"use client";

import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";

import { warnOnce } from "../lib/warn-once";

/** A new value, or a function of the previous one (like `setState`). */
export type ControllableUpdate<T> = T | ((prev: T) => T);

/**
 * One controlled/uncontrolled state hook for every SheenUI component. `value` controls it (only `undefined`
 * means uncontrolled, so `null` is a valid controlled value); otherwise `defaultValue` seeds internal state.
 * The setter accepts a value or an updater, skips a value equal to the current one (`Object.is`, so
 * `onChange` never fires for a no-op) and is referentially stable. Uncontrolled, chained updates in one tick build
 * on each other; controlled, every request is compared with the current `value` prop and reported, so an owner that
 * rejects a change is asked again on the next attempt.
 * Returns `[value, set, ref]`, where `ref.current` is the latest value for event handlers. A component must stay
 * controlled or uncontrolled for its whole life: the internal state is not carried across a switch, and development
 * builds print a one-time warning when it happens.
 *
 * @example
 * ```tsx
 * import { useControllable } from "@sheenui/theme";
 *
 * function Counter({ value, onChange }: { value?: number; onChange?: (next: number) => void }) {
 *   const [count, setCount] = useControllable(value, 0, onChange);
 *   return <button type="button" onClick={() => setCount((n) => n + 1)}>{count}</button>;
 * }
 * ```
 *
 * @see /foundations
 */
export function useControllable<T>(value: T | undefined, defaultValue: T | (() => T), onChange?: (next: T) => void) {
  const [inner, setInner] = useState(defaultValue);
  const controlled = value !== undefined;
  const current = controlled ? value : inner;
  const ref = useRef(current);
  const wasControlled = useRef(controlled);
  useEffect(() => {
    if (wasControlled.current !== controlled) {
      warnOnce(
        controlled
          ? "A component changed from uncontrolled to controlled: `value` was undefined and is now set. Pick one for the component's whole life."
          : "A component changed from controlled to uncontrolled: `value` was set and is now undefined. Pass `null`/a value, or switch to `defaultValue` from the start.",
      );
      wasControlled.current = controlled;
    }
  }, [controlled]);
  const onChangeRef = useRef(onChange);
  useLayoutEffect(() => {
    ref.current = current;
    onChangeRef.current = onChange;
  });
  const set = useCallback(
    (update: ControllableUpdate<T>) => {
      const next = typeof update === "function" ? (update as (prev: T) => T)(ref.current) : update;
      if (Object.is(next, ref.current)) return;
      // Controlled: never remember the request. `ref.current` stays the prop value until the owner commits a new one,
      // so a rejected change is reported again the next time (and an updater never builds on a value that was never shown).
      if (!controlled) {
        ref.current = next;
        setInner(next);
      }
      onChangeRef.current?.(next);
    },
    [controlled],
  );
  return [current, set, ref] as const;
}

"use client";

import { useSyncExternalStore, type RefObject } from "react";
import { useDirection } from "@base-ui/react/direction-provider";

type Direction = "ltr" | "rtl";

/**
 * ONE MutationObserver for every component that follows the text direction. Flipping `dir` at runtime, on the root or
 * on any ancestor, mirrors a layout without resizing it, so no ResizeObserver fires: this is the cue. Listeners are
 * the components' own (coalesced) read functions; the observer exists only while someone listens.
 *
 * @internal Subscribe from an effect or `useSyncExternalStore`; it returns the unsubscribe function.
 * @example
 * ```tsx
 * import { useEffect, useState } from "react";
 * import { watchDirection } from "./use-direction";
 *
 * export function DirectionLabel() {
 *   const [dir, setDir] = useState(() => document.documentElement.dir || "ltr");
 *   useEffect(() => watchDirection(() => setDir(document.documentElement.dir || "ltr")), []);
 *   return <span>{dir}</span>;
 * }
 * ```
 *
 * @see /components
 */
export function watchDirection(listener: () => void) {
  directionListeners.add(listener);
  if (!directionObserver && typeof MutationObserver !== "undefined") {
    directionObserver = new MutationObserver(() => directionListeners.forEach((fn) => fn()));
    directionObserver.observe(document.documentElement, { attributes: true, attributeFilter: ["dir"], subtree: true });
  }
  return () => {
    directionListeners.delete(listener);
    if (directionListeners.size === 0) {
      directionObserver?.disconnect();
      directionObserver = null;
    }
  };
}
const directionListeners = new Set<() => void>();
let directionObserver: MutationObserver | null = null;

/** The direction in force at `element`: its nearest `dir` ancestor (itself included), `ltr` when there is none. */
function directionAt(element: Element | null): Direction {
  const node = element ? element.closest("[dir]") : document.documentElement;
  return (node ?? document.documentElement).getAttribute("dir") === "rtl" ? "rtl" : "ltr";
}

/**
 * Event-time direction read for key handlers: is `element` laid out right-to-left right now? One computed-style read, no
 * ref and no subscription, so a runtime `dir` flip is seen on the next key press. Prefer `useResolvedDirection` for
 * anything that renders differently per direction.
 *
 * @internal Arrow-key handlers that swap Left/Right in right-to-left text.
 * @example
 * ```tsx
 * import { isRtlAt } from "./use-direction";
 *
 * export function Stepper() {
 *   return (
 *     <div
 *       role="group"
 *       aria-label="Steps"
 *       onKeyDown={(event) => {
 *         const forward = isRtlAt(event.currentTarget) ? "ArrowLeft" : "ArrowRight";
 *         if (event.key === forward) event.preventDefault();
 *       }}
 *     />
 *   );
 * }
 * ```
 *
 * @see /components
 */
export function isRtlAt(element: Element): boolean {
  return getComputedStyle(element).direction === "rtl";
}

/**
 * The ONE place a component learns the text direction (for logical sides, mirrored scroll maths, a mirrored pill).
 * Order: the `direction` prop if given, then Base UI's `DirectionProvider` (`rtl`), then the nearest `dir` ancestor of
 * `ref`'s element, else `<html dir>`. Live: a runtime `dir` flip re-renders the caller (single shared observer), and
 * it is `ltr` on the server. Pass `ref` for anything rendered inside the page (a calendar, a tab list, a chart); leave
 * it out for portalled surfaces (Drawer, Toaster), which sit under `<body>` and follow the provider or `<html dir>`.
 * Key handlers call `isRtlAt(event.currentTarget)` at event time instead: no ref, no subscription.
 *
 * @internal Used by every component that mirrors itself in right-to-left text.
 * @example
 * ```tsx
 * import { useRef } from "react";
 * import { useResolvedDirection } from "./use-direction";
 *
 * export function Edge() {
 *   const ref = useRef<HTMLSpanElement>(null);
 *   const left = useResolvedDirection(undefined, ref) === "ltr";
 *   return <span ref={ref}>{left ? "start is the left edge" : "start is the right edge"}</span>;
 * }
 * ```
 *
 * @see /components
 */
export function useResolvedDirection(prop?: Direction, ref?: RefObject<Element | null>): Direction {
  const provided = useDirection();
  const found = useSyncExternalStore(
    watchDirection,
    () => directionAt(ref?.current ?? null),
    () => "ltr" as const,
  );
  return prop ?? (provided === "rtl" ? "rtl" : found);
}

/**
 * Watches `element` with one IntersectionObserver and calls `onChange` with the latest entry each time its
 * visibility changes (including the first report). Returns the cleanup function; a no-op where
 * IntersectionObserver does not exist (old browsers, test environments), so callers keep their own default
 * state for that case. The one place the library creates a single-target observer for pause-off-screen loops.
 *
 * @internal Call from an effect and return the result as its cleanup.
 * @example
 * ```tsx
 * import { useEffect, useRef, useState } from "react";
 * import { observeIntersection } from "./use-intersection";
 *
 * export function Seen() {
 *   const ref = useRef<HTMLDivElement>(null);
 *   const [seen, setSeen] = useState(false);
 *   useEffect(() => {
 *     const el = ref.current;
 *     return el ? observeIntersection(el, (entry) => setSeen(entry.isIntersecting)) : undefined;
 *   }, []);
 *   return <div ref={ref}>{seen ? "in view" : "off screen"}</div>;
 * }
 * ```
 *
 * @see /components
 */
export function observeIntersection(
  element: Element,
  onChange: (entry: IntersectionObserverEntry) => void,
  options?: IntersectionObserverInit,
): () => void {
  if (typeof IntersectionObserver === "undefined") return () => undefined;
  const observer = new IntersectionObserver((entries) => {
    const entry = entries[entries.length - 1];
    if (entry) onChange(entry);
  }, options);
  observer.observe(element);
  return () => observer.disconnect();
}

"use client";

import { useLayoutEffect, useRef } from "react";

/**
 * A ref that always holds the latest `value`, for stable callbacks that must read current props or state
 * without becoming dependencies. The ref is updated in a layout effect after each commit (never during
 * render, so it is StrictMode-, concurrent- and React Compiler-safe). Read `ref.current` only inside event
 * handlers, effects and animation frames, never while rendering. Prefer `useEffectEvent` when the callback
 * is only called from an effect; use this when the callback is passed to children or other hooks.
 *
 * @example
 * ```tsx
 * import { useLatest } from "@sheenui/theme";
 *
 * function Logger({ count }: { count: number }) {
 *   const latestRef = useLatest(count);
 *   return <button type="button" onClick={() => console.log(latestRef.current)}>Log</button>;
 * }
 * ```
 *
 * @see /components
 */
export function useLatest<T>(value: T) {
  const ref = useRef(value);
  useLayoutEffect(() => {
    ref.current = value;
  });
  return ref;
}

/**
 * Keeps an existing `ref` in step with `value`: the same layout-effect update as `useLatest`, for when the
 * ref is declared earlier (for example because a lazy initialiser closes over it). Never writes during render.
 *
 * @example
 * ```tsx
 * import { useRef } from "react";
 * import { useSyncRef } from "@sheenui/theme";
 *
 * function Logger({ count }: { count: number }) {
 *   const ref = useRef(count);
 *   useSyncRef(ref, count);
 *   return <button type="button" onClick={() => console.log(ref.current)}>Log</button>;
 * }
 * ```
 *
 * @see /components
 */
export function useSyncRef<T>(ref: { current: T }, value: T) {
  useLayoutEffect(() => {
    ref.current = value;
  });
}

"use client";

import { useEffect, type RefObject } from "react";
import { useMotionValue, useSpring } from "motion/react";

import { useMotionGate } from "../motion/gate";
import { distance, follow } from "../motion/tokens";

/** Options of {@link useMagnetic}. */
export type UseMagneticOptions = {
  /**
   * Turn the pull on or off (a disabled or loading button passes `false`).
   * @default true
   */
  enabled?: boolean;
  /**
   * How far outside the element's box (px) the pointer already pulls it.
   * @default 8
   */
  reach?: number;
  /**
   * Share of the pointer's offset from the element's centre that becomes movement (0 to 1); the result is capped at `distance.magneticMax`.
   * @default 0.25
   */
  strength?: number;
};

/**
 * Magnetic pull: the element leans toward the pointer while the pointer is
 * within `reach` px of its box, by at most `distance.magneticMax` px, on the `follow.magnetic` spring, and springs
 * home when the pointer leaves. Two MotionValues write `transform` straight to the element, so nothing re-renders
 * per frame; one passive document listener does the tracking, and a new target mid-flight keeps the spring's
 * velocity (interruptible). The element's own `translate` and `scale` (hover lift, press) are left alone.
 * Off for touch screens, for reduced motion (OS or in-app) and while `enabled` is false.
 *
 * Keyboard: None: pointer only; keyboard focus never moves the element.
 * Accessibility: The pull is at most 8 px and never moves the click target out from under the pointer; it is removed with reduced motion.
 * Motion: Spring `follow.magnetic`, cap `distance.magneticMax`; compositor `transform` only.
 *
 * @example
 * ```tsx
 * import { useRef } from "react";
 * import { useMagnetic } from "@sheenui/theme";
 *
 * export function Pull() {
 *   const ref = useRef<HTMLAnchorElement>(null);
 *   useMagnetic(ref);
 *   return <a ref={ref} href="/start">Get started</a>;
 * }
 * ```
 *
 * @see /foundations
 */
export function useMagnetic(
  ref: RefObject<HTMLElement | null>,
  { enabled = true, reach = 8, strength = 0.25 }: UseMagneticOptions = {},
) {
  const { pointerFx } = useMotionGate();
  const pullX = useMotionValue(0);
  const pullY = useMotionValue(0);
  const x = useSpring(pullX, follow.magnetic);
  const y = useSpring(pullY, follow.magnetic);
  const on = enabled && pointerFx;

  useEffect(() => {
    const el = ref.current;
    if (!el || !on) return;
    const write = () => {
      const px = x.get();
      const py = y.get();
      el.style.transform =
        Math.abs(px) < 0.05 && Math.abs(py) < 0.05 ? "" : `translate3d(${px.toFixed(2)}px,${py.toFixed(2)}px,0)`;
    };
    const stopX = x.on("change", write);
    const stopY = y.on("change", write);

    const max = distance.magneticMax;
    // Symmetric about zero (`-max` to `max`), so it stays local rather than calling `lib/math`'s `clamp(n, lo, hi)`.
    const clamp = (v: number) => Math.max(-max, Math.min(max, v));
    let box: DOMRect | null = null;
    let frame = 0;
    let last: { x: number; y: number } | null = null;
    const stale = () => {
      box = null;
    };
    const flush = () => {
      frame = 0;
      if (!last) return;
      // The box is read at most once per scroll / resize, never per move. It is the element's resting box:
      // the pull is a transform, so the cached rect is shifted by the current pull before use.
      box ??= el.getBoundingClientRect();
      const cx = box.left + box.width / 2 - x.get();
      const cy = box.top + box.height / 2 - y.get();
      const hw = box.width / 2 + reach;
      const hh = box.height / 2 + reach;
      const dx = last.x - cx;
      const dy = last.y - cy;
      if (Math.abs(dx) <= hw && Math.abs(dy) <= hh) {
        pullX.set(clamp(dx * strength));
        pullY.set(clamp(dy * strength));
      } else {
        pullX.set(0);
        pullY.set(0);
      }
    };
    const move = (event: PointerEvent) => {
      if (event.pointerType === "touch") return;
      last = { x: event.clientX, y: event.clientY };
      frame ||= requestAnimationFrame(flush);
    };
    const leave = () => {
      last = null;
      pullX.set(0);
      pullY.set(0);
    };
    document.addEventListener("pointermove", move, { passive: true });
    document.documentElement.addEventListener("pointerleave", leave);
    window.addEventListener("scroll", stale, { passive: true, capture: true });
    window.addEventListener("resize", stale, { passive: true });
    return () => {
      document.removeEventListener("pointermove", move);
      document.documentElement.removeEventListener("pointerleave", leave);
      window.removeEventListener("scroll", stale, { capture: true });
      window.removeEventListener("resize", stale);
      cancelAnimationFrame(frame);
      stopX();
      stopY();
      pullX.jump(0);
      pullY.jump(0);
      el.style.transform = "";
    };
  }, [ref, on, reach, strength, x, y, pullX, pullY]);
}

"use client";

import { useCallback, useSyncExternalStore } from "react";

/** The one touch query SheenUI uses: any coarse pointer (a touch laptop with a mouse counts as touch-capable). */
export const COARSE_POINTER_QUERY = "(any-pointer: coarse)";
/** The OS dark colour scheme query. */
export const PREFERS_DARK_QUERY = "(prefers-color-scheme: dark)";

/** True while the OS asks for solid surfaces: reduced transparency, more contrast or forced colours. */
export const SOLID_GLASS_QUERY =
  "(prefers-reduced-transparency: reduce), (prefers-contrast: more), (forced-colors: active)";
/** A phone-width viewport: just under Tailwind's `sm` (640px). Pickers, toasts and the chat widget switch to their phone layouts under it. */
export const PHONE_QUERY = "(max-width: 639.98px)";
/** A mouse or trackpad: hover and a fine pointer. */
export const FINE_POINTER_QUERY = "(hover: hover) and (pointer: fine)";
/** The OS asks for reduced motion. */
export const REDUCED_MOTION_QUERY = "(prefers-reduced-motion: reduce)";

const canMatch = () => typeof window !== "undefined" && typeof window.matchMedia === "function";

/** One MediaQueryList per query: a snapshot read must not allocate a new list every call. */
const lists = new Map<string, MediaQueryList>();
let listsOwner: unknown = null;
function listFor(query: string) {
  // A replaced `window.matchMedia` (a test double, a polyfill) starts a fresh cache.
  const current: unknown = Reflect.get(window, "matchMedia");
  if (listsOwner !== current) {
    lists.clear();
    listsOwner = current;
  }
  let list = lists.get(query);
  if (!list) {
    list = window.matchMedia(query);
    lists.set(query, list);
  }
  return list;
}

/**
 * Whether a CSS media query currently matches, kept live with `useSyncExternalStore`. It is `serverValue`
 * (default `false`) on the server and during hydration, so prerendered markup never mismatches.
 *
 * - `enabled: false` skips the subscription and returns `false`.
 *
 * @example
 * ```tsx
 * import { useMediaQuery } from "@sheenui/theme";
 *
 * function Layout() {
 *   const wide = useMediaQuery("(min-width: 768px)");
 *   return <p>{wide ? "Wide" : "Narrow"}</p>;
 * }
 * ```
 *
 * @see /foundations
 */
export function useMediaQuery(query: string, options: { serverValue?: boolean; enabled?: boolean } = {}) {
  const { serverValue = false, enabled = true } = options;
  // Stable per query, so React does not unsubscribe and resubscribe on every render.
  const subscribe = useCallback(
    (notify: () => void) => {
      if (!enabled || !canMatch()) return () => undefined;
      const list = listFor(query);
      list.addEventListener("change", notify);
      return () => list.removeEventListener("change", notify);
    },
    [query, enabled],
  );
  return useSyncExternalStore(
    subscribe,
    () => enabled && canMatch() && listFor(query).matches,
    () => serverValue,
  );
}

/**
 * True on devices with a coarse pointer (touch). One query, `(any-pointer: coarse)`, everywhere in SheenUI, so a
 * chart, a carousel and a tooltip never disagree about what "touch" means. `false` on the server.
 *
 * @example
 * ```tsx
 * import { useCoarsePointer } from "@sheenui/theme";
 *
 * function Hint() {
 *   return <p>{useCoarsePointer() ? "Tap to select" : "Click to select"}</p>;
 * }
 * ```
 *
 * @see /foundations
 */
export function useCoarsePointer() {
  return useMediaQuery(COARSE_POINTER_QUERY);
}

/**
 * True when the OS prefers a dark colour scheme. `false` on the server. To follow the app's own theme switch as well,
 * use `usePreferences` from the same package.
 *
 * @example
 * ```tsx
 * import { usePrefersDark } from "@sheenui/theme";
 *
 * function Mode() {
 *   return <p>{usePrefersDark() ? "Dark" : "Light"}</p>;
 * }
 * ```
 *
 * @see /foundations
 */
export function usePrefersDark() {
  return useMediaQuery(PREFERS_DARK_QUERY);
}

/**
 * True when the OS asks for solid surfaces (reduced transparency, more contrast or forced colours).
 * Live. Use it to skip decorative blur or canvas work that solid surfaces would hide anyway.
 *
 * Accessibility: This is the signal behind SheenUI's reduced-transparency and forced-colors fallbacks.
 * Glass: Mirrors the media queries `prefers-reduced-transparency`, `prefers-contrast: more` and `forced-colors: active`.
 *
 * @example
 * ```tsx
 * import { useOsSolidGlass } from "@sheenui/theme";
 *
 * export function Sparkles() {
 *   const solid = useOsSolidGlass();
 *   return solid ? null : <div className="sparkles" />;
 * }
 * ```
 *
 * @see /foundations
 */
export function useOsSolidGlass() {
  return useMediaQuery(SOLID_GLASS_QUERY);
}

"use client";

import { useCallback, useSyncExternalStore } from "react";

import { REDUCED_MOTION_QUERY, useMediaQuery } from "./use-media-query";

/**
 * User preferences, stored as data-attributes on <html> (so CSS can react)
 * and in localStorage (so they survive reloads and sync across tabs).
 *
 *   data-theme         "light" | "dark"          (absent = follow OS)
 *   data-motion        "reduced"                 (absent = full motion)
 *   data-transparency  "reduced"                 (absent = glass)
 *   data-glass         "lite" | "full"           (absent = full blur; "full" = the visitor turned
 *                                                 Lite off, so automatic Lite glass stays off)
 *   data-sheen-style   "liquid" | "aurora"       (absent = "liquid", the default style preset)
 *
 * Inline `sheenPreferenceScript` in <head> so the attributes are set before first paint.
 */

type Pref = "theme" | "motion" | "transparency" | "glass" | "style";

const PREFS: readonly Pref[] = ["theme", "motion", "transparency", "glass", "style"];
const STORAGE_PREFIX = "sheen:";

/** The attribute each preference lives in on <html>. */
const ATTR: Record<Pref, string> = {
  theme: "data-theme",
  motion: "data-motion",
  transparency: "data-transparency",
  glass: "data-glass",
  style: "data-sheen-style",
};

/* ---------- Style presets ---------- */

/**
 * SheenUI's style presets. Each one is a layer of tokens (backdrop, glass recipe, rim light,
 * accent palette, display type, motion intensity) over the same components:
 *   - "liquid"  Liquid Glass (default): thick clear glass over silk ribbons and glossy spheres.
 *   - "aurora"  Aurora Neon: frosted glass with glowing rims under a moving aurora sky.
 */
export const SHEEN_STYLES = ["liquid", "aurora"] as const;
/** The two style presets: `liquid` (Liquid Glass) and `aurora` (Aurora Neon). */
export type SheenStyle = (typeof SHEEN_STYLES)[number];
/** The style preset used when nothing is saved: `liquid`. */
export const DEFAULT_SHEEN_STYLE: SheenStyle = "liquid";

/**
 * Type guard: true when `value` is one of `SHEEN_STYLES`. Pure; no DOM access, so it is safe to call
 * on the server.
 */
export function isSheenStyle(value: unknown): value is SheenStyle {
  return typeof value === "string" && (SHEEN_STYLES as readonly string[]).includes(value);
}

/* ---------- Store ---------- */

function read(pref: Pref): string | null {
  if (typeof document === "undefined") return null;
  return document.documentElement.getAttribute(ATTR[pref]);
}

function apply(pref: Pref, value: string | null) {
  const root = document.documentElement;
  if (value === null) root.removeAttribute(ATTR[pref]);
  else root.setAttribute(ATTR[pref], value);
}

function write(pref: Pref, value: string | null) {
  apply(pref, value);
  try {
    if (value === null) localStorage.removeItem(STORAGE_PREFIX + pref);
    else localStorage.setItem(STORAGE_PREFIX + pref, value);
  } catch {
    /* storage can be blocked (private mode); the attribute still applies */
  }
}

/*
 * One store for every consumer: a single MutationObserver on <html> (plus one
 * `storage` listener for other tabs) fans out to a set of listeners. It is created
 * for the first subscriber and torn down after the last one leaves, so a page with
 * twenty preference-aware components still has exactly one observer.
 */
const listeners = new Set<() => void>();
let observer: MutationObserver | null = null;

function emit() {
  for (const listener of listeners) listener();
}

/** Another tab changed a preference: mirror it here. The observer then notifies listeners. */
function onStorage(event: StorageEvent) {
  if (!event.key?.startsWith(STORAGE_PREFIX)) return;
  const pref = event.key.slice(STORAGE_PREFIX.length) as Pref;
  if (!PREFS.includes(pref)) return;
  if (pref === "style") apply(pref, isSheenStyle(event.newValue) ? event.newValue : DEFAULT_SHEEN_STYLE);
  else apply(pref, event.newValue);
}

function subscribe(listener: () => void) {
  listeners.add(listener);
  if (!observer) {
    observer = new MutationObserver(emit);
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: PREFS.map((pref) => ATTR[pref]),
    });
    window.addEventListener("storage", onStorage);
  }
  return () => {
    listeners.delete(listener);
    if (listeners.size === 0 && observer) {
      observer.disconnect();
      observer = null;
      window.removeEventListener("storage", onStorage);
    }
  };
}

/** Server snapshot: no attributes exist yet (SSR / prerender). */
const serverSnapshot = () => null;

function usePref(pref: Pref) {
  const value = useSyncExternalStore(subscribe, () => read(pref), serverSnapshot);
  const set = useCallback((next: string | null) => write(pref, next), [pref]);
  return [value, set] as const;
}

/** The theme a visitor can pick: `light`, `dark` or `system` (follow the OS). */
export type ThemeChoice = "light" | "dark" | "system";

/**
 * The visitor's colour theme and a setter that saves it (`data-theme` on `<html>` plus localStorage,
 * synced across tabs). `"system"` removes the attribute so the OS preference wins.
 * Returns `{ theme, setTheme }`; `theme` is `"light" | "dark" | "system"` and is `"system"` on the server.
 *
 * Accessibility: Pair the control with a visible label or `aria-pressed`; the hook has no UI.
 *
 * @example
 * ```tsx
 * import { useTheme } from "@sheenui/theme";
 *
 * export function ThemeButton() {
 *   const { theme, setTheme } = useTheme();
 *   return <button onClick={() => setTheme(theme === "dark" ? "light" : "dark")}>Theme: {theme}</button>;
 * }
 * ```
 *
 * @see /foundations
 */
export function useTheme() {
  const [value, set] = usePref("theme");
  const theme: ThemeChoice = value === "light" || value === "dark" ? value : "system";
  const setTheme = useCallback((t: ThemeChoice) => set(t === "system" ? null : t), [set]);
  return { theme, setTheme };
}

/**
 * The in-app "reduce transparency" switch: `[on, setOn]`. When on (`data-transparency="reduced"` on
 * `<html>`), glass surfaces turn solid. Saved in localStorage and synced across tabs; `false` on the server.
 *
 * Accessibility: Honours the OS "reduce transparency" setting in CSS as well; this is the manual override.
 *
 * @example
 * ```tsx
 * import { useReducedTransparency } from "@sheenui/theme";
 *
 * export function SolidToggle() {
 *   const [solid, setSolid] = useReducedTransparency();
 *   return <label><input type="checkbox" checked={solid} onChange={(e) => setSolid(e.target.checked)} /> Solid surfaces</label>;
 * }
 * ```
 *
 * @see /foundations
 */
export function useReducedTransparency() {
  const [value, set] = usePref("transparency");
  const setReduced = useCallback((on: boolean) => set(on ? "reduced" : null), [set]);
  return [value === "reduced", setReduced] as const;
}

/**
 * The in-app "reduce motion" switch: `[on, setOn]` (`data-motion="reduced"` on `<html>`, saved in
 * localStorage, synced across tabs; `false` on the server). It is the manual switch only: use
 * `useSheenReducedMotion` for "OS setting OR this switch".
 *
 * Accessibility: Reduced motion keeps opacity feedback and drops movement, scaling and loops.
 *
 * @example
 * ```tsx
 * import { useMotionPreference } from "@sheenui/theme";
 *
 * export function MotionToggle() {
 *   const [reduced, setReduced] = useMotionPreference();
 *   return <button aria-pressed={reduced} onClick={() => setReduced(!reduced)}>Reduce motion</button>;
 * }
 * ```
 *
 * @see /foundations
 */
export function useMotionPreference() {
  const [value, set] = usePref("motion");
  const setReduced = useCallback((on: boolean) => set(on ? "reduced" : null), [set]);
  return [value === "reduced", setReduced] as const;
}

/**
 * Lite glass: cheaper blur and a calmer backdrop for weak devices. Turned on automatically
 * (see useAutoLiteGlass in the backdrop) unless the visitor made a choice; turning it off saves
 * "full", so it stays off on the next visit. Returns `[lite, setLite]`; `false` on the server.
 *
 * Accessibility: Lite glass changes blur and backdrop only; contrast and layout stay the same.
 *
 * @example
 * ```tsx
 * import { useGlassMode } from "@sheenui/theme";
 *
 * export function LiteToggle() {
 *   const [lite, setLite] = useGlassMode();
 *   return <button aria-pressed={lite} onClick={() => setLite(!lite)}>Lite glass</button>;
 * }
 * ```
 *
 * @see /foundations
 */
export function useGlassMode() {
  const [value, set] = usePref("glass");
  const setLite = useCallback((on: boolean) => set(on ? "lite" : "full"), [set]);
  return [value === "lite", setLite] as const;
}

/**
 * The active style preset (`"liquid"` by default, or `"aurora"`) and a setter that saves it
 * (`data-sheen-style` on `<html>` plus localStorage, synced across tabs). `"liquid"` on the server.
 * Returns `{ style, setStyle }`.
 *
 * Accessibility: The presets share the same contrast targets; this hook has no UI of its own.
 *
 * @example
 * ```tsx
 * import { useSheenStyle } from "@sheenui/theme";
 *
 * export function StyleSwitch() {
 *   const { style, setStyle } = useSheenStyle();
 *   return <button onClick={() => setStyle(style === "liquid" ? "aurora" : "liquid")}>Style: {style}</button>;
 * }
 * ```
 *
 * @see /foundations
 */
export function useSheenStyle() {
  const [value, set] = usePref("style");
  const style: SheenStyle = isSheenStyle(value) ? value : DEFAULT_SHEEN_STYLE;
  const setStyle = useCallback((next: SheenStyle) => set(next), [set]);
  return { style, setStyle };
}

/** The active style preset outside React (reads <html>; "liquid" on the server). */
export function readSheenStyle(): SheenStyle {
  const value = read("style");
  return isSheenStyle(value) ? value : DEFAULT_SHEEN_STYLE;
}

/* ---------- Reduced motion (live) ---------- */

/**
 * True when the OS asks for reduced motion OR the in-app toggle is on.
 * Live: it subscribes to the media query (Motion's useReducedMotion reads the OS setting
 * once per mount, so a change in system settings would be missed until a reload).
 * `false` on the server.
 *
 * Accessibility: Follows `prefers-reduced-motion` live and the in-app switch; branch every non-essential animation on it.
 *
 * @example
 * ```tsx
 * import { useSheenReducedMotion } from "@sheenui/theme";
 *
 * export function Pulse() {
 *   const reduced = useSheenReducedMotion();
 *   return <span className={reduced ? "" : "animate-pulse"}>Live</span>;
 * }
 * ```
 *
 * @see /foundations
 */
export function useSheenReducedMotion() {
  const os = useMediaQuery(REDUCED_MOTION_QUERY);
  const [app] = useMotionPreference();
  return os || app;
}

/**
 * Inline this in <head> (before your CSS) to apply saved preferences with no flash.
 * The style preset is always set (the saved one, or "liquid"), so CSS can rely on it.
 */
export const sheenPreferenceScript = `(function(){try{var r=document.documentElement;${JSON.stringify(PREFS.filter((pref) => pref !== "style"))}.forEach(function(k){var v=localStorage.getItem("${STORAGE_PREFIX}"+k);if(v)r.setAttribute("data-"+k,v);});var s=localStorage.getItem("${STORAGE_PREFIX}style");r.setAttribute("data-sheen-style",${SHEEN_STYLES.map((style) => `s===${JSON.stringify(style)}`).join("||")}?s:${JSON.stringify(DEFAULT_SHEEN_STYLE)});}catch(e){document.documentElement.setAttribute("data-sheen-style",${JSON.stringify(DEFAULT_SHEEN_STYLE)});}})();`;

"use client";

import { usePrefersDark } from "./use-media-query";
import { useTheme } from "./use-preferences";

/**
 * The ONE place the colour scheme actually on screen is resolved: the saved theme, or the OS setting while it is
 * "system". Live: it updates when the person switches theme or the OS flips. Server render returns "light" for
 * "system" until hydration. Public `useResolvedTheme` and the charts' `useDarkScheme` both read it.
 *
 * @internal Use it for effects CSS cannot switch by theme (blend modes, canvas colours); colours come from `--sheen-*` tokens.
 * @example
 * ```tsx
 * import { useResolvedScheme } from "./use-resolved-scheme";
 *
 * export function Label() {
 *   return <span>{useResolvedScheme() === "dark" ? "Night" : "Day"}</span>;
 * }
 * ```
 *
 * @see /foundations
 */
export function useResolvedScheme(): "light" | "dark" {
  const { theme } = useTheme();
  const osDark = usePrefersDark();
  return theme === "system" ? (osDark ? "dark" : "light") : theme;
}

"use client";

import { useCallback, useLayoutEffect, useRef, useState } from "react";

import { useLatest } from "./use-latest";

/** Lists longer than this are windowed on their own (`virtualized="auto"`): Select, Combobox and CommandPalette. */
export const VIRTUALIZE_THRESHOLD = 200;

/** Whether a long list is windowed: `true` / `false` force it, `"auto"` (the default) windows lists over {@link VIRTUALIZE_THRESHOLD} rows. */
export function shouldVirtualize(virtualized: boolean | "auto" | undefined, count: number) {
  return virtualized === true || ((virtualized ?? "auto") === "auto" && count > VIRTUALIZE_THRESHOLD);
}

/** Options of {@link useVirtualWindow}. */
export type UseVirtualWindowOptions = {
  /**
   * How many rows the list has (headings included).
   */
  count: number;
  /**
   * Turn the window off: every row is reported as visible (the list renders fully).
   *
   * @default true
   */
  enabled?: boolean;
  /**
   * Row height in px before the first row has been measured. Rows must all be this tall (give them a fixed height and
   * mark each with `data-vrow`); the real height is read from the first one, so touch sizes need no extra work.
   *
   * @default 40
   */
  estimateSize?: number;
  /**
   * Rows rendered beyond each edge of the viewport, so a fast scroll or a held arrow key never shows a gap.
   *
   * @default 8
   */
  overscan?: number;
  /**
   * Viewport height in px used while the scroll element has no layout yet (server rendering, a closed popup).
   *
   * @default 320
   */
  fallbackViewport?: number;
};

/** What {@link useVirtualWindow} returns. */
export type VirtualWindow = {
  /** Pass to the scroll container's `ref`. */
  ref: (element: HTMLElement | null) => void;
  /** The scroll container once it is mounted (a popup's list mounts when it opens), `null` before. */
  element: HTMLElement | null;
  /** First row to render (inclusive). */
  start: number;
  /** End of the rendered rows (exclusive). */
  end: number;
  /** Height of one row in px (measured). */
  size: number;
  /** Height of the whole list in px: spacers keep the scroll bar and the layout exactly as if every row existed. */
  totalSize: number;
  /** Space above the rendered rows, in px. */
  padStart: number;
  /** Space below the rendered rows, in px. */
  padEnd: number;
  /** Scrolls the row into view (`"nearest"` by default) and renders it in the same frame. */
  scrollToIndex: (index: number, align?: "nearest" | "start" | "center") => void;
};

/**
 * A small windowing hook for long lists of equally tall rows: it reports which rows are near the viewport so a list
 * of thousands renders only a few dozen elements. Select, Combobox and CommandPalette use it for `virtualized` lists.
 * Attach `ref` to the scrolling element, render rows `start` to `end` between two spacers of `padStart` and
 * `padEnd` px (or inside a box `totalSize` tall) and give each row a fixed height and a `data-vrow` attribute.
 *
 * Keyboard: none of its own; call `scrollToIndex` when your own keyboard handling moves the active row, and put
 * `aria-setsize` / `aria-posinset` on the rows so screen readers still hear "3 of 5000".
 * Accessibility: windowed rows are removed from the DOM, so the active row must be scrolled into view (and so
 * rendered) before something points at it with `aria-activedescendant`.
 *
 * @example
 * ```tsx
 * import { useVirtualWindow } from "@sheenui/theme";
 *
 * const rows = Array.from({ length: 5000 }, (_, i) => `Row ${i + 1}`);
 *
 * export function LongList() {
 *   const win = useVirtualWindow({ count: rows.length, estimateSize: 32 });
 *   return (
 *     <div ref={win.ref} className="h-64 overflow-y-auto">
 *       <div style={{ paddingTop: win.padStart, paddingBottom: win.padEnd }}>
 *         {rows.slice(win.start, win.end).map((row) => (
 *           <div key={row} data-vrow="" style={{ height: win.size }}>
 *             {row}
 *           </div>
 *         ))}
 *       </div>
 *     </div>
 *   );
 * }
 * ```
 *
 * @see /components/select
 */
export function useVirtualWindow({
  count,
  enabled = true,
  estimateSize = 40,
  overscan = 8,
  fallbackViewport = 320,
}: UseVirtualWindowOptions): VirtualWindow {
  const [element, setElement] = useState<HTMLElement | null>(null);
  const [scrollTop, setScrollTop] = useState(0);
  const [viewport, setViewport] = useState(fallbackViewport);
  const [size, setSize] = useState(estimateSize);
  const elementRef = useRef<HTMLElement | null>(null);
  const sizeRef = useLatest(size);

  const ref = useCallback((node: HTMLElement | null) => {
    elementRef.current = node;
    setElement(node);
  }, []);

  useLayoutEffect(() => {
    if (!element || !enabled) return;
    let frame = 0;
    const read = () => {
      frame = 0;
      setScrollTop(element.scrollTop);
      setViewport(element.clientHeight || fallbackViewport);
    };
    const schedule = () => {
      if (!frame) frame = requestAnimationFrame(read);
    };
    read();
    element.addEventListener("scroll", schedule, { passive: true });
    const observer = typeof ResizeObserver === "undefined" ? null : new ResizeObserver(schedule);
    observer?.observe(element);
    return () => {
      if (frame) cancelAnimationFrame(frame);
      element.removeEventListener("scroll", schedule);
      observer?.disconnect();
    };
  }, [element, enabled, fallbackViewport]);

  // The real row height (touch sizes, density) is read from the first rendered row.
  useLayoutEffect(() => {
    if (!element || !enabled) return;
    const row = element.querySelector<HTMLElement>("[data-vrow]");
    // Layout height, not the painted one: a popup that is scaling in would read 4% short.
    const height = row?.offsetHeight ?? 0;
    if (height > 0 && Math.abs(height - sizeRef.current) > 0.5) setSize(height);
  }, [element, enabled, count, sizeRef]);

  const total = Math.max(0, count);
  const rowSize = Math.max(1, size);
  let start = 0;
  let end = total;
  if (enabled) {
    start = Math.max(0, Math.floor(scrollTop / rowSize) - overscan);
    end = Math.min(total, Math.ceil((scrollTop + viewport) / rowSize) + overscan);
    if (end < start) end = start;
  }

  const scrollToIndex = useCallback(
    (index: number, align: "nearest" | "start" | "center" = "nearest") => {
      const node = elementRef.current;
      if (!node) return;
      const rowHeight = Math.max(1, sizeRef.current);
      const view = node.clientHeight || fallbackViewport;
      const top = index * rowHeight;
      const bottom = top + rowHeight;
      let next = node.scrollTop;
      if (align === "start") next = top;
      else if (align === "center") next = top - (view - rowHeight) / 2;
      else if (top < next) next = top;
      else if (bottom > next + view) next = bottom - view;
      next = Math.max(0, next);
      if (next !== node.scrollTop) node.scrollTop = next;
      setScrollTop(next);
      setViewport(view);
    },
    [fallbackViewport, sizeRef],
  );

  return {
    ref,
    element,
    start,
    end,
    size: rowSize,
    totalSize: total * rowSize,
    padStart: start * rowSize,
    padEnd: Math.max(0, total - end) * rowSize,
    scrollToIndex,
  };
}

"use client";

/**
 * Small helpers shared by the canvas and scattered-element effects (Particles, Confetti, Meteors): how many
 * pieces a device can afford, a seeded random source so server and client markup agree, and a way to read a
 * `--sheen-*` token as a colour a canvas can paint with.
 */

import { useSyncExternalStore } from "react";

type DeviceHints = Navigator & { deviceMemory?: number; connection?: { saveData?: boolean } };

/**
 * Share (0..1] of the requested particle count this device should draw: halved on low memory, on few cores or when
 * the visitor asked to save data. Always 1 on the server.
 *
 * @internal Used by the effect components; not part of the public barrel.
 */
export function deviceBudget(): number {
  if (typeof navigator === "undefined") return 1;
  const nav = navigator as DeviceHints;
  const weak =
    (nav.deviceMemory !== undefined && nav.deviceMemory <= 4) ||
    (nav.hardwareConcurrency > 0 && nav.hardwareConcurrency <= 4) ||
    nav.connection?.saveData === true;
  return weak ? 0.5 : 1;
}

/**
 * A small deterministic random generator (mulberry32): the same seed gives the same numbers on the server and in the
 * browser, so scattered decoration hydrates without a mismatch.
 *
 * @internal Used by the effect components; not part of the public barrel.
 */
export function seededRandom(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Resolves any CSS colour (a `var(--sheen-accent)` token, a `light-dark()` pair, `currentColor`) to the colour
 * the browser paints right now, as a string a 2D canvas accepts.
 *
 * @internal Used by the effect components; not part of the public barrel.
 */
export function resolveCssColor(host: Element, value: string): string {
  const probe = document.createElement("span");
  probe.style.color = value;
  probe.style.display = "none";
  host.appendChild(probe);
  const resolved = getComputedStyle(probe).color;
  probe.remove();
  return resolved || "transparent";
}

/**
 * Calls `onChange` whenever the colours a token resolves to may have changed: the theme or style preset
 * attribute on `<html>`, or the OS colour scheme. Returns the cleanup.
 *
 * @internal Used by the effect components; not part of the public barrel.
 */
export function watchColorScheme(onChange: () => void): () => void {
  if (typeof document === "undefined") return () => undefined;
  const observer = new MutationObserver(onChange);
  observer.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ["data-theme", "data-sheen-style", "class", "style"],
  });
  const media = typeof matchMedia === "function" ? matchMedia("(prefers-color-scheme: dark)") : null;
  media?.addEventListener("change", onChange);
  return () => {
    observer.disconnect();
    media?.removeEventListener("change", onChange);
  };
}

const subscribeNever = () => () => undefined;

/**
 * `false` while rendering on the server and during hydration, `true` once the component runs in the browser. Lets an
 * effect keep the server markup plain (fully readable, no scattered pieces) and switch on after hydration without a
 * state write inside an effect.
 *
 * @internal Used by the effect components; not part of the public barrel.
 * @example
 * ```tsx
 * import { useHydrated } from "./canvas-effects";
 *
 * export function Greeting() {
 *   return <p>{useHydrated() ? "Hello from the browser" : "Hello"}</p>;
 * }
 * ```
 *
 * @see /foundations
 */
export function useHydrated(): boolean {
  return useSyncExternalStore(
    subscribeNever,
    () => true,
    () => false,
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

/*
 * tailwind-merge only dedupes classes it can classify. Teach it SheenUI's own
 * scales so `cn("rounded-sheen-md", "rounded-sheen-lg")` keeps just the last one
 * instead of shipping both and leaving the winner to CSS source order.
 */
const twMerge = extendTailwindMerge<"glass-level">({
  extend: {
    theme: {
      radius: ["sheen-sm", "sheen-md", "sheen-lg", "sheen-xl", "sheen-full"],
      ease: ["sheen-out", "sheen-in-out", "sheen-exit", "sheen-spring"],
      text: ["2xs"],
    },
    classGroups: {
      // Glass levels replace each other: cn("glass-2", "glass-3") → "glass-3".
      "glass-level": ["glass-1", "glass-2", "glass-3"],
    },
  },
});

/** Merge class names, letting later Tailwind classes override earlier ones. */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * Base UI's `className` is a string OR a function of the part's state. This builds the `className` for a wrapper
 * that adds its own classes: pass the consumer's `className` and a `build` that merges it, and you get a string back
 * for a string (or nothing), or a state function for a function, so `className={(state) => ...}` keeps working.
 *
 * @example
 * ```tsx
 * import { Switch as BaseSwitch } from "@base-ui/react/switch";
 * import { classNameWith, cn } from "@sheenui/theme";
 *
 * type Props = { className?: string | ((state: BaseSwitch.Root.State) => string | undefined) };
 *
 * export function Example({ className }: Props) {
 *   return <BaseSwitch.Root className={classNameWith(className, (extra) => cn("rounded-full", extra))} />;
 * }
 * ```
 *
 * @see /components
 */
export function classNameWith<S>(
  className: string | ((state: S) => string | undefined) | undefined,
  build: (extra: string | undefined) => string,
): string | ((state: S) => string) {
  return typeof className === "function" ? (state: S) => build(className(state)) : build(className);
}

/**
 * CSV helpers: RFC 4180 quoting, plus protection against spreadsheet formula injection
 * (text starting with = + - @ or a tab is prefixed with an apostrophe; numbers are left alone).
 */

/** A cell value `toCsv` can write: text, numbers, booleans, dates (as ISO strings) or empty. */
export type CsvValue = string | number | boolean | Date | null | undefined;

const NEEDS_QUOTES = /[",\r\n]|^\s|\s$/;
const FORMULA_START = /^[=+\-@\t\r]/;

/** One CSV field: quoted when it holds a comma, quote or line break, and defanged against spreadsheet formula injection. */
export function escapeCsvValue(value: CsvValue): string {
  if (value === null || value === undefined) return "";
  if (typeof value === "number") return Number.isFinite(value) ? String(value) : "";
  if (typeof value === "boolean") return value ? "true" : "false";
  let text = value instanceof Date ? value.toISOString() : value;
  if (FORMULA_START.test(text)) text = `'${text}`;
  return NEEDS_QUOTES.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
}

/** Build a CSV document (CRLF line endings) from a header row and data rows. */
export function toCsv(headers: string[], rows: CsvValue[][]): string {
  return [headers, ...rows].map((row) => row.map(escapeCsvValue).join(",")).join("\r\n");
}

/** Save a Blob as a file through a temporary link. The one download implementation: CSV, SVG and PNG exports all use it. */
export function downloadBlob(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  link.rel = "noopener";
  document.body.appendChild(link);
  link.click();
  link.remove();
  // Revoke later: Safari needs the URL alive while the download starts.
  window.setTimeout(() => URL.revokeObjectURL(url), 1000);
}

/** Download text as a .csv file. Adds a BOM so Excel reads UTF-8 (₹, é, …) correctly. */
export function downloadCsv(filename: string, csv: string) {
  const name = filename.toLowerCase().endsWith(".csv") ? filename : `${filename}.csv`;
  downloadBlob(new Blob(["\uFEFF", csv], { type: "text/csv;charset=utf-8" }), name);
}

/** Download rows as a CSV file: a header row plus data rows (UTF-8 with BOM, quoted and formula-safe). */
export function exportCsv(filename: string, headers: string[], rows: CsvValue[][]) {
  downloadCsv(filename, toCsv(headers, rows));
}

import type { ReactNode } from "react";

import { cn } from "./cn";

/** Props of {@link FieldControlShell}. */
export type FieldControlShellProps = {
  /** The control itself (a Switch track, a Checkbox box). */
  control: ReactNode;
  /** Text next to the control; it and the control share one `<label>`. Without it, the control stands alone. */
  label?: ReactNode;
  /** Secondary line under the label, inside the same `<label>`. Only shown with `label`. */
  description?: ReactNode;
  /** Error text, shown as an alert below. It needs `errorId` so the control can point at it. */
  error?: ReactNode;
  /** The id the label text takes, so the control can name itself from it (`aria-labelledby`) on the first render instead of waiting for Base UI to wire it up after hydration. */
  labelId?: string;
  /** The id the error paragraph takes (the control's `aria-describedby`). */
  errorId: string;
  /** Classes for the outermost element: the `<label>`, the wrapper holding an `error`, or the bare control's own. */
  className?: string;
};

/**
 * The label, description and error layout Switch and Checkbox share. The outer element, which takes `className`,
 * depends on what is set: the `<label>` when only a label is, a `<div>` wrapper once there is an `error`, and with
 * neither label nor error no wrapper at all (the caller puts `className` on the control).
 *
 * @internal Not part of the public barrel: the example documents the module's own helpers.
 * @example
 * ```tsx
 * import { FieldControlShell } from "./field-control-shell";
 *
 * export const Row = () => (
 *   <FieldControlShell control={<input type="checkbox" />} label="Agree" errorId="agree-error" error="Required" />
 * );
 * ```
 *
 * @see /components/switch
 */
export function FieldControlShell({
  control,
  label,
  description,
  error,
  errorId,
  labelId,
  className,
}: FieldControlShellProps) {
  const message = error ? (
    <p id={errorId} role="alert" className="text-xs font-medium text-sheen-danger-text">
      {error}
    </p>
  ) : null;

  if (!label)
    return message ? (
      <div className={cn("flex flex-col gap-1.5", className)}>
        {control}
        {message}
      </div>
    ) : (
      control
    );

  const field = (
    <label className={cn("flex cursor-pointer items-start gap-3", message ? undefined : className)}>
      <span className="pt-0.5">{control}</span>
      <span className="flex flex-col gap-0.5">
        <span id={labelId} className="text-sm font-medium">
          {label}
        </span>
        {description && <span className="text-xs text-sheen-fg-muted">{description}</span>}
      </span>
    </label>
  );
  return message ? (
    <div className={cn("flex flex-col gap-1.5", className)}>
      {field}
      {message}
    </div>
  ) : (
    field
  );
}

/**
 * The one height scale of every button and form control: "sm" 32px, "md" 40px (default), "lg" 48px, read from the
 * `--sheen-control-h-*` tokens (styles/tokens.css) so a Button beside an Input lines up at every size. On touch screens
 * (`any-pointer: coarse`) "sm" and "md" grow to 44px, so no control is shorter than a finger.
 */
export type FieldSize = "sm" | "md" | "lg";

/** Fixed heights for single-line controls (Select trigger, NumberField, date picker trigger, ColorField, Input). */
export const fieldHeight: Record<FieldSize, string> = {
  sm: "h-(--sheen-control-h-sm)",
  md: "h-(--sheen-control-h-md)",
  lg: "h-(--sheen-control-h-lg)",
};

/** Minimum heights for controls that can grow (Combobox with chips, TagsInput). */
export const fieldMinHeight: Record<FieldSize, string> = {
  sm: "min-h-(--sheen-control-h-sm)",
  md: "min-h-(--sheen-control-h-md)",
  lg: "min-h-(--sheen-control-h-lg)",
};

"use client";

import { useCallback, useMemo } from "react";
import type { FocusEvent, FocusEventHandler, Ref, RefCallback } from "react";

import { useLatest } from "../hooks/use-latest";

/**
 * Props every SheenUI form control accepts so it plugs into a form library (react-hook-form's `Controller`,
 * TanStack Form, Formik) and into a native `<form>`: a `ref` to the focusable element (so a failed
 * validation can focus it), `onBlur` (so the library can mark it touched), `name`, `required`, `disabled`,
 * `aria-invalid` and `aria-describedby`.
 */
export type FormControlProps<T extends HTMLElement = HTMLElement> = {
  /** Ref to the control's focusable element (the trigger, input or first thumb). Form libraries use it to focus the field after a failed validation. */
  ref?: Ref<T>;
  /** Called when focus leaves the control (not when it moves between the control's own parts). */
  onBlur?: FocusEventHandler<HTMLElement>;
  /** Field name, used for native form submission and by form libraries. */
  name?: string;
  /** Marks the field as required. */
  required?: boolean;
  /** Disables the field. */
  disabled?: boolean;
  /** Marks the field as invalid (also set automatically when `error` is shown). */
  "aria-invalid"?: boolean | "true" | "false";
  /** Ids of elements that describe the field, merged with the control's own description and error ids. */
  "aria-describedby"?: string;
};

/** Combine refs (callback or object) into one callback ref; `undefined` entries are skipped. */
export function mergeRefs<T>(...refs: (Ref<T> | undefined)[]): RefCallback<T> {
  return (node) => {
    const cleanups: (() => void)[] = [];
    for (const ref of refs) {
      if (typeof ref === "function") {
        const cleanup = ref(node);
        if (typeof cleanup === "function") cleanups.push(cleanup);
        else cleanups.push(() => ref(null));
      } else if (ref) {
        (ref as { current: T | null }).current = node;
        cleanups.push(() => {
          (ref as { current: T | null }).current = null;
        });
      }
    }
    return () => {
      for (const cleanup of cleanups) cleanup();
    };
  };
}

/**
 * Wraps `onBlur` for a control made of several focusable parts: it fires only when focus leaves the whole
 * group, not when it moves from one part to the next.
 */
export function groupBlur<T extends HTMLElement>(handler?: FocusEventHandler<T>): FocusEventHandler<T> | undefined {
  if (!handler) return undefined;
  return (event: FocusEvent<T>) => {
    const next = event.relatedTarget;
    if (next instanceof Node && event.currentTarget.contains(next)) return;
    handler(event);
  };
}

/** Join description ids, dropping anything that is not a non-empty string (so `cond && id` works); `undefined` when nothing is left. */
export function joinIds(...ids: unknown[]): string | undefined {
  return ids.filter((id): id is string => typeof id === "string" && id !== "").join(" ") || undefined;
}

/**
 * `mergeRefs` as a hook: returns one stable callback ref that forwards the node to every ref passed in, always the latest ones.
 *
 * @example
 * ```tsx
 * import { useRef, type Ref } from "react";
 * import { useMergedRef } from "@sheenui/theme";
 *
 * export function Field({ ref }: { ref?: Ref<HTMLInputElement> }) {
 *   const own = useRef<HTMLInputElement>(null);
 *   return <input ref={useMergedRef(own, ref)} />;
 * }
 * ```
 *
 * @see /forms/field
 */
export function useMergedRef<T>(...refs: (Ref<T> | undefined)[]): RefCallback<T> {
  const latestRef = useLatest(refs);
  return useCallback((node: T | null) => mergeRefs(...latestRef.current)(node), [latestRef]);
}

/**
 * A ref for a control made of several focusable parts (a radio group, a rating, an OTP field). It attaches
 * `ref` to the control's container and makes the container's `focus()` move focus to the first matching
 * descendant (selectors are tried in order, e.g. the checked radio first), so a form library that calls
 * `ref.focus()` after a failed validation lands on something a person can use.
 *
 * @example
 * ```tsx
 * import type { Ref } from "react";
 * import { useFocusProxyRef } from "@sheenui/theme";
 *
 * export function Options({ ref }: { ref?: Ref<HTMLDivElement> }) {
 *   const group = useFocusProxyRef(ref, "[aria-checked='true']", "button");
 *   return <div ref={group}><button>A</button></div>;
 * }
 * ```
 *
 * @see /forms/field
 */
export function useFocusProxyRef<T extends HTMLElement>(
  ref: Ref<T> | undefined,
  ...selectors: string[]
): RefCallback<T> {
  const key = selectors.join("\n");
  return useMemo(
    () =>
      mergeRefs<T>((node) => {
        if (!node) return;
        const original = node.focus.bind(node);
        node.focus = (options?: FocusOptions) => {
          for (const selector of key.split("\n")) {
            const target = node.querySelector<HTMLElement>(selector);
            if (target) {
              target.focus(options);
              return;
            }
          }
          original(options);
        };
        // On detach (or when the selectors / ref change and the ref re-attaches) the element gets its own `focus` back.
        return () => {
          Reflect.deleteProperty(node, "focus");
        };
      }, ref),
    [ref, key],
  );
}

"use client";

import { createContext, useContext, useLayoutEffect, useRef, useState, type ReactNode } from "react";
import { animate } from "motion/react";

import { cn } from "./cn";
import { useSheenReducedMotion } from "../hooks/use-preferences";
import { spring } from "../motion/tokens";

/** Per open popup: which pill is showing, so the next one can glide from it (never across popups). */
type HighlightTracker = {
  /** The pill that is shown, or was shown last. */
  current: HTMLElement | null;
  /** When `current` was hidden; 0 while it is shown. */
  hiddenAt: number;
};

const HighlightContext = createContext<HighlightTracker | null>(null);

/** A pill hidden longer ago than this (the pointer left the menu) isn't glided from. */
const GLIDE_WINDOW_MS = 120;

/**
 * Makes `el` the pill that is shown. Returns where the previous pill is on screen right now
 * (mid-glide included) if it just left, and whether keyboard focus moved it. The tracker is shared,
 * mutable state by design (one per open popup), so the writes live here, outside the component.
 */
function claimHighlight(tracker: HighlightTracker, el: HTMLElement) {
  const prev = tracker.current;
  let from: DOMRect | null = null;
  let viaKeyboard = false;
  if (prev && prev !== el) {
    if (prev.isConnected && tracker.hiddenAt > 0 && performance.now() - tracker.hiddenAt < GLIDE_WINDOW_MS) {
      from = prev.getBoundingClientRect();
      viaKeyboard = prev.parentElement?.matches(":focus-visible") ?? false;
    }
    prev.style.transform = "";
  }
  tracker.current = el;
  tracker.hiddenAt = 0;
  el.style.transform = "";
  return { from, viaKeyboard };
}

/** Notes when the shown pill `el` was hidden, so the next pill can glide from it (see `claimHighlight`). */
function releaseHighlight(tracker: HighlightTracker, el: HTMLElement) {
  if (tracker.current === el) tracker.hiddenAt = performance.now();
}

/** Props of `MenuHighlight`; each option is documented on its field. */
export type MenuHighlightProps = {
  /** Show the pill (pass the item's `highlighted` state). */
  active: boolean;
  /** "danger" tints it red, for destructive items. Default "neutral". */
  tone?: "neutral" | "danger";
  /** Adds extra classes to the pill. */
  className?: string;
};

/**
 * The highlight pill. Every item renders one; only the highlighted item's is visible, and it
 * glides in from wherever the previous pill was on screen. Use it as the first child of your
 * own items built on Base UI Menu parts, inside a MenuContent.
 *
 * The glide is worked out in screen space and re-read every frame, so it stays smooth when
 * the menu scrolls to reveal the next item (a shared-layout animation measures the start
 * and end at different scroll offsets there, and jumps).
 *
 * Keyboard: none, it is decorative. Accessibility: `aria-hidden`; hidden in forced colors, where the item itself
 * switches to `Highlight`. Glass and motion: transform and opacity only; reduced motion makes it jump.
 *
 * Wrap the list of items in `GlideHighlightScope` (the `MenuContent` of this library already does): without it the pill
 * still lights the highlighted item but does not glide from the previous one.
 *
 * @example
 * ```tsx
 * import { Menu as BaseMenu } from "@base-ui/react/menu";
 * import { GlideHighlightScope, MenuHighlight } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <BaseMenu.Root>
 *       <BaseMenu.Trigger>Actions</BaseMenu.Trigger>
 *       <BaseMenu.Portal>
 *         <BaseMenu.Positioner>
 *           <BaseMenu.Popup>
 *             <GlideHighlightScope>
 *               <BaseMenu.Item render={(props, state) => (
 *                 <div {...props}><MenuHighlight active={state.highlighted} />{props.children}</div>
 *               )}>Rename</BaseMenu.Item>
 *             </GlideHighlightScope>
 *           </BaseMenu.Popup>
 *         </BaseMenu.Positioner>
 *       </BaseMenu.Portal>
 *     </BaseMenu.Root>
 *   );
 * }
 * ```
 *
 * @see /overlays/dropdown-menu
 */
export function MenuHighlight({ active, tone = "neutral", className }: MenuHighlightProps) {
  const tracker = useContext(HighlightContext);
  const reduced = useSheenReducedMotion();
  const ref = useRef<HTMLSpanElement>(null);

  useLayoutEffect(() => {
    const el = ref.current;
    const item = el?.parentElement;
    if (!active || !el || !item || !tracker) return;

    const { from, viaKeyboard } = claimHighlight(tracker, el);

    let stop: (() => void) | undefined;
    if (from && from.height > 0 && !reduced) {
      // Base UI scrolls a keyboard-highlighted item into view a frame later; do it now, so the
      // glide starts from what was on screen and ends where the item will stay.
      if (viaKeyboard) item.scrollIntoView({ block: "nearest", inline: "nearest" });
      const start = from;
      const place = (progress: number) => {
        const to = item.getBoundingClientRect();
        if (to.height === 0) return;
        const top = start.top + (to.top - start.top) * progress;
        const height = start.height + (to.height - start.height) * progress;
        el.style.transform = `translateY(${top - to.top}px) scaleY(${height / to.height})`;
      };
      place(0);
      const controls = animate(0, 1, {
        ...spring.snappy,
        onUpdate: place,
        onComplete: () => {
          el.style.transform = "";
        },
      });
      stop = () => controls.stop();
    }

    return () => {
      // Leave any mid-glide transform in place: the next pill reads it as its start.
      stop?.();
      releaseHighlight(tracker, el);
    };
  }, [active, reduced, tracker]);

  return (
    <span
      ref={ref}
      aria-hidden
      data-slot="menu-highlight"
      className={cn(
        "pointer-events-none absolute inset-0 -z-10 origin-top rounded-sheen-sm",
        active ? "opacity-100" : "opacity-0",
        tone === "danger" ? "bg-sheen-danger-soft" : "bg-sheen-hover",
        // Keyboard focus: a solid ring that travels with the pill (the tint alone is too faint).
        "[:focus-visible>&]:shadow-[inset_0_0_0_2px_var(--sheen-focus)]",
        // High contrast drops the tint: the item itself switches to Highlight (see itemBase).
        "forced-colors:hidden",
        className,
      )}
    />
  );
}

/**
 * Gives every `MenuHighlight` pill inside it one shared tracker, so the pill glides between items of the same
 * popup (Menu, Select, Combobox) and never in from another popup. `MenuContent` wraps its children in it; use it
 * around the list of your own Base UI popup.
 *
 * Keyboard: none. Accessibility: renders no element. Glass and motion: see `MenuHighlight`.
 *
 * @example
 * ```tsx
 * import { Select as BaseSelect } from "@base-ui/react/select";
 * import { GlideHighlightScope } from "@sheenui/theme";
 *
 * export function Example({ children }: { children: React.ReactNode }) {
 *   return (
 *     <BaseSelect.Popup><GlideHighlightScope>{children}</GlideHighlightScope></BaseSelect.Popup>
 *   );
 * }
 * ```
 *
 * @see /overlays/dropdown-menu
 */
export function GlideHighlightScope({ children }: { children: ReactNode }) {
  const [tracker] = useState<HighlightTracker>(() => ({ current: null, hiddenAt: 0 }));
  return <HighlightContext value={tracker}>{children}</HighlightContext>;
}

/**
 * Splits the rendered rows of a windowed list into runs that share a group, so each run can sit in a
 * `role="group"` named by that group. A windowed list drops the group heading when it scrolls out of view,
 * so the name comes from the rows themselves, not from the heading's element.
 *
 * @example
 * ```tsx
 * import { Select } from "@sheenui/theme";
 *
 * export function Example() {
 *   return <Select label="Item" items={[{ value: "a", label: "A", group: "Letters" }]} />;
 * }
 * ```
 *
 * @see /components/select
 *
 * @internal
 */
export function segmentByGroup<T>(entries: T[], groupOf: (entry: T) => string | undefined) {
  const segments: { label: string | undefined; key: string; entries: T[] }[] = [];
  const seen = new Map<string, number>();
  for (const entry of entries) {
    const label = groupOf(entry);
    const last = segments.at(-1);
    if (last && last.label === label) last.entries.push(entry);
    else {
      // Keyed by the group (not the position), so a group's wrapper survives scrolling and keeps the focused option mounted.
      const base = label ?? "\u0000";
      const n = seen.get(base) ?? 0;
      seen.set(base, n + 1);
      segments.push({ label, key: `${base}#${n}`, entries: [entry] });
    }
  }
  return segments;
}

/** A heading level, 1 to 6. Every component that renders a heading takes it as `headingLevel`, so the page outline stays right. */
export type HeadingLevel = 1 | 2 | 3 | 4 | 5 | 6;

/**
 * What a `headingLevel` prop accepts: a level (1 to 6), or `"none"` to render the same styled text as a
 * paragraph with no heading role. `"none"` is for a component embedded as an example or inside another widget,
 * where its title must not appear in the page's document outline. Headings nested inside the component follow suit.
 */
export type HeadingLevelOption = HeadingLevel | "none";

/** The element a heading renders as: `h1` to `h6`, or `p` for a `"none"` heading. */
export type HeadingTag = "h1" | "h2" | "h3" | "h4" | "h5" | "h6" | "p";

/**
 * The element for a heading `offset` levels below `level`.
 *
 * @param level The component's `headingLevel`.
 * @param offset How many levels deeper this heading sits (0 for the component's own title).
 * @returns `h1` to `h6` (clamped at `h6`), or `p` when `level` is `"none"` (or `false`, the older spelling).
 * @example
 * const Title = headingTag(headingLevel); // <Title>Plans</Title>
 */
export function headingTag(level: HeadingLevelOption | false, offset = 0): HeadingTag {
  if (level === "none" || level === false) return "p";
  return `h${Math.min(6, level + offset)}` as HeadingTag;
}

/**
 * The `headingLevel` to hand to a nested component that renders its headings `by` levels below `level`.
 *
 * @param level The component's `headingLevel`.
 * @param by How many levels deeper the child sits.
 * @returns A level clamped at 6, or `"none"` when `level` is `"none"` (so the whole subtree stays out of the outline).
 */
export function headingBelow(level: HeadingLevelOption | false, by = 1): HeadingLevel | "none" {
  if (level === "none" || level === false) return "none";
  return Math.min(6, level + by) as HeadingLevel;
}

/**
 * The element for each `headingLevel` value, for use as `const Title = HEADING_TAGS[level]`.
 * A plain lookup, so the React lint rule does not take it for a component created during render (it does for a function call's result).
 */
export const HEADING_TAGS: Readonly<Record<HeadingLevel | "none", HeadingTag>> = {
  1: "h1",
  2: "h2",
  3: "h3",
  4: "h4",
  5: "h5",
  6: "h6",
  none: "p",
};

/**
 * True while an input method editor (Japanese, Chinese, Korean and other IMEs) is composing text, so
 * Enter must confirm the composition instead of committing a value. `isComposing` alone misses the
 * key that ends the composition in Safari, which fires `compositionend` first; the legacy
 * `keyCode === 229` still reports it. Pass a native `KeyboardEvent` (`event.nativeEvent` in React).
 * Pure: it only reads the event it is given, so it is safe to import on the server.
 */
export function isImeComposing(event: { isComposing: boolean; keyCode: number }): boolean {
  return event.isComposing || event.keyCode === 229;
}

/**
 * Up to two upper-case initials of a name, or "" when it is empty. By default they are the first letters of the first
 * two words; with `"first-last"` they are the first letters of the first and the last word.
 * @internal
 */
export function initials(name: string, pick: "first-two" | "first-last" = "first-two"): string {
  const words = name.trim().split(/\s+/).filter(Boolean);
  const chosen = pick === "first-last" && words.length > 1 ? [words[0], words[words.length - 1]] : words.slice(0, 2);
  return chosen
    .map((word) => word?.[0] ?? "")
    .join("")
    .toUpperCase();
}

/**
 * Limits `n` to the range from `lo` to `hi`. The one clamp helper in the library: pure, with no directive,
 * so server and client modules can both import it.
 *
 * @internal Re-exported by the charts' `chart-utils` for the chart modules.
 * @example
 * ```ts
 * import { clamp } from "./math";
 *
 * export const percent = (n: number) => clamp(n, 0, 100);
 * ```
 *
 * @see /components
 */
export function clamp(n: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, n));
}

let surfaces = 0;

/**
 * `data-modal-open` on `<html>` while a modal glass surface is in the DOM.
 *
 * styles/glass.css turns the page's own blur off behind a dialog (the glass budget with a modal open). That rule
 * used to be written as `:root:has([data-slot="dialog-content"])`, which made the browser re-check the whole
 * document against the `:has()` on every DOM insertion while a dialog opened or closed (six to nine re-checks
 * per open at 4x CPU). An attribute the dialog toggles itself gives the same result for one attribute change.
 *
 * Use it as a ref on the modal's popup element (`ref={mergeRefs(ref, modalSurfaceRef)}`): it counts the
 * surfaces attached, so nested or stacked dialogs keep the flag until the last one has left the DOM. It is
 * called with `null` when the node detaches (React 18 style; `mergeRefs` adapts it for React 19's cleanups).
 */
export function modalSurfaceRef(node: HTMLElement | null): void {
  if (typeof document === "undefined") return;
  if (node) {
    surfaces++;
    document.documentElement.setAttribute("data-modal-open", "");
  } else if (surfaces > 0 && --surfaces === 0) {
    document.documentElement.removeAttribute("data-modal-open");
  }
}

/**
 * Keeps Tab and Shift+Tab inside a modal popup, synchronously.
 *
 * Base UI traps focus with two invisible guard spans around the popup. Landing on a guard hands focus back
 * on the next animation frame, so a second Tab pressed inside that gap (key repeat on a busy page, a script
 * or a switch device that sends keys quickly) walks on to the page behind the dialog. This wraps at the ends
 * on the keydown itself, so focus never reaches a guard by keyboard. The guards stay in place for everything
 * else (screen-reader virtual cursors, programmatic focus).
 *
 * It is a native listener on the popup element, not a React `onKeyDown` prop: Base UI merges and can skip a
 * popup's own key handler, a listener on the node cannot be skipped. Events from a nested popup that is
 * portalled elsewhere (a select or a menu opened inside the dialog) have a target outside the popup and are
 * left alone.
 *
 * @internal
 */

const TABBABLE =
  'a[href],button,input:not([type="hidden"]),select,textarea,summary,[contenteditable="true"],audio[controls],video[controls],iframe,[tabindex]';

function isTabbable(el: HTMLElement) {
  if (el.tabIndex < 0 || el.hasAttribute("data-base-ui-focus-guard")) return false;
  if (el.matches(":disabled") || el.closest("[inert],[hidden]")) return false;
  if (
    el instanceof HTMLInputElement &&
    el.type === "radio" &&
    !el.checked &&
    el.form?.querySelector(`input[type="radio"][name="${CSS.escape(el.name)}"]:checked`)
  )
    return false;
  return el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden";
}

/** Keydown listener for a modal popup: wraps Tab at its first and last tabbable element. */
function wrapModalTab(event: KeyboardEvent): void {
  if (event.key !== "Tab" || event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey) return;
  const popup = event.currentTarget;
  const target = event.target;
  if (!(popup instanceof HTMLElement) || !(target instanceof Node) || !popup.contains(target)) return;
  // A modal rendered inside this one (not portalled out) wraps its own Tab: leave its events to it.
  if (target instanceof Element) {
    const inner = target.closest('[role="dialog"],[role="alertdialog"]');
    if (inner && inner !== popup && popup.contains(inner)) return;
  }
  const tabbable = [...popup.querySelectorAll<HTMLElement>(TABBABLE)].filter(isTabbable);
  const first = tabbable[0];
  const last = tabbable[tabbable.length - 1];
  if (!first || !last) {
    event.preventDefault();
    return;
  }
  if (event.shiftKey ? target === first || target === popup : target === last) {
    event.preventDefault();
    (event.shiftKey ? last : first).focus();
  }
}

/**
 * Wraps Tab at the ends of `popup` while `enabled`; returns the cleanup that removes the listener (the return
 * value of a `useEffect` callback). Pass the popup element from state (a ref callback that sets it), so the
 * listener is attached when the popup mounts: `useEffect(() => modalTabTrap(node, modal), [node, modal])`.
 *
 * @internal
 */
export function modalTabTrap(popup: HTMLElement | null, enabled = true): (() => void) | undefined {
  if (!popup || !enabled) return undefined;
  popup.addEventListener("keydown", wrapModalTab);
  return () => popup.removeEventListener("keydown", wrapModalTab);
}

/** The handlers React and Motion type differently (drag and animation events); a Motion element takes Motion's own. */
type Conflicting = "onDrag" | "onDragStart" | "onDragEnd" | "onAnimationStart";
const CONFLICTING: readonly Conflicting[] = ["onDrag", "onDragStart", "onDragEnd", "onAnimationStart"];

/** `P` without the handlers whose signatures differ between React's DOM props and Motion's. */
export type MotionSafeProps<P> = Omit<P, Conflicting>;

/**
 * Props of a plain element, typed for spreading onto a `motion.*` element: the four handlers that React and Motion
 * type differently (`onDrag`, `onDragStart`, `onDragEnd`, `onAnimationStart`) are removed, so the spread is checked
 * instead of cast away with `as object`. Public props types use {@link MotionSafeProps} so callers cannot pass them.
 *
 * @internal Not part of the public barrel.
 */
export function motionSafeProps<P extends object>(props: P): MotionSafeProps<P> {
  const rest: Record<string, unknown> = { ...(props as Record<string, unknown>) };
  for (const key of CONFLICTING) Reflect.deleteProperty(rest, key);
  return rest as MotionSafeProps<P>;
}

/**
 * The CSS selector that marks an element revealed by a JavaScript entrance (`initial={{ opacity: 0 }}`): add
 * `data-sheen-reveal` to it and render `NoScriptReveal` once near it.
 *
 * @internal Not part of the public barrel: shared by the blocks whose entrance starts from `opacity: 0`.
 * @example
 * ```tsx
 * import { REVEAL_ATTRIBUTE } from "./no-script-reveal";
 *
 * export const attrs = { [REVEAL_ATTRIBUTE]: "" };
 * ```
 *
 * @see /blocks/feature-grid
 */
export const REVEAL_ATTRIBUTE = "data-sheen-reveal";

/**
 * Makes the server-rendered content visible when JavaScript does not run. A Motion entrance writes `opacity: 0` into the
 * server HTML and the script reveals it, so without script the cards stayed invisible. This renders a `<noscript>`
 * style (the server HTML only; React never renders `<noscript>` children on the client) that overrides the inline
 * start state of every `data-sheen-reveal` element. With script the entrance plays as before.
 *
 * Accessibility: the content was always in the accessibility tree; this makes it visible too.
 *
 * @internal Not part of the public barrel: render it once next to the elements that carry `data-sheen-reveal`.
 * @example
 * ```tsx
 * import { NoScriptReveal } from "./no-script-reveal";
 *
 * export function Example() {
 *   return <NoScriptReveal />;
 * }
 * ```
 *
 * @see /blocks/feature-grid
 */
export function NoScriptReveal() {
  return (
    // In a hidden box so the empty <noscript> block takes no room (and no flex gap); a style element applies wherever it is.
    <div hidden>
      <noscript>
        <style>{`[${REVEAL_ATTRIBUTE}]{opacity:1!important;transform:none!important}`}</style>
      </noscript>
    </div>
  );
}

/**
 * How many options fit in a list's scroll area (PageUp / PageDown move by that many): the inner height over the height
 * of one option, at least 1. `fallback` when the list has no layout yet. It does not depend on the scroll position.
 *
 * @internal
 */
export function pageSize(list: HTMLElement | null | undefined, optionHeight: number, fallback = 8): number {
  if (!list || list.clientHeight === 0 || optionHeight <= 0) return fallback;
  const style = getComputedStyle(list);
  const inner = list.clientHeight - (parseFloat(style.paddingTop) || 0) - (parseFloat(style.paddingBottom) || 0);
  return Math.max(1, Math.floor(inner / optionHeight));
}

"use client";

/**
 * Accessibility fix-ups for the Base UI popups (menus, listboxes, comboboxes). Spread `popupA11yProps`
 * on the popup's `*.Positioner`: `<BaseMenu.Positioner {...popupA11yProps}>`.
 *
 * It solves three axe-core findings that every Base UI popup raises while it is open:
 *
 * 1. `region` ("all page content should be contained by landmarks"). Base UI appends the popup's
 *    portal to `<body>`, outside `<main>`. `role="region"` makes the positioner its own region. It has
 *    no accessible name on purpose: an unnamed region is not exposed as a landmark, so landmark lists
 *    stay clean while the popup (which takes focus and has its own role and name) is read as usual.
 *    It sits on the positioner, not the portal, because Select keeps its portal mounted after it
 *    closes while the positioner is hidden. A submenu's positioner is named "Submenu" so two open
 *    menus never share a landmark name (`landmark-unique`).
 * 2. `aria-hidden-focus`, focus guards. Base UI's invisible focus-guard spans are `aria-hidden` and
 *    tabbable on purpose (they redirect Tab). axe accepts that for focus traps: an element with an
 *    `onfocus` handler is treated as a sentinel, so each guard gets a no-op one.
 * 3. `aria-hidden-focus`, the page behind. A typeable combobox hides everything outside it with
 *    `aria-hidden` but leaves links and buttons tabbable. While the popup is open those controls (inside
 *    any `aria-hidden` subtree) are
 *    taken out of the tab order (`tabindex="-1"`, restored on close). They stay clickable, so a
 *    click outside still closes the popup and presses the button in one go (`inert` would swallow it).
 *
 * `typeablePopupA11yProps` is the variant for popups whose input stays in the page (Combobox, the Tags
 * input suggestions). Base UI hides everything outside such a popup from assistive technology
 * (`aria-hidden`, unconditionally: there is no prop to turn it off), including the page's `<h1>` and
 * landmarks. That is the right call on touch screen readers (VoiceOver iOS, TalkBack), which ignore
 * `aria-activedescendant` and need the list to be the only thing to swipe through. On a fine pointer
 * (desktop screen readers follow `aria-activedescendant`, the WAI-ARIA combobox pattern is non-modal
 * and the page stays readable) the variant takes back what Base UI hid: only nodes hidden after the
 * popup mounted, so anything the app or another dialog had already hidden stays hidden. "Fine" means the
 * primary pointer (`(pointer: coarse)`), not `any-pointer`, which also matches touch laptops. On every device
 * Tab inside the open list is handled explicitly: focus moves to the next tabbable element after the input
 * and the list closes (2.1.1 / 2.4.3), so nothing is ever unreachable while the page is held.
 *
 * @internal
 */

import { useCallback, useLayoutEffect, useRef } from "react";

/** The primary pointer only: `(any-pointer: coarse)` also matches touch laptops and phones with a hardware keyboard. */
const PRIMARY_COARSE_QUERY = "(pointer: coarse)";

/** Accessible name of a nested popup's positioner: `level` is 1 for a first submenu, 2 for the one inside it. Default "Submenu" / "Submenu, level 2". */
export type SubmenuName = (level: number) => string;

/** English default of {@link SubmenuName}. */
export const defaultSubmenuName: SubmenuName = (level) => (level === 1 ? "Submenu" : `Submenu, level ${level}`);

const noop = () => undefined;

const TABBABLE =
  'a[href],button:not([disabled]),input:not([disabled]):not([type="hidden"]),select:not([disabled]),textarea:not([disabled]),summary,[contenteditable="true"],[tabindex]:not([tabindex="-1"])';

/** Elements taken out of the tab order, shared by every open popup (a submenu opens over its parent). */
const held = new Map<HTMLElement, { original: string | null; count: number }>();

function hold(el: HTMLElement) {
  const entry = held.get(el);
  if (entry) {
    entry.count += 1;
    return;
  }
  held.set(el, { original: el.getAttribute("tabindex"), count: 1 });
  el.setAttribute("tabindex", "-1");
}

function release(el: HTMLElement) {
  const entry = held.get(el);
  if (!entry) return;
  entry.count -= 1;
  if (entry.count > 0) return;
  held.delete(el);
  // Leave it alone if the app changed it meanwhile (a roving tabindex, say).
  if (el.getAttribute("tabindex") !== "-1") return;
  if (entry.original === null) el.removeAttribute("tabindex");
  else el.setAttribute("tabindex", entry.original);
}

/** Touch screen readers need the list to be the only reachable content, so they keep Base UI's confinement. */
function keepsPageExposed() {
  return typeof matchMedia === "function" && !matchMedia(PRIMARY_COARSE_QUERY).matches;
}

const FOCUSABLE =
  'a[href],button,input:not([type="hidden"]),select,textarea,summary,[contenteditable="true"],[tabindex]';

/** Tab order as the user sees it: tabindex held by an open popup counts as its original value. */
function isTabbableNow(el: HTMLElement) {
  const entry = held.get(el);
  const tabindex = entry ? entry.original : el.getAttribute("tabindex");
  if (tabindex !== null && Number.parseInt(tabindex, 10) < 0) return false;
  if (tabindex === null && !el.matches('a[href],button,input,select,textarea,summary,[contenteditable="true"]'))
    return false;
  if (el.matches(":disabled") || el.closest("[inert],[hidden]") || el.hasAttribute("data-base-ui-focus-guard"))
    return false;
  if (el.closest("[data-base-ui-portal]")) return false;
  return el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden";
}

/**
 * Tab inside an open typeable list: Base UI keeps the page hidden on touch-capable devices, which used to send
 * focus to `<body>`. Move focus explicitly to the next tabbable element after the input (before it for Shift+Tab);
 * the list closes when the input loses focus. Independent of pointer type, so no control is ever unreachable.
 */
function handleTab(event: KeyboardEvent, positioner: HTMLElement) {
  if (event.key !== "Tab" || event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey) return;
  const input = event.target;
  if (!(input instanceof HTMLElement) || positioner.contains(input) || !input.matches("input,textarea,[role=combobox]"))
    return;
  const all = [...document.querySelectorAll<HTMLElement>(FOCUSABLE)].filter(
    (el) => el === input || (isTabbableNow(el) && !positioner.contains(el)),
  );
  const at = all.indexOf(input);
  if (at < 0) return;
  const next = all[at + (event.shiftKey ? -1 : 1)];
  if (!next) return; // first/last stop: the browser moves on to its own chrome
  event.preventDefault();
  next.focus();
}

function createPopupRef(exposePage: boolean) {
  return (positioner: HTMLElement | null) => popupRef(positioner, exposePage, defaultSubmenuName);
}

function popupRef(positioner: HTMLElement | null, exposePage: boolean, submenuName: SubmenuName) {
  if (!positioner) return;
  const mine = new Set<HTMLElement>();
  // Hidden before this popup opened: not Base UI's doing for this popup, never un-hidden here.
  const hiddenBefore =
    exposePage && keepsPageExposed() ? new Set(document.querySelectorAll("[aria-hidden='true']")) : null;
  let frame = 0;

  const sweep = () => {
    frame = 0;
    if (!positioner.isConnected) return;
    for (const guard of document.querySelectorAll<HTMLElement>("[data-base-ui-focus-guard]")) {
      guard.onfocus ??= noop;
    }
    for (const root of document.querySelectorAll<HTMLElement>('[aria-hidden="true"]')) {
      if (
        hiddenBefore &&
        !hiddenBefore.has(root) &&
        !root.contains(positioner) &&
        !root.closest("[data-base-ui-portal]") &&
        !root.hasAttribute("data-base-ui-focus-guard")
      ) {
        root.removeAttribute("aria-hidden");
        continue;
      }
      // Never the popup itself, a portal's content or Base UI's own focus guards (they keep tabindex 0 to trap focus).
      if (
        root.contains(positioner) ||
        root.closest("[data-base-ui-portal]") ||
        root.hasAttribute("data-base-ui-focus-guard")
      )
        continue;
      const stops = root.matches(TABBABLE) ? [root] : [];
      for (const el of [...stops, ...root.querySelectorAll<HTMLElement>(TABBABLE)]) {
        if (mine.has(el) || el.hasAttribute("data-base-ui-focus-guard")) continue;
        mine.add(el);
        hold(el);
      }
    }
  };
  const schedule = () => {
    if (!frame) frame = requestAnimationFrame(sweep);
  };

  // A nested popup (a submenu) lives in its parent's portal: give it its own landmark name.
  const depth = nestedDepth(positioner);
  if (depth > 0) positioner.setAttribute("aria-label", submenuName(depth));

  const onKeyDown = exposePage ? (event: KeyboardEvent) => handleTab(event, positioner) : null;
  if (onKeyDown) document.addEventListener("keydown", onKeyDown, true);

  schedule();
  // Base UI applies and removes aria-hidden as popups open and close: only that attribute is watched.
  const observer = new MutationObserver(schedule);
  observer.observe(document.body, { attributes: true, attributeFilter: ["aria-hidden"], subtree: true });

  return () => {
    observer.disconnect();
    if (onKeyDown) document.removeEventListener("keydown", onKeyDown, true);
    if (frame) cancelAnimationFrame(frame);
    for (const el of mine) release(el);
    mine.clear();
  };
}

function nestedDepth(positioner: HTMLElement) {
  let depth = 0;
  let portal = positioner.parentElement?.closest("[data-base-ui-portal]") ?? null;
  // positioner.parentElement is this popup's own portal; walk up from there.
  portal = portal?.parentElement?.closest("[data-base-ui-portal]") ?? null;
  while (portal) {
    depth += 1;
    portal = portal.parentElement?.closest("[data-base-ui-portal]") ?? null;
  }
  return depth;
}

// Module-level refs: a stable identity, so React attaches each one once per mount.
const menuPopupRef = createPopupRef(false);
const typeablePopupRef = createPopupRef(true);

/** For menu, select and listbox popups: spread it on the `*.Positioner` (role, ref that applies the fix-ups above). */
export const popupA11yProps = { role: "region", ref: menuPopupRef } as const;
/** For popups whose input stays in the page (Combobox, Tags input): also keeps the page exposed on fine pointers. */
export const typeablePopupA11yProps = { role: "region", ref: typeablePopupRef } as const;

/**
 * `popupA11yProps` with a translatable name for nested popups. The ref keeps a stable identity (React attaches it once
 * per mount) and reads the latest `name` when the popup opens.
 *
 * @internal Menu content: `<BaseMenu.Positioner {...usePopupA11yProps(labels.submenu)}>`.
 * @example
 * ```tsx
 * import { Menu as BaseMenu } from "@base-ui/react/menu";
 * import { usePopupA11yProps } from "./popup-a11y";
 *
 * export function Popup({ children }: { children: React.ReactNode }) {
 *   const a11y = usePopupA11yProps((level) => `Untermenue ${level}`);
 *   return <BaseMenu.Positioner {...a11y}>{children}</BaseMenu.Positioner>;
 * }
 * ```
 * @see /overlays/dropdown-menu
 */
export function usePopupA11yProps(submenuName: SubmenuName = defaultSubmenuName) {
  const nameRef = useRef(submenuName);
  useLayoutEffect(() => {
    nameRef.current = submenuName;
  });
  const attach = useCallback(
    (positioner: HTMLElement | null) => popupRef(positioner, false, (level) => nameRef.current(level)),
    [],
  );
  return { role: "region", ref: attach } as const;
}

let counter = 0;

/**
 * A unique id for things created on the client (attachments, optimistic messages, chat turns):
 * `<prefix>-<time in base 36>-<count in base 36>`. Unique within a page load and sortable by creation.
 */
export function uid(prefix = "id") {
  counter += 1;
  return `${prefix}-${Date.now().toString(36)}-${counter.toString(36)}`;
}

/**
 * Dev-only console warning that prints each distinct message once. Silent unless a build tool says this is a
 * development build: `import.meta.env.DEV` (Vite and compatible bundlers) first, then `process.env.NODE_ENV`
 * (webpack, Next.js, Node) where `process` exists. When neither is available it counts as production, so a
 * browser that loads the package untouched never prints. Used for misuse that should be loud while developing
 * but never costs a user anything.
 */
declare const process: { env?: { NODE_ENV?: string } } | undefined;

/**
 * Decide whether this is a development build from the two signals a build tool can provide. Pure, so the
 * decision is testable; unknown means production.
 */
export function isDevelopmentBuild(viteDev: boolean | undefined, nodeEnv: string | undefined): boolean {
  if (typeof viteDev === "boolean") return viteDev;
  if (nodeEnv !== undefined) return nodeEnv !== "production";
  return false;
}

const seen = new Set<string>();

/** Print `message` through `console.warn` once per page load, in development builds only. */
export function warnOnce(message: string): void {
  const nodeEnv = typeof process !== "undefined" ? process.env?.NODE_ENV : undefined;
  // The literal `import.meta.env` is what Vite and compatible bundlers replace; this package has no Vite types of its own.
  // eslint-disable-next-line @typescript-eslint/ban-ts-comment -- ts-expect-error would fail wherever vite/client types exist
  // @ts-ignore -- ImportMeta.env exists only with vite/client types
  // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-member-access -- typed only where vite/client types exist
  const viteDev: boolean | undefined = import.meta.env?.DEV;
  if (!isDevelopmentBuild(viteDev, nodeEnv)) return;
  if (seen.has(message)) return;
  seen.add(message);
  console.warn(`[SheenUI] ${message}`);
}

/** Forget every message already printed. For tests. */
export function resetWarnOnce(): void {
  seen.clear();
}

"use client";

import { useRef } from "react";

import { useAmbientBeat } from "./beat";

/**
 * Drives paused Web Animations from the shared ambient beat (~30 Hz) instead of letting them free-run at the display rate.
 * Effects that sit behind glass use it: every glass surface above re-blurs when its backdrop changes, so the backdrop
 * must change only on the beat. Create the animations paused, move them in `seek(ms)`, and `on` is false while the
 * effect is off-screen, hidden or paused (the clock stops and so does the beat's cost). Returns the clock, in ms, so a
 * rebuilt animation can start in phase with `anim.currentTime = clock.current`.
 *
 * Accessibility: No UI of its own; gate it with `useLoopPlayback` so reduced motion, hidden tabs and off-screen keep it off.
 * Motion: Rides the shared beat, so it costs nothing while `on` is false.
 *
 * @example
 * ```tsx
 * import { useRef } from "react";
 * import { useBeatAnimations } from "@sheenui/theme";
 *
 * export function Glow() {
 *   const ref = useRef<HTMLDivElement>(null);
 *   const animation = useRef<Animation | null>(null);
 *   useBeatAnimations((ms) => {
 *     if (animation.current) animation.current.currentTime = ms;
 *   }, true);
 *   return <div ref={ref} aria-hidden="true" className="size-8 rounded-full bg-sheen-accent" />;
 * }
 * ```
 *
 * @see /foundations
 */
export function useBeatAnimations(seek: (ms: number) => void, on: boolean) {
  const clock = useRef(0);
  useAmbientBeat((_now, dt) => {
    clock.current += dt * 1000;
    seek(clock.current);
  }, on);
  return clock;
}

"use client";

import { useEffect, useEffectEvent } from "react";

import { COARSE_POINTER_QUERY } from "../hooks/use-media-query";

/**
 * THE BEAT: one frame clock for everything that changes BEHIND or ON glass. Ambient work runs at ~30 Hz; followers (pointer light) run every frame.
 *
 * A glass surface re-blurs its backdrop whenever anything under it changes. If the backdrop
 * drifts at 60 Hz, the pointer light at 60 Hz and a parallax layer on yet another frame, every
 * glass surface re-blurs on every frame. On the beat they all change on the SAME frames, at most
 * ~30 times a second (the Aurora prototype measured this as the difference between janky and
 * 60 fps pointer moves). Motion springs still smooth every frame; only DOM writes wait for a beat.
 *
 *   - ambient: backdrop loops (drift, aurora sky). They run while registered. Mid-scroll they get
 *     every 2nd beat (~15 fps; every 4th, ~7 fps, on touch screens, where a flick keeps the GPU
 *     and the main thread busy for seconds): the eye follows the content, not slow light. The
 *     beat owns one passive scroll listener for this (bound only while the loop runs), so every
 *     ambient loop is throttled on every scroller, with or without a pointer light or an aurora
 *     sky on the page.
 *   - followers: pointer-driven writes (rim light, parallax). They run while the beat is awake:
 *     `wakeBeat()` on every pointer move keeps it awake ~1.2 s (springs settling).
 *
 * The rAF loop stops itself when nothing is registered and nothing is awake (zero idle cost).
 */

type Tick = (now: number, dt: number) => void;

const beat = {
  raf: 0,
  slot: -1,
  periodMs: 1000 / 30,
  lastAmbient: 0,
  scrollingUntil: 0,
  wakeUntil: 0,
  ambient: new Set<Tick>(),
  follow: new Set<Tick>(),
};

const SCROLL_MS = 150;
let scrollBound = false;

/** Ambient beats skipped between two played ones while the page scrolls (touch screens skip more). */
let coarse: MediaQueryList | null = null;
function scrollStride() {
  if (typeof window === "undefined" || typeof window.matchMedia !== "function") return 2;
  coarse ??= window.matchMedia(COARSE_POINTER_QUERY); // a live list: .matches is always current
  return coarse.matches ? 4 : 2;
}

function onScroll() {
  beat.scrollingUntil = performance.now() + SCROLL_MS;
}

/** One passive scroll listener (capture: nested scrollers too), alive only while the loop runs. */
function bindScroll(on: boolean) {
  if (on === scrollBound || typeof window === "undefined") return;
  scrollBound = on;
  if (on) window.addEventListener("scroll", onScroll, { passive: true, capture: true });
  else window.removeEventListener("scroll", onScroll, { capture: true });
}

function loop(now: number) {
  if (beat.ambient.size === 0 && now >= beat.wakeUntil) {
    beat.raf = 0;
    beat.lastAmbient = 0;
    bindScroll(false);
    return;
  }
  beat.raf = requestAnimationFrame(loop);
  // Followers (pointer light) run on every frame: the light follows the cursor at display rate. They go first:
  // they read cached boxes and sometimes re-measure, and a measure placed after the ambient writes
  // (sky transforms, canvas size) would force a style/layout flush mid-frame.
  if (beat.follow.size > 0) beat.follow.forEach((fn) => fn(now, 0));
  // Ambient work is phase-locked to slots (every 2nd vsync at 60 Hz): one decision per frame for everyone.
  const slot = Math.floor(now / beat.periodMs);
  if (slot === beat.slot) return;
  beat.slot = slot;
  const scrolling = now < beat.scrollingUntil;
  if (beat.ambient.size > 0 && !(scrolling && slot % scrollStride() !== 0)) {
    const dt = beat.lastAmbient ? Math.min(0.1, (now - beat.lastAmbient) / 1000) : 0;
    beat.lastAmbient = now;
    beat.ambient.forEach((fn) => fn(now, dt));
  }
}

function start() {
  if (beat.raf || typeof requestAnimationFrame === "undefined") return;
  beat.raf = requestAnimationFrame(loop);
  bindScroll(true);
}

/** Run `fn` on every beat until the returned function is called (backdrop loops). */
export function addAmbient(fn: Tick) {
  beat.ambient.add(fn);
  start();
  return () => {
    beat.ambient.delete(fn);
  };
}

/** Run `fn` on every beat while the beat is awake (see wakeBeat). */
export function addFollower(fn: Tick) {
  beat.follow.add(fn);
  return () => {
    beat.follow.delete(fn);
  };
}

/** Keep followers running for `ms` (call on every pointer move). */
export function wakeBeat(ms = 1200) {
  if (typeof performance === "undefined") return;
  beat.wakeUntil = Math.max(beat.wakeUntil, performance.now() + ms);
  start();
}

/**
 * The page is scrolling: ambient loops drop to every 2nd beat for `ms`. The beat already listens
 * to every scroll event itself; call this for scrolling it cannot see (a programmatic pan, a
 * canvas drag) or to hold the throttle longer.
 */
export function markScrolling(ms = SCROLL_MS) {
  if (typeof performance === "undefined") return;
  beat.scrollingUntil = performance.now() + ms;
}

/**
 * True while any scroller is scrolling (the beat's own passive scroll listener saw an event in the last 150 ms; it is bound only
 * while a beat loop runs, so `markScrolling()` callers keep it accurate elsewhere). Live data uses it to skip a tick mid-scroll.
 */
export function isScrolling() {
  return typeof performance !== "undefined" && performance.now() < beat.scrollingUntil;
}

/** Beat rate in frames per second (30 by default; Lite glass uses 20). */
export function setBeatRate(fps: number) {
  beat.periodMs = 1000 / Math.max(1, Math.min(60, fps));
}

/**
 * Run `cb(now, dt)` on every ambient beat (~30 Hz, fewer while the page scrolls) while mounted and
 * `on`. The latest `cb` is always the one called, so it may close over fresh props and state.
 * `now` is a `requestAnimationFrame` timestamp in ms, `dt` the seconds since the last ambient beat (capped at 0.1).
 *
 * Accessibility: No UI of its own; gate decorative loops with `useMotionGate()` so reduced motion keeps them off.
 * Motion: One shared rAF clock for every ambient loop; it stops itself when nothing is registered.
 *
 * @example
 * ```tsx
 * import { useRef } from "react";
 * import { useAmbientBeat } from "@sheenui/theme";
 *
 * export function Drift() {
 *   const ref = useRef<HTMLDivElement>(null);
 *   useAmbientBeat((now) => {
 *     if (ref.current) ref.current.style.transform = `translateX(${Math.sin(now / 2000) * 20}px)`;
 *   });
 *   return <div ref={ref} aria-hidden="true" className="size-8 rounded-full bg-sheen-accent" />;
 * }
 * ```
 *
 * @see /foundations
 */
export function useAmbientBeat(cb: Tick, on = true) {
  const onBeat = useEffectEvent((now: number, dt: number) => {
    cb(now, dt);
  });
  useEffect(() => {
    if (!on) return;
    return addAmbient((now, dt) => {
      onBeat(now, dt);
    });
  }, [on]);
}

/**
 * Run `cb(now)` on every beat while the beat is awake (see `wakeBeat`), while mounted and `on`.
 * For pointer-driven DOM writes (rim light, parallax) that must change on the same frames as the
 * backdrop. The latest `cb` is always the one called.
 *
 * Accessibility: No UI of its own; pointer effects belong behind `useMotionGate().pointerFx`.
 * Motion: Followers run only while the beat is awake (about 1.2 s after the last `wakeBeat()`), then cost nothing.
 *
 * @example
 * ```tsx
 * import { useRef } from "react";
 * import { useBeatFollower } from "@sheenui/theme";
 *
 * // Placeholder: an internal helper of the motion engine, not part of the package entry.
 * declare function wakeBeat(): void;
 *
 * export function Follow() {
 *   const ref = useRef<HTMLDivElement>(null);
 *   const target = useRef({ x: 0, y: 0 });
 *   useBeatFollower(() => {
 *     if (ref.current) ref.current.style.transform = `translate(${target.current.x}px, ${target.current.y}px)`;
 *   });
 *   return (
 *     <div
 *       onPointerMove={(e) => {
 *         target.current = { x: e.clientX % 40, y: e.clientY % 40 };
 *         wakeBeat();
 *       }}
 *     >
 *       <div ref={ref} aria-hidden="true" className="size-6 rounded-full bg-sheen-accent" />
 *     </div>
 *   );
 * }
 * ```
 *
 * @see /foundations
 */
export function useBeatFollower(cb: Tick, on = true) {
  const onBeat = useEffectEvent((now: number, dt: number) => {
    cb(now, dt);
  });
  useEffect(() => {
    if (!on) return;
    return addFollower((now, dt) => {
      onBeat(now, dt);
    });
  }, [on]);
}

"use client";

import { type RefObject } from "react";
import { useInView, usePageInView, type UseInViewOptions } from "motion/react";

import { FINE_POINTER_QUERY, useMediaQuery } from "../hooks/use-media-query";
import { useGlassMode, useSheenReducedMotion } from "../hooks/use-preferences";

/**
 * True on a mouse or trackpad (`(hover: hover) and (pointer: fine)`), live; `false` on touch screens
 * and during server rendering.
 *
 * Accessibility: No UI of its own; never hide the only way to reach a function behind a hover.
 *
 * @example
 * ```tsx
 * import { useFinePointer } from "@sheenui/theme";
 *
 * export function Hint() {
 *   const fine = useFinePointer();
 *   return <p>{fine ? "Hover a card to see its light." : "Tap a card to open it."}</p>;
 * }
 * ```
 *
 * @see /foundations
 */
export function useFinePointer() {
  return useMediaQuery(FINE_POINTER_QUERY);
}

/**
 * Which motion tiers are allowed right now. Read once per component, branch on the
 * flags: `reduced` (OS setting or in-app switch), `pointerFx` (mouse/trackpad and not reduced) and
 * `richFx` (not reduced and not Lite glass). `pointerFx` is `false` during server rendering.
 *
 * Accessibility: Respects `prefers-reduced-motion` and the in-app reduce-motion switch; off-by-default effects cost nothing.
 * Motion: Pointer effects need a fine pointer; text blur and many parallax layers need Lite glass off.
 *
 * @example
 * ```tsx
 * import { useMotionGate } from "@sheenui/theme";
 *
 * export function Badge() {
 *   const { reduced, richFx } = useMotionGate();
 *   return <span className={richFx && !reduced ? "animate-pulse" : ""}>New</span>;
 * }
 * ```
 *
 * @see /foundations
 */
export function useMotionGate() {
  const reduced = useSheenReducedMotion();
  const [lite] = useGlassMode();
  const finePointer = useFinePointer();
  return {
    reduced,
    /** Pointer-driven effects (light, magnetic, tilt): mouse / trackpad only, never with reduced motion. */
    pointerFx: finePointer && !reduced,
    /** Costly extras (text blur, more than 2 parallax layers): off in lite glass mode. */
    richFx: !reduced && !lite,
  };
}

/** Options of {@link useLoopPlayback}. */
export type LoopPlaybackOptions = {
  /** The state of your own pause button: `true` stops the loop. Default `false`. */
  paused?: boolean;
  /** How far outside the viewport still counts as near, as a CSS margin string. Default `"100px"`. */
  margin?: UseInViewOptions["margin"];
  /** Share of the element that must be on screen instead of a margin (`"some"`, `"all"` or `0..1`). Overrides `margin`. */
  amount?: "some" | "all" | number;
  /** Stop the loop under reduced motion. Default `true`; pass `false` for a loop whose CSS already handles it. */
  respectReducedMotion?: boolean;
};

/**
 * Should a loop (ambient drift, beam, marquee, shimmer, typing dots, a live ticker) be playing?
 * Only when motion is allowed, the user has not paused it, it is near the viewport (100 px margin by default)
 * and the tab is visible. `ref` is the element the loop lives in; `options.paused` is your own pause button's
 * state. This is the one loop-visibility hook: every loop in the library, including the dashboards' live
 * tickers, asks it.
 *
 * Accessibility: Always offer a visible pause control for loops that run longer than 5 seconds (WCAG 2.2.2).
 * Motion: Pauses off-screen, in a hidden tab and under reduced motion.
 *
 * @example
 * ```tsx
 * import { useRef } from "react";
 * import { useLoopPlayback } from "@sheenui/theme";
 *
 * export function Ticker() {
 *   const ref = useRef<HTMLDivElement>(null);
 *   const playing = useLoopPlayback(ref); // or useLoopPlayback(ref, { paused: userPaused })
 *   return <div ref={ref} className="overflow-hidden" data-playing={playing}>Breaking news</div>;
 * }
 * ```
 *
 * @see /foundations
 */
export function useLoopPlayback(ref: RefObject<Element | null>, options: LoopPlaybackOptions = {}) {
  const { paused = false, margin = "100px", amount, respectReducedMotion = true } = options;
  const reduced = useSheenReducedMotion();
  const near = useInView(ref, amount === undefined ? { margin } : { amount });
  const pageVisible = usePageInView();
  return !(respectReducedMotion && reduced) && !paused && near && pageVisible;
}

/**
 * A tiny smoothing follower for pointer light: the light chases the pointer with an
 * exponential lerp (time constant 70 ms, about `follow.pointer`: no overshoot, caught up in ~350 ms) instead
 * of snapping, one `requestAnimationFrame` at a time, and goes idle as soon as it arrives.
 *
 * `to(x, y)` sets the target (the first call after `reset()` jumps there). `apply` receives the smoothed
 * position every frame: write a `translate` to a composited layer there, never a gradient position.
 * Plain data and DOM-free, so it is safe on the server. Reduced motion: do not create one (static light).
 *
 * @internal Not part of the public barrel: the example documents the module's own helpers.
 * @example
 * ```ts
 *
 * import { createLightFollower } from "./light-follower";
 *
 * export function attach(layer: HTMLElement) {
 *   const follower = createLightFollower((x, y) => {
 *     layer.style.translate = `${x}px ${y}px`;
 *   });
 *   layer.parentElement?.addEventListener("pointermove", (e) => follower.to(e.offsetX, e.offsetY));
 * }
 * ```
 */
export function createLightFollower(apply: (x: number, y: number) => void) {
  const TAU = 70;
  let tx = 0;
  let ty = 0;
  let cx = 0;
  let cy = 0;
  let primed = false;
  let raf = 0;
  let last = 0;
  const tick = (now: number) => {
    const k = 1 - Math.exp(-Math.min(64, now - last) / TAU);
    last = now;
    cx += (tx - cx) * k;
    cy += (ty - cy) * k;
    if (Math.abs(tx - cx) + Math.abs(ty - cy) > 0.25) {
      apply(cx, cy);
      raf = requestAnimationFrame(tick);
    } else {
      cx = tx;
      cy = ty;
      raf = 0;
      apply(cx, cy);
    }
  };
  return {
    /** Moves the target; the first call after `reset()` jumps straight there. */
    to(x: number, y: number) {
      tx = x;
      ty = y;
      if (!primed) {
        primed = true;
        cx = x;
        cy = y;
        apply(x, y);
        return;
      }
      if (!raf) {
        last = performance.now();
        raf = requestAnimationFrame(tick);
      }
    },
    /** Forgets the position (the pointer left): the next `to` jumps instead of gliding in from far away. */
    reset() {
      primed = false;
    },
    /** Cancels the pending frame. */
    stop() {
      if (raf) cancelAnimationFrame(raf);
      raf = 0;
    },
  };
}

"use client";

import { useEffect } from "react";

/**
 * Looping CSS animations (skeleton shimmer, indeterminate bars, floating blobs, equalizer bars,
 * spinners) pause while their element is off-screen and resume when it comes back. Chrome keeps ticking, and restyling, an animation that
 * nobody can see; on a page with a dozen of them that is steady main-thread and compositor work.
 *
 * ONE hook for the whole app, no per-component wiring:
 *   - an `animationstart` listener (capture, so it sees every CSS animation as it begins) plus a
 *     single sweep of `document.getAnimations()` at mount find the infinite CSS animations;
 *   - one shared IntersectionObserver (100 px margin) watches their elements and pauses /
 *     resumes only the animations it paused itself.
 * Web Animations started from script (Motion) are never touched: only `CSSAnimation`s are.
 * Reduced motion needs nothing here: it already turns loops into a single 1 ms pass.
 */

function isInfiniteCss(animation: Animation): animation is CSSAnimation {
  return (
    typeof CSSAnimation === "function" &&
    animation instanceof CSSAnimation &&
    animation.effect?.getComputedTiming().iterations === Infinity
  );
}

function targetOf(animation: Animation) {
  const effect = animation.effect as KeyframeEffect | null;
  // Pseudo-element animations (::before / ::after) report their originating element as target.
  return effect ? effect.target : null;
}

/**
 * The animations an element owns, its own pseudo-elements (::before / ::after / ...) included.
 * Plain `element.getAnimations()` omits the pseudo-element ones, so a loop drawn on a pseudo-element
 * would never pause; `{ subtree: true }` lists them (and the descendants', filtered out here).
 */
function ownAnimations(element: Element) {
  return element.getAnimations({ subtree: true }).filter((a) => targetOf(a) === element);
}

/** What one mounted `useOffscreenLoops` can report about itself (after sweeping out anything that left the document). */
type LoopRegistry = { stats: () => { anchors: number; elements: number } };
const registries = new Set<LoopRegistry>();

/**
 * How many anchors and animated elements the mounted `useOffscreenLoops` hooks still hold. A sweep runs first, so this
 * is the number of loops that are really in the document (0 after every spinner is gone).
 *
 * @internal Test and debugging aid, not part of the public barrel.
 */
export function offscreenLoopStats() {
  let anchors = 0;
  let elements = 0;
  for (const registry of registries) {
    const stats = registry.stats();
    anchors += stats.anchors;
    elements += stats.elements;
  }
  return { anchors, elements };
}

/**
 * Pause every looping CSS animation while its element (its parent, for loops that move their own element) is off-screen, resume it when it returns.
 * `SheenMotionProvider` already calls it once for the whole app; call it yourself only without the provider. It finds the loops itself, so no
 * component needs wiring. Elements are tracked weakly and forgotten (unobserved) as soon as they leave the
 * document, so a long-lived app that mounts and unmounts spinners and skeletons does not accumulate them.
 *
 * Props: `enabled` (boolean, default `true`): turn the pausing off, e.g. while debugging.
 *
 * Accessibility: No UI of its own. A paused loop is off-screen, so nothing visible changes; motion that Motion starts from script is never touched, and reduced motion needs nothing from it.
 * Motion: Pauses `CSSAnimation`s with infinite iterations through one shared IntersectionObserver (100 px margin).
 *
 * @example
 * ```tsx
 * import { type ReactNode } from "react";
 * import { useOffscreenLoops } from "@sheenui/theme";
 *
 * export function Root({ children }: { children: ReactNode }) {
 *   useOffscreenLoops();
 *   return <main>{children}</main>;
 * }
 * ```
 *
 * @see /foundations
 */
export function useOffscreenLoops(enabled = true) {
  useEffect(() => {
    if (!enabled || typeof window === "undefined" || typeof IntersectionObserver !== "function") return;
    // A loop usually moves its own element (a shimmer sweeping inside an overflow-hidden skeleton):
    // while it is out of its own clip the element reports "not intersecting" although the loop is
    // on screen, and a paused loop could never come back. So the observer watches the element's
    // parent, which stays put, and pauses or resumes every loop that hangs off it.
    const groups = new WeakMap<Element, Set<WeakRef<Element>>>(); // observed anchor -> animated elements
    const anchorRefs = new Set<WeakRef<Element>>(); // weak handles of the observed anchors (iteration and unobserve)
    const anchorOf = new WeakMap<Element, Element>();
    const inspected = new WeakSet<Element>(); // elements whose animations were listed once (a restart needs no second listing)
    const away = new WeakSet<Element>(); // anchors currently off-screen
    const paused = new WeakMap<Element, Animation[]>(); // animated element -> loops this hook paused
    const pausedElements = new Set<WeakRef<Element>>(); // iteration handle for `paused`, pruned with the rest
    const handles = new WeakMap<Element, WeakRef<Element>>();
    const refOf = (element: Element) => {
      let ref = handles.get(element);
      if (!ref) handles.set(element, (ref = new WeakRef(element)));
      return ref;
    };

    const pauseLoops = (element: Element) => {
      const running = ownAnimations(element).filter((a) => a.playState === "running" && isInfiniteCss(a));
      for (const animation of running) animation.pause();
      if (running.length) {
        paused.set(element, [...(paused.get(element) ?? []), ...running]);
        pausedElements.add(refOf(element));
      }
    };
    const resumeLoops = (element: Element) => {
      // A hidden tab keeps its loops paused: play() would override the CSS pause of html[data-page-hidden].
      // They come back on visibilitychange (resumeVisible).
      if (document.visibilityState === "hidden") return;
      for (const animation of paused.get(element) ?? []) if (animation.playState === "paused") animation.play();
      paused.delete(element);
      pausedElements.delete(refOf(element));
    };

    const forget = (anchor: Element) => {
      observer.unobserve(anchor);
      groups.delete(anchor);
      away.delete(anchor);
      anchorRefs.delete(refOf(anchor));
    };

    // Drop every element that left the document and every anchor that has nothing left to pause.
    const sweep = () => {
      for (const anchorRef of anchorRefs) {
        const anchor = anchorRef.deref();
        if (!anchor) {
          anchorRefs.delete(anchorRef);
          continue;
        }
        const group = groups.get(anchor);
        if (group) {
          for (const ref of group) {
            const element = ref.deref();
            if (element?.isConnected) continue;
            group.delete(ref);
            if (element) {
              paused.delete(element);
              anchorOf.delete(element);
            }
          }
        }
        // A detached anchor is forgotten even if its children linger: they left the document with it.
        if (!group?.size || !anchor.isConnected) forget(anchor);
      }
      for (const ref of pausedElements) if (!ref.deref()?.isConnected) pausedElements.delete(ref);
    };
    let sweepQueued = false;
    const queueSweep = () => {
      if (sweepQueued) return;
      sweepQueued = true;
      queueMicrotask(() => {
        sweepQueued = false;
        sweep();
      });
    };

    // Raw observer on purpose: one shared observer over every registered loop anchor, with its own sweep.
    const observer = new IntersectionObserver(
      (entries) => {
        for (const { target: anchor, isIntersecting } of entries) {
          // A detached anchor reports one last "not intersecting": that is the cue to forget it.
          if (!anchor.isConnected) {
            sweep();
            continue;
          }
          const group = groups.get(anchor);
          if (!group) continue;
          if (isIntersecting) away.delete(anchor);
          else away.add(anchor);
          for (const ref of group) {
            const element = ref.deref();
            if (!element) continue;
            if (isIntersecting) resumeLoops(element);
            else pauseLoops(element);
          }
        }
      },
      { rootMargin: "100px" },
    );

    const consider = (animation: Animation) => {
      if (!isInfiniteCss(animation)) return;
      const target = targetOf(animation);
      if (!target || anchorOf.has(target)) return;
      const anchor = target.parentElement ?? target;
      anchorOf.set(target, anchor);
      const group = groups.get(anchor);
      if (group) group.add(refOf(target));
      else {
        groups.set(anchor, new Set([refOf(target)]));
        anchorRefs.add(refOf(anchor));
        observer.observe(anchor);
      }
    };
    // Inspect one animated element: list its animations once (a restart needs no second listing) and pause its loops
    // when it started off-screen. getAnimations() flushes style, so it never runs inside the animationstart event itself.
    const inspect = (target: Element) => {
      if (!target.isConnected) return;
      if (!inspected.has(target)) {
        inspected.add(target);
        ownAnimations(target).forEach(consider);
      }
      // A loop (re)started while its element is off-screen waits for it to come back.
      const anchor = anchorOf.get(target);
      if (anchor && away.has(anchor)) pauseLoops(target);
    };
    // Started elements queue up and are inspected together in idle time: the load phase (dozens of entrance animations
    // starting while the page hydrates) never pays for a style flush per element.
    const queue = new Set<Element>();
    let scheduled = false;
    let disposed = false;
    let first = false;
    const drain = () => {
      scheduled = false;
      if (disposed) return;
      if (first) document.documentElement.getAnimations({ subtree: true }).forEach(consider);
      first = false;
      for (const target of queue) inspect(target);
      queue.clear();
      queueSweep();
    };
    // Safari has no requestIdleCallback: a short timer stands in.
    const schedule = () => {
      if (scheduled) return;
      scheduled = true;
      const ric = (window as { requestIdleCallback?: Window["requestIdleCallback"] }).requestIdleCallback;
      if (ric) ric(drain, { timeout: 500 });
      else setTimeout(drain, 120);
    };
    const onStart = (event: Event) => {
      const target = event.target;
      if (!(target instanceof Element)) return;
      queue.add(target);
      schedule();
    };

    // A hidden tab: script-played loops (resumed after a scroll) ignore the CSS pause, so every running
    // infinite CSS loop is paused here, and the ones whose anchor is on screen play again when the tab returns.
    const hiddenPaused = new Set<Animation>();
    const onVisibility = () => {
      if (document.visibilityState === "hidden") {
        for (const animation of document.getAnimations()) {
          if (animation.playState === "running" && isInfiniteCss(animation)) {
            animation.pause();
            hiddenPaused.add(animation);
          }
        }
        return;
      }
      for (const animation of hiddenPaused) {
        const target = targetOf(animation);
        const anchor = target && anchorOf.get(target);
        const stillAway = anchor ? away.has(anchor) : false;
        if (animation.playState === "paused" && !stillAway && !(target && paused.get(target)?.includes(animation))) {
          animation.play();
        }
      }
      hiddenPaused.clear();
      for (const ref of [...pausedElements]) {
        const element = ref.deref();
        const anchor = element && anchorOf.get(element);
        if (element && anchor && !away.has(anchor)) resumeLoops(element);
      }
    };
    document.addEventListener("visibilitychange", onVisibility);

    const registry: LoopRegistry = {
      stats: () => {
        sweep();
        let elements = 0;
        for (const anchorRef of anchorRefs) {
          const anchor = anchorRef.deref();
          elements += (anchor ? groups.get(anchor)?.size : 0) ?? 0;
        }
        return { anchors: anchorRefs.size, elements };
      },
    };
    registries.add(registry);

    // The first listing of the loops already running waits for idle time after the page has loaded: the whole-document
    // getAnimations() forces a full style flush, which used to land inside the hydration tasks.
    const startFirst = () => {
      first = true;
      schedule();
    };
    if (document.readyState === "complete") startFirst();
    else window.addEventListener("load", startFirst, { once: true });
    document.addEventListener("animationstart", onStart, true);
    document.addEventListener("animationcancel", queueSweep, true);
    return () => {
      registries.delete(registry);
      document.removeEventListener("visibilitychange", onVisibility);
      hiddenPaused.clear();
      document.removeEventListener("animationstart", onStart, true);
      document.removeEventListener("animationcancel", queueSweep, true);
      window.removeEventListener("load", startFirst);
      disposed = true;
      queue.clear();
      observer.disconnect();
      for (const ref of pausedElements) {
        const element = ref.deref();
        for (const animation of (element ? paused.get(element) : undefined) ?? [])
          if (animation.playState === "paused") animation.play();
      }
      pausedElements.clear();
      anchorRefs.clear();
    };
  }, [enabled]);
}

"use client";

import { useEffect } from "react";

import { addFollower, isScrolling, markScrolling, wakeBeat } from "./beat";

/**
 * "Glass catches light" for every glass surface on the page.
 *
 * ONE pointer listener for the whole app. On every frame (see beat.ts) it lights the glass
 * surfaces nearest the pointer by writing, inline on each surface:
 *   --sheen-mx / --sheen-my   pointer position inside the surface (px): the rim's hot spot and the inner light
 *   --sheen-ra                angle from the surface's centre to the pointer: the rim's broad lit side
 *   --sheen-lit               0..1, how close the pointer is (the rim brightens as it nears)
 * and marks it [data-sheen-lit] (its rim layer gets its own compositor layer while lit).
 * The style presets draw the rim from these (glass.css + styles/presets/*.css).
 *
 * Cost rules:
 *   - No React state: plain DOM writes, batched on the beat (reads first, then writes).
 *   - The variables are registered `inherits: false`, so a write restyles the surface and its
 *     rim pseudo-element only, never the surface's whole subtree.
 *   - At most MAX_LIT surfaces within REACH px are lit; every other surface keeps no inline
 *     light at all (no restyle, no repaint).
 *   - Boxes are cached in PAGE coordinates, so scrolling the window never touches layout: the
 *     viewport box is the cached box minus the scroll offset. Only surfaces within REACH px of
 *     the viewport (an IntersectionObserver says which) are ever measured; a box is re-read when
 *     its surface is resized (ResizeObserver), enters the viewport band, the window resizes, a
 *     nested scroller scrolls, or every REFRESH_MS as a safety net (reflow above it). Sticky and
 *     fixed surfaces keep viewport coordinates and are re-read at most every PINNED_MS while the
 *     page scrolls (a sticky bar sticking or letting go).
 *   - Pointer moves never read layout. Fine pointer only and never with reduced motion: then
 *     every surface rests in the ambient light from the top-left (the CSS defaults).
 * Opt a surface out with data-sheen-light="off"; opt any element in with data-sheen-light.
 */

/** Pointer position, shared with backdrops (the aurora sky lifts under it). Viewport fractions. */
export const sheenPointer = { x: 0.62, y: 0.3, on: false };

const SELECTOR = ".glass-1, .glass-2, .glass-3, [data-sheen-light]";
const REACH = 260;
const MAX_LIT = 6;
/** Resting light: the sun at the top-left (matches the CSS defaults). */
const REST_ANGLE = -40;
const REST_LIT = 0.42;
const FLARE_SPEED = 2.4; // px per ms
/** The surface list is re-queried at most this often (ms), while the beat is awake. */
const DISCOVER_MS = 1000;
/** Safety-net re-read of the boxes in reach (ms), for reflow that resizes nothing. */
const REFRESH_MS = 1500;
/** A sticky / fixed surface is re-read at most this often (ms) while the window scrolls. */
const PINNED_MS = 120;

type LitState = { lit: number; ra: number };

type Surface = {
  el: HTMLElement;
  /** Box in page coordinates (viewport box + scroll offset at the time it was read). */
  x: number;
  y: number;
  w: number;
  h: number;
  /** Within REACH px of the viewport (IntersectionObserver); unknown (true) until it reports. */
  near: boolean;
  /** The box must be read again before it is used. */
  stale: boolean;
  /** Sticky / fixed (it or an ancestor): its box is kept in VIEWPORT coordinates (x / y above), not page ones. null = not yet known. */
  pinned: boolean | null;
  /** When the box was last read. */
  at: number;
};

function isPinned(el: HTMLElement) {
  for (let node: HTMLElement | null = el; node && node !== document.body; node = node.parentElement) {
    const position = getComputedStyle(node).position;
    if (position === "fixed" || position === "sticky") return true;
  }
  return false;
}

/**
 * The pointer rim light for every glass surface (the work is described at the top of this file).
 * Call it once near the root (SheenBackdrop already does).
 *
 * Props: `enabled` (boolean, required): `false` turns the light off and leaves every surface in
 * the ambient light from the top-left.
 *
 * Accessibility: Decorative: no focus, no pointer capture, never with reduced motion or on touch.
 * Glass: Writes four custom properties on the nearest glass surfaces only; no layout reads on pointer moves or window scrolls.
 * Motion: Runs every frame as a beat follower and only while the pointer is moving or the light is easing.
 *
 * @example
 * ```tsx
 * import { type ReactNode } from "react";
 * import { useSheenPointerLight } from "@sheenui/theme";
 *
 * export function Root({ children }: { children: ReactNode }) {
 *   useSheenPointerLight(true);
 *   return <main>{children}</main>;
 * }
 * ```
 *
 * @see /foundations
 */
export function useSheenPointerLight(enabled: boolean) {
  useEffect(() => {
    if (!enabled || typeof window === "undefined") return;
    const root = document.documentElement;
    const state = new Map<HTMLElement, LitState>();
    const surfaces = new Map<HTMLElement, Surface>();
    let list: Surface[] = [];
    let discoveredAt = -1e9;
    let refreshedAt = -1e9;
    let allStale = true;
    let pinnedDirty = false;
    // The window scrolled since the offsets were cached; they are re-read on the beat, and only while a pointer is
    // there to light anything (touch and idle pages never read them: scrollX / scrollY flush style and layout).
    let scrollStale = false;
    // The scroll offset and the viewport size are cached from the scroll / resize events:
    // window.scrollX / scrollY / innerHeight can flush style and layout when read mid-frame.
    let sx = window.scrollX;
    let sy = window.scrollY;
    let vh = window.innerHeight;
    let vw = window.innerWidth;
    let px = -1e5;
    let py = -1e5;
    let active = false;
    let lastX = 0;
    let lastY = 0;
    let lastT = 0;
    let flareTimer = 0;
    // Work is done only while something changed (pointer, scroll, resize) or the light is still easing:
    // an idle pointer repaints nothing, and followers run at display rate only while dirty.
    let dirty = true;

    // Which surfaces are near the viewport, and which changed size: both reported by the browser
    // between frames, with no layout read from us.
    // Raw observer on purpose: one shared observer over many surfaces, reading every entry (observeIntersection
    // is the single-target helper).
    const visibility =
      typeof IntersectionObserver === "function"
        ? new IntersectionObserver(
            (entries) => {
              for (const entry of entries) {
                const s = surfaces.get(entry.target as HTMLElement);
                if (!s) continue;
                // A removed surface reports one last "not intersecting": let go of it now, so the page it came
                // from is not kept alive by this Map or the observer.
                if (!entry.target.isConnected) {
                  forget(s);
                  list = list.filter((x) => x !== s);
                  continue;
                }
                if (entry.isIntersecting && !s.near) s.stale = true;
                s.near = entry.isIntersecting;
              }
            },
            { rootMargin: `${REACH}px` },
          )
        : null;
    const resizes =
      typeof ResizeObserver === "function"
        ? new ResizeObserver((entries) => {
            for (const entry of entries) {
              const s = surfaces.get(entry.target as HTMLElement);
              if (s) s.stale = true;
            }
          })
        : null;

    const release = (el: HTMLElement) => {
      state.delete(el);
      el.removeAttribute("data-sheen-lit");
      for (const p of ["--sheen-mx", "--sheen-my", "--sheen-ra", "--sheen-lit"]) el.style.removeProperty(p);
    };

    const forget = (s: Surface) => {
      surfaces.delete(s.el);
      visibility?.unobserve(s.el);
      resizes?.unobserve(s.el);
    };

    /** Re-query the surfaces (a cheap selector match, no layout) and (un)observe the changes. */
    const discover = (now: number) => {
      discoveredAt = now;
      const found = new Set<HTMLElement>();
      for (const el of document.querySelectorAll<HTMLElement>(SELECTOR)) {
        if (el.dataset.sheenLight === "off" || el instanceof HTMLInputElement || el instanceof HTMLTextAreaElement)
          continue;
        found.add(el);
        if (surfaces.has(el)) continue;
        surfaces.set(el, { el, x: 0, y: 0, w: 0, h: 0, near: true, stale: true, pinned: null, at: 0 });
        visibility?.observe(el);
        resizes?.observe(el);
      }
      for (const s of surfaces.values()) if (!found.has(s.el)) forget(s);
      list = Array.from(surfaces.values());
    };

    /** Drop every surface (and lit state) whose element left the document: no layout, no queries. */
    const sweep = () => {
      let removed = false;
      for (const s of surfaces.values()) {
        if (s.el.isConnected) continue;
        forget(s);
        removed = true;
      }
      for (const el of state.keys()) if (!el.isConnected) state.delete(el);
      if (removed) list = Array.from(surfaces.values());
    };

    /**
     * Store a box. `viewportLeft` / `viewportTop` are viewport coordinates; the scroll offset when
     * they were taken turns them into page ones (pinned surfaces keep viewport coordinates).
     */
    const store = (s: Surface, left: number, top: number, width: number, height: number) => {
      s.pinned ??= isPinned(s.el);
      s.x = s.pinned ? left : left + sx;
      s.y = s.pinned ? top : top + sy;
      s.w = width;
      s.h = height;
    };

    /**
     * Boxes without a forced layout: a one-shot IntersectionObserver reports every target's
     * bounding box with its first callback, computed by the browser in its own rendering step
     * (a getBoundingClientRect here would flush style and layout in the middle of our frame).
     * The boxes land one frame later; until then the old box (or none) is used.
     */
    const measure = (due: Surface[]) => {
      if (!due.length) return;
      if (typeof IntersectionObserver !== "function") {
        for (const s of due) {
          const r = s.el.getBoundingClientRect();
          store(s, r.left, r.top, r.width, r.height);
        }
        return;
      }
      // Raw observer on purpose: a one-shot read of boundingClientRect for many surfaces, no layout read.
      const once = new IntersectionObserver((entries) => {
        once.disconnect();
        for (const entry of entries) {
          const s = surfaces.get(entry.target as HTMLElement);
          if (!s) continue;
          const r = entry.boundingClientRect;
          store(s, r.left, r.top, r.width, r.height);
        }
      });
      for (const s of due) once.observe(s.el);
    };

    /** READ phase: ask for the boxes of what is near the viewport and stale (no layout read here). */
    const read = (now: number) => {
      if (now - discoveredAt > DISCOVER_MS) discover(now);
      if (now - refreshedAt > REFRESH_MS) {
        refreshedAt = now;
        allStale = true;
      }
      let waiting = false;
      const due: Surface[] = [];
      for (const s of list) {
        if (!s.near) continue;
        const pinnedDue = pinnedDirty && s.pinned !== false;
        if (!(allStale || s.stale || pinnedDue)) continue;
        if (!allStale && !s.stale && now - s.at <= PINNED_MS) {
          waiting = true; // asked for on a later beat, so a sticky bar's last move still lands
          continue;
        }
        s.at = now;
        s.stale = false;
        due.push(s);
      }
      allStale = false;
      pinnedDirty = waiting;
      measure(due);
      // Boxes land one frame later, and a sticky bar may still be moving: look again next frame.
      if (due.length > 0 || waiting) dirty = true;
    };

    const update = (now: number) => {
      if (!dirty || (!active && state.size === 0)) return;
      // The light holds still while the page scrolls: under a resting pointer the surfaces sliding past it would each get
      // inline style writes on every frame (about 1,000 style invalidations per 2 s of scroll on the data table, one
      // frame in three over budget at 4x). It catches up 150 ms after the last scroll event.
      if (isScrolling()) {
        wakeBeat(200);
        return;
      }
      dirty = false;
      if (scrollStale) {
        scrollStale = false;
        sx = window.scrollX;
        sy = window.scrollY;
      }
      read(now);

      // Pick the nearest surfaces within reach (viewport box = cached page box minus the scroll).
      const near: { el: HTMLElement; left: number; top: number; w: number; h: number; d: number }[] = [];
      if (active) {
        for (const s of list) {
          if (!s.near || s.w < 2 || s.h < 2) continue;
          // Pinned surfaces hold viewport coordinates, the others page coordinates.
          const left = s.pinned ? s.x : s.x - sx;
          const top = s.pinned ? s.y : s.y - sy;
          if (top + s.h < 0 || top > vh) continue;
          const dx = Math.max(left - px, 0, px - (left + s.w));
          const dy = Math.max(top - py, 0, py - (top + s.h));
          const d = Math.hypot(dx, dy);
          if (d <= REACH) near.push({ el: s.el, left, top, w: s.w, h: s.h, d });
        }
        near.sort((a, b) => a.d - b.d || a.w * a.h - b.w * b.h);
        near.length = Math.min(near.length, MAX_LIT);
      }
      const keep = new Set(near.map((n) => n.el));

      // WRITE phase: light the near ones (eased on the beat, no CSS transition), fade the rest out.
      let easing = false;
      for (const { el, left, top, w, h, d } of near) {
        const prev = state.get(el) ?? { lit: REST_LIT, ra: REST_ANGLE };
        let a = (Math.atan2(px - (left + w / 2), -(py - (top + h / 2))) * 180) / Math.PI;
        // Continuous angle, so the light never spins the long way round.
        while (a - prev.ra > 180) a -= 360;
        while (a - prev.ra < -180) a += 360;
        const target = 1 - d / REACH;
        const next = { lit: prev.lit + (target - prev.lit) * 0.23, ra: prev.ra + (a - prev.ra) * 0.29 };
        if (Math.abs(target - next.lit) > 0.01 || Math.abs(a - next.ra) > 0.5) easing = true;
        if (!state.has(el)) el.setAttribute("data-sheen-lit", "");
        state.set(el, next);
        el.style.setProperty("--sheen-mx", `${(px - left).toFixed(1)}px`);
        el.style.setProperty("--sheen-my", `${(py - top).toFixed(1)}px`);
        el.style.setProperty("--sheen-ra", `${next.ra.toFixed(1)}deg`);
        el.style.setProperty("--sheen-lit", next.lit.toFixed(3));
      }
      for (const [el, s] of state) {
        if (keep.has(el)) continue;
        if (!el.isConnected) {
          state.delete(el);
          continue;
        }
        const lit = s.lit + (REST_LIT - s.lit) * 0.19;
        const ra = s.ra + (REST_ANGLE - s.ra) * 0.19;
        if (Math.abs(lit - REST_LIT) < 0.02 && Math.abs(ra - REST_ANGLE) < 2) {
          release(el);
          continue;
        }
        easing = true;
        state.set(el, { lit, ra });
        el.style.setProperty("--sheen-ra", `${ra.toFixed(1)}deg`);
        el.style.setProperty("--sheen-lit", lit.toFixed(3));
      }
      if (easing) {
        dirty = true;
        wakeBeat(120);
      }
    };

    const onMove = (event: PointerEvent) => {
      if (event.pointerType === "touch") return;
      const dt = Math.max(1, event.timeStamp - lastT);
      const speed = Math.hypot(event.clientX - lastX, event.clientY - lastY) / dt;
      lastX = event.clientX;
      lastY = event.clientY;
      lastT = event.timeStamp;
      if (speed > FLARE_SPEED && dt < 80) {
        // A fast flick: the reflection flares for a moment.
        root.setAttribute("data-sheen-flare", "");
        window.clearTimeout(flareTimer);
        flareTimer = window.setTimeout(() => root.removeAttribute("data-sheen-flare"), 180);
      }
      px = event.clientX;
      py = event.clientY;
      active = true;
      dirty = true;
      sheenPointer.x = px / vw;
      sheenPointer.y = py / vh;
      sheenPointer.on = true;
      wakeBeat();
    };
    const onLeave = (event: PointerEvent) => {
      if (event.relatedTarget) return;
      active = false;
      dirty = true;
      sheenPointer.on = false;
      px = py = -1e5;
      wakeBeat(400);
    };
    const onScroll = (event: Event) => {
      // The window scrolling needs no re-read (page boxes minus the offset); a nested scroller
      // moves its surfaces without the window knowing, so those boxes are read again.
      if (event.target === document || event.target === document.documentElement) {
        scrollStale = true; // the offsets are re-read on the next beat, not here (a read flushes style and layout)
        pinnedDirty = true; // sticky / fixed surfaces may have moved
      } else {
        allStale = true;
      }
      dirty = true;
      markScrolling();
      if (active) wakeBeat(300);
    };
    const onResize = () => {
      vw = window.innerWidth;
      vh = window.innerHeight;
      scrollStale = true;
      allStale = true;
      dirty = true;
    };

    // Surfaces removed with their page (a route change) are released within a couple of seconds, even with the
    // pointer idle and the beat asleep; the IntersectionObserver report above usually gets there first.
    const sweepTimer = window.setInterval(sweep, 2000);
    const stopFollow = addFollower(update);
    window.addEventListener("pointermove", onMove, { passive: true });
    document.addEventListener("pointerout", onLeave);
    window.addEventListener("scroll", onScroll, { passive: true, capture: true });
    window.addEventListener("resize", onResize);
    return () => {
      stopFollow();
      window.clearInterval(sweepTimer);
      window.clearTimeout(flareTimer);
      root.removeAttribute("data-sheen-flare");
      window.removeEventListener("pointermove", onMove);
      document.removeEventListener("pointerout", onLeave);
      window.removeEventListener("scroll", onScroll, { capture: true });
      window.removeEventListener("resize", onResize);
      visibility?.disconnect();
      resizes?.disconnect();
      surfaces.clear();
      list = [];
      for (const el of Array.from(state.keys())) release(el);
      sheenPointer.on = false;
    };
  }, [enabled]);
}

import type { TargetAndTransition, Transition, Variants } from "motion/react";

import { budgetStagger, distance, duration, exitTransition, follow, scaleTo, spring, staggerStep } from "./tokens";

/**
 * Ready-made animation presets. Each has a full and a reduced version:
 * the reduced one keeps opacity feedback but drops movement and scaling.
 *
 * Entrances spring in; exits are shorter, ease in and never overshoot.
 * Variant names: "hidden" → "visible" on enter, "exit" on leave (with AnimatePresence).
 */

/** Transition for anything leaving: duration.exit with ease.exit. (Also exported from tokens.) */
export { exitTransition };

/** Opacity tween inside a spring entrance: a fade never springs. */
const fadeTween = { type: "tween", duration: duration.base } as const;

/**
 * Variants for a fade-and-rise entrance (`hidden`, `visible`, `exit`), each with a `full` and a
 * `reduced` (opacity only) version. Plain data: safe on the server.
 */
export const fadeUp = {
  full: {
    hidden: { opacity: 0, y: 12 },
    visible: { opacity: 1, y: 0, transition: { ...spring.gentle, opacity: fadeTween } },
    exit: { opacity: 0, y: 6, transition: exitTransition },
  },
  reduced: {
    hidden: { opacity: 0 },
    visible: { opacity: 1, transition: { duration: duration.fast } },
    exit: { opacity: 0, transition: exitTransition },
  },
} satisfies Record<string, Variants>;

/**
 * Variants for a small scale-and-fade entrance (`hidden`, `visible`, `exit`), each with a `full` and a
 * `reduced` (opacity only) version. Plain data: safe on the server.
 */
export const scaleIn = {
  full: {
    hidden: { opacity: 0, scale: scaleTo.popFrom },
    visible: { opacity: 1, scale: 1, transition: { ...spring.snappy, opacity: fadeTween } },
    exit: { opacity: 0, scale: scaleTo.press, transition: exitTransition },
  },
  reduced: {
    hidden: { opacity: 0 },
    visible: { opacity: 1, transition: { duration: duration.fast } },
    exit: { opacity: 0, transition: exitTransition },
  },
} satisfies Record<string, Variants>;

/**
 * Stand-alone exit target for AnimatePresence children: `exit={reduced ? exit.reduced : exit.full}`.
 * A small shrink plus fade, no translation, so it reads as "dismissed" rather than "moved".
 */
export const exit = {
  full: { opacity: 0, scale: 0.98, transition: exitTransition },
  reduced: { opacity: 0, transition: exitTransition },
} satisfies Record<string, TargetAndTransition>;

/**
 * Parent variant that staggers its children's "visible" state. Uses `delayChildren` with a
 * budgeted stagger (the old `staggerChildren` option is deprecated in Motion 14), so the whole
 * group never spreads over more than STAGGER_BUDGET (0.4 s), however many children.
 */
export const stagger = (step: number = staggerStep.items): Variants => ({
  hidden: {},
  visible: { transition: { delayChildren: budgetStagger(step) } },
});

/** The press spring as a transition. `out: true`: the RELEASE uses it too. */
const pressSpring = { type: "spring", ...follow.press, out: true } satisfies Transition;

/** Hover lift + press physics for interactive surfaces (release rebounds on the press spring). */
export const hoverLift = {
  whileHover: { y: -distance.nudge, transition: spring.snappy },
  whileTap: { scale: scaleTo.press, y: 0, transition: pressSpring },
};

/** Press physics: sink to 0.97 on the stiff press spring, rebound 1.5% on release. */
export const press = {
  whileTap: { scale: scaleTo.press, transition: pressSpring },
};

"use client";

import { useEffect, type ComponentProps } from "react";
import type { ReactNode } from "react";
import { MotionConfig } from "motion/react";

import { useSheenReducedMotion } from "../hooks/use-preferences";
import { useOffscreenLoops } from "./offscreen-loops";
import { spring } from "./tokens";

/**
 * One MotionConfig for the whole app. Without it Motion runs with its default
 * `reducedMotion: "never"` and ignores the OS setting completely.
 *
 *   - reducedMotion: "always" when the OS asks for reduced motion OR html[data-motion="reduced"]
 *     is on (read live, see useSheenReducedMotion); otherwise "user" (Motion follows the OS).
 *     With it, Motion skips x / y / scale / rotate / size / layout animations. It does NOT cover
 *     `transform` strings, filter, clipPath or MotionValues you drive yourself: those branch on
 *     useMotionGate().
 *   - transition: the default for any motion component that sets none (spring.smooth).
 *   - skipAnimations: the `skipAnimations` prop (default false). Visual-test harnesses set it so every value jumps to its end;
 *     the library itself never reads the URL.
 *
 * Each motion component reads `reducedMotion` once, when it mounts: remount the routed page
 * when the preference flips (key it on useSheenReducedMotion()), not the whole shell.
 *
 * Props: `children` (ReactNode, required), `nonce` (string, optional: the CSP nonce for the
 * styles Motion injects) and `skipAnimations` (boolean, default false: jump every animation to its end, for screenshot tests).
 *
 * Accessibility: Makes Motion follow `prefers-reduced-motion` and the in-app switch; it renders no markup of its own.
 *
 * @example
 * ```tsx
 * import { SheenMotionProvider } from "@sheenui/theme";
 *
 * export function Root() {
 *   return (
 *     <SheenMotionProvider>
 *       <main>
 *         <h1>Hello</h1>
 *       </main>
 *     </SheenMotionProvider>
 *   );
 * }
 * ```
 *
 * @see /foundations
 */
export function SheenMotionProvider({
  children,
  nonce,
  skipAnimations = false,
}: {
  children: ReactNode;
  /** CSP nonce for the inline styles Motion injects. */
  nonce?: string;
  /** Turn every Motion animation off (tests, screenshots); the final state is shown at once. */
  skipAnimations?: boolean;
}) {
  const reduced = useSheenReducedMotion();
  // Looping CSS animations pause while off-screen, app-wide (one shared IntersectionObserver).
  useOffscreenLoops();
  // A background tab stops every decorative loop: `data-page-hidden` on <html> pauses all CSS animations
  // (motion.css), so a loop added later is covered too. Per-component pausing off-screen stays as it is.
  useEffect(() => {
    const root = document.documentElement;
    const sync = () => root.toggleAttribute("data-page-hidden", document.visibilityState === "hidden");
    sync();
    document.addEventListener("visibilitychange", sync);
    return () => {
      document.removeEventListener("visibilitychange", sync);
      root.removeAttribute("data-page-hidden");
    };
  }, []);
  return (
    <MotionConfig
      reducedMotion={reduced ? "always" : "user"}
      transition={spring.smooth}
      skipAnimations={skipAnimations}
      nonce={nonce}
    >
      {children}
    </MotionConfig>
  );
}

/** Props of {@link SheenMotionProvider}. One MotionConfig for the whole app. */
export type SheenMotionProviderProps = ComponentProps<typeof SheenMotionProvider>;

"use client";

import { AnimatePresence, motion, type HTMLMotionProps, type Transition } from "motion/react";
import { useLayoutEffect, useRef, type ElementType, type ReactNode, type RefObject } from "react";

import { useSheenReducedMotion } from "../hooks/use-preferences";
import { duration, ease, spring } from "./tokens";

/** Motion's `layout` transition for reordering: `spring.smooth` (never overshoots), instant with reduced motion. */
const instant = { duration: 0 } satisfies Transition;

/** The tags an item can render as (a fixed map: Motion components are created once, never during render). */
const motionTags = {
  li: motion.li,
  div: motion.div,
  section: motion.section,
  article: motion.article,
  tr: motion.tr,
  a: motion.a,
  p: motion.p,
} as const;

/** Tags an {@link AnimatedListItem} can render as. */
export type AnimatedListItemTag = keyof typeof motionTags;

/**
 * Keeps keyboard focus on an element that React moved. Reordering keyed children moves their DOM
 * nodes, and a browser drops focus from a node that is re-inserted. Give it the list element: it
 * remembers the focused descendant and puts focus back after the render that moved it.
 *
 * Accessibility: Only restores focus that the move itself dropped (focus on `body`); it never steals focus from elsewhere.
 *
 * @example
 * ```tsx
 * import { useRef } from "react";
 * import { useKeepFocusOnReorder } from "@sheenui/theme";
 *
 * export function Rows({ ids }: { ids: string[] }) {
 *   const ref = useRef<HTMLUListElement>(null);
 *   useKeepFocusOnReorder(ref);
 *   return (
 *     <ul ref={ref}>
 *       {ids.map((id) => (
 *         <li key={id}>
 *           <button type="button">{id}</button>
 *         </li>
 *       ))}
 *     </ul>
 *   );
 * }
 * ```
 *
 * @param ref - Ref of the element whose children are reordered.
 * @see /foundations
 */
export function useKeepFocusOnReorder(ref: RefObject<HTMLElement | null>) {
  const last = useRef<HTMLElement | null>(null);
  useLayoutEffect(() => {
    const root = ref.current;
    if (!root) return;
    const remember = (event: FocusEvent) => {
      last.current = event.target instanceof HTMLElement ? event.target : null;
    };
    const forget = (event: FocusEvent) => {
      // Moving a node fires blur with no related target; a real move of focus sets one.
      if (event.relatedTarget) last.current = null;
    };
    root.addEventListener("focusin", remember);
    root.addEventListener("focusout", forget);
    return () => {
      root.removeEventListener("focusin", remember);
      root.removeEventListener("focusout", forget);
    };
  }, [ref]);
  // Every render: if the remembered node is still in the list but focus fell to the body, restore it.
  useLayoutEffect(() => {
    const node = last.current;
    const active = document.activeElement;
    if (node && node.isConnected && ref.current?.contains(node) && (!active || active === document.body)) {
      node.focus({ preventScroll: true });
    }
  });
}

/** Props of {@link AnimatedList}. */
export type AnimatedListProps = {
  /**
   * Sets the tag of the list element.
   * @default "ul"
   */
  as?: "ul" | "ol" | "div" | "section" | "tbody";
  /** Holds the items, which are {@link AnimatedListItem}s with stable `key`s. */
  children?: ReactNode;
  /** Class names for the list element. */
  className?: string;
  /**
   * Animate items leaving (shorter than an entrance, items below close the gap by sliding up).
   * @default true
   */
  animateExit?: boolean;
} & Omit<React.HTMLAttributes<HTMLElement>, "children" | "className">;

/**
 * A list whose items slide to their new position when they are reordered, inserted or removed, and
 * fade and scale in or out. Use it for to-do lists, ranked lists, sortable cards and any keyed list
 * that changes. It is built on Motion `layout` (a transform-only FLIP: the new layout is measured,
 * then each item is animated from where it was, so nothing outside the list shifts), springs from
 * the motion tokens, and keeps keyboard focus on an item that moved. Pair it with
 * {@link AnimatedListItem}; every item needs a stable `key`.
 *
 * Props: `as` (default `"ul"`), `animateExit` (default `true`), `className`, plus any native element prop.
 *
 * Keyboard: Nothing is added: items keep their own tab order, and a focused item stays focused while it slides to its new place.
 * Accessibility: Renders a plain `ul` (or your `as`) with real children, so list semantics and reading order follow the DOM, which already has the new order. Reordering is not announced by itself: announce it from your own live region when the user caused it.
 * Motion: Items move with `spring.smooth` on transform only; an entrance fades and scales in, an exit uses `duration.exit` with `ease.exit` (shorter than the entrance). With reduced motion items jump to their new place with no animation, and only a plain fade remains.
 *
 * @example
 * ```tsx
 * import { useState } from "react";
 * import { AnimatedList, AnimatedListItem } from "@sheenui/theme";
 *
 * export function Todos() {
 *   const [items, setItems] = useState(["Write", "Review", "Ship"]);
 *   return (
 *     <>
 *       <button type="button" onClick={() => setItems((list) => [...list].reverse())}>
 *         Reverse
 *       </button>
 *       <AnimatedList>
 *         {items.map((item) => (
 *           <AnimatedListItem key={item}>{item}</AnimatedListItem>
 *         ))}
 *       </AnimatedList>
 *     </>
 *   );
 * }
 * ```
 *
 * @see /foundations
 */
export function AnimatedList({ as = "ul", animateExit = true, children, ...rest }: AnimatedListProps) {
  const ref = useRef<HTMLElement>(null);
  useKeepFocusOnReorder(ref);
  const Tag = as as ElementType;
  return (
    <Tag ref={ref} data-slot="animated-list" {...rest}>
      {animateExit ? (
        <AnimatePresence initial={false} mode="popLayout">
          {children}
        </AnimatePresence>
      ) : (
        children
      )}
    </Tag>
  );
}

/** Props of {@link AnimatedListItem}. */
export type AnimatedListItemProps = {
  /**
   * Sets the tag of the item element.
   * @default "li"
   */
  as?: AnimatedListItemTag;
  /**
   * Animate the item's size too (`layout`), not just its position. Off by default: position-only
   * FLIP never stretches the content.
   * @default false
   */
  resize?: boolean;
} & Omit<HTMLMotionProps<"li">, "layout" | "transition">;

/**
 * One item of an {@link AnimatedList}. It animates to a new position with Motion `layout="position"`
 * (transform only), fades and scales in on insert and out on removal, and renders as any tag with
 * `as`. Give it a stable `key`; the key is what lets it be tracked across a reorder.
 *
 * Props: `as` (default `"li"`), `resize` (default `false`), plus any Motion / native element prop except `layout` and `transition`.
 *
 * Keyboard: Nothing is added; interactive content inside keeps its own keys and its focus survives the move.
 * Accessibility: A plain `li` by default (use `as="div"` outside a `ul`); it adds no roles or live regions. Animation never delays the content: the new DOM order is correct from the first frame.
 * Motion: Reflow uses `spring.smooth`, transform only; entrance is a short fade and scale, exit uses `duration.exit` and `ease.exit`. Reduced motion: no movement, no scaling, instant.
 *
 * @example
 * ```tsx
 * import { AnimatedList, AnimatedListItem } from "@sheenui/theme";
 *
 * export function Ranking({ names }: { names: string[] }) {
 *   return (
 *     <AnimatedList>
 *       {names.map((name) => (
 *         <AnimatedListItem key={name}>{name}</AnimatedListItem>
 *       ))}
 *     </AnimatedList>
 *   );
 * }
 * ```
 *
 * @see /foundations
 */
export function AnimatedListItem({ as = "li", resize = false, ...rest }: AnimatedListItemProps) {
  const reduced = useSheenReducedMotion();
  const Item = motionTags[as] as typeof motion.li;
  return (
    <Item
      data-slot="animated-list-item"
      layout={reduced ? false : resize ? true : "position"}
      initial={reduced ? false : { opacity: 0, scale: 0.98 }}
      animate={{
        opacity: 1,
        scale: 1,
        transition: reduced ? instant : { ...spring.smooth, opacity: { duration: duration.base } },
      }}
      exit={{
        opacity: 0,
        scale: reduced ? 1 : 0.98,
        transition: { duration: reduced ? 0 : duration.exit, ease: ease.exit },
      }}
      transition={reduced ? instant : spring.smooth}
      {...rest}
    />
  );
}

/**
 * The `layout` props for a row that should slide to its new place when its siblings reorder, for
 * markup that cannot use {@link AnimatedListItem} (table rows, grid cells). Spread them on a
 * `motion.tr`, `motion.div`, ...: `<motion.tr {...useRowReorder()} />`. It is position-only
 * (transform), with `spring.smooth`, and `{ layout: false }` under reduced motion.
 *
 * Accessibility: Adds no semantics, so `display` and table roles are untouched.
 * Motion: Transform only; reduced motion: no animation.
 *
 * @example
 * ```tsx
 * import { motion } from "motion/react";
 * import { useRowReorder } from "@sheenui/theme";
 *
 * export function Row({ label }: { label: string }) {
 *   const reorder = useRowReorder();
 *   return (
 *     <motion.div {...reorder}>
 *       {label}
 *     </motion.div>
 *   );
 * }
 * ```
 *
 * @returns Props to spread on a Motion element: `layout` and `transition`.
 * @see /foundations
 */
export function useRowReorder() {
  const reduced = useSheenReducedMotion();
  return reduced
    ? ({ layout: false } as const)
    : ({ layout: "position", transition: { layout: spring.smooth } } as const);
}

"use client";

import { ease } from "./tokens";

/**
 * Route (page) transitions. Two parts that work together:
 *
 *   1. `startRouteTransition()` wraps a navigation in `document.startViewTransition`. The browser
 *      cross-fades the page as ONE flat snapshot (the blur of every glass surface is already baked
 *      in, so glass never flickers) while the header and sidebar, identical in both snapshots, stay
 *      visually still. The page title additionally rises 8 px (CSS in `styles/motion.css`, keyed on
 *      `[data-route-transition]` on `#main`, else on `<html>`).
 *   2. `riseIn()` is the fallback for browsers without View Transitions: a transform-only 8 px rise
 *      of the new page, run with Motion. Transform only, because an opacity fade on a wrapper would
 *      turn every glass surface inside it into a flat panel for the length of the fade.
 *
 * Both are skipped under reduced motion (`data-motion="reduced"` on `<html>`, or the OS setting):
 * the page swaps instantly. Neither blocks navigation: the update always runs, and the browser is
 * only held on the old frame until the update has committed or `timeoutMs` has passed.
 */

/** True when `document.startViewTransition` exists (Chrome/Edge 111+, Safari 18+, Firefox 144+). */
export function supportsViewTransitions(): boolean {
  return typeof document !== "undefined" && typeof document.startViewTransition === "function";
}

/** True when motion is reduced, live: `data-motion="reduced"` on `<html>` or the OS setting. */
export function isMotionReduced(): boolean {
  if (typeof document === "undefined") return true;
  if (document.documentElement.getAttribute("data-motion") === "reduced") return true;
  return typeof window.matchMedia === "function" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

/** Options for {@link startRouteTransition}. */
export type RouteTransitionOptions = {
  /** Longest time (ms) the old frame is held while waiting for `update` to commit. Default 150: a cold route
   *  commits later, on its own, and the pending progress bar shows meanwhile, so input is never held up. */
  timeoutMs?: number;
  /** Transition types (`"push"`, `"back"`, `"forward"`...): `:active-view-transition-type(back)` styles can react. */
  types?: string[];
  /** Force the instant swap (e.g. your own reduced-motion flag). Default: read from the document. */
  reduced?: boolean;
};

const ATTRIBUTE = "data-route-transition";
let running: ViewTransition | undefined;

/**
 * Run a navigation as a view transition when the browser supports it and motion is allowed, else
 * run it at once. `update` must start your state change and return a promise that resolves once
 * the new page is in the DOM (for React: resolve it from a layout effect). A page whose code is
 * still loading therefore never shows a half page, and `timeoutMs` keeps a slow chunk from freezing
 * the frame for ever.
 *
 * Returns `true` when a view transition was started, `false` when `update` ran directly.
 *
 * Accessibility: Move focus and announce the page after the transition as you would without it; the snapshot is visual only. Reduced motion swaps the page instantly.
 * Motion: Root cross-fade 150 ms out and in (same curve, plus-lighter) plus an 8 px title rise (`styles/motion.css`).
 *
 * @example
 * ```tsx
 * import { startTransition } from "react";
 * import { startRouteTransition } from "@sheenui/theme";
 *
 * let resolveCommit: (() => void) | undefined;
 *
 * export function go(next: string, setPath: (path: string) => void) {
 *   startRouteTransition(
 *     () =>
 *       new Promise<void>((resolve) => {
 *         resolveCommit = resolve;
 *         startTransition(() => setPath(next));
 *       }),
 *   );
 * }
 * ```
 *
 * @see /foundations
 */
export function startRouteTransition(
  update: () => void | Promise<void>,
  options: RouteTransitionOptions = {},
): boolean {
  const { timeoutMs = 150, reduced = isMotionReduced(), types } = options;
  if (reduced || !supportsViewTransitions()) {
    void update();
    return false;
  }
  // The flag goes on the page's main region when there is one: an attribute flip on <html> restyles the whole document.
  const root = document.getElementById("main") ?? document.documentElement;
  // A newer navigation wins: a click during a running transition skips it (its end state is applied at once).
  running?.skipTransition();
  root.setAttribute(ATTRIBUTE, "");
  let transition: ViewTransition;
  const callback = async () => {
    let timer: ReturnType<typeof setTimeout> | undefined;
    const limit = new Promise<void>((resolve) => {
      timer = setTimeout(resolve, timeoutMs);
    });
    try {
      await Promise.race([Promise.resolve(update()), limit]);
    } finally {
      clearTimeout(timer);
    }
  };
  try {
    transition = types?.length
      ? (
          document.startViewTransition as unknown as (
            this: Document,
            o: { update: () => Promise<void>; types: string[] },
          ) => ViewTransition
        ).call(document, { update: callback, types })
      : document.startViewTransition(callback);
    running = transition;
  } catch {
    root.removeAttribute(ATTRIBUTE);
    void update();
    return false;
  }
  const clear = () => {
    if (running === transition) running = undefined;
    if (!running) root.removeAttribute(ATTRIBUTE);
  };
  // A skipped transition (a newer navigation, a hidden tab) rejects these promises: that is fine.
  transition.ready.catch(() => undefined);
  transition.updateCallbackDone.catch(() => undefined);
  void transition.finished.then(clear, clear);
  return true;
}

let rise: { cancel: () => void } | undefined;

/**
 * Fallback page transition for browsers without View Transitions: lift `element` 8 px into place
 * over 220 ms (transform only, so the glass inside it keeps its blur). A no-op under reduced motion
 * and where View Transitions exist. Starting a new rise cancels the previous one. It uses the Web Animations API
 * directly, so it costs no library code.
 *
 * Accessibility: Purely visual; the element keeps its DOM position, focus and reading order.
 * Motion: `transform: translateY(8px) → 0`, 220 ms, `ease.out`; never `opacity`.
 *
 * @example
 * ```tsx
 * import { useLayoutEffect } from "react";
 * import { riseIn } from "@sheenui/theme";
 *
 * export function Outlet({ path }: { path: string }) {
 *   useLayoutEffect(() => {
 *     riseIn(document.getElementById("main"));
 *   }, [path]);
 *   return <main id="main" />;
 * }
 * ```
 *
 * @see /foundations
 */
export function riseIn(element: HTMLElement | null, { distance = 8, duration = 0.22 } = {}): void {
  if (!element || supportsViewTransitions() || isMotionReduced()) return;
  rise?.cancel();
  if (typeof element.animate !== "function") return;
  const animation = element.animate(
    { transform: [`translateY(${distance}px)`, "translateY(0px)"] },
    { duration: duration * 1000, easing: `cubic-bezier(${ease.out.join(", ")})` },
  );
  rise = animation;
  animation.finished.then(
    () => element.style.removeProperty("transform"),
    () => undefined, // cancelled by a newer rise
  );
}

import { spring as springGenerator, type DynamicOption, type SpringOptions, type Transition } from "motion/react";
import { COARSE_POINTER_QUERY, PHONE_QUERY } from "../hooks/use-media-query";

/**
 * SheenUI motion tokens: the single source of truth for timing.
 * Mirrored in src/styles/motion.css as CSS variables; keep the two in sync.
 *
 * Durations are in seconds (Motion's unit).
 */

/** Seconds (Motion's unit). Mirrored in motion.css. */
export const duration = {
  instant: 0.1,
  fast: 0.15,
  base: 0.22,
  slow: 0.35,
  slower: 0.6,
  /** Leaving: shorter than every entrance. Pair with ease.exit. */
  exit: 0.15,
  /** Tooltips, menus and other small things closing. */
  exitFast: 0.1,
  /** One loop of the ambient backdrop drift. */
  ambient: 28,
} as const;

/**
 * Easing curves as cubic-bezier arrays: `out` for entrances, `inOut` for loops, `exit` for leaving
 *. Plain data: safe on the server.
 */
export const ease = {
  /** Entrances and state changes that are not springs. */
  out: [0.22, 1, 0.36, 1],
  /** Loops and ambient drift. */
  inOut: [0.65, 0, 0.35, 1],
  /** Exits only: accelerates away, stops dead on the target (no overshoot). */
  exit: [0.4, 0, 1, 1],
} as const;

/**
 * The four springs. Defined by visualDuration + bounce, so they line up with tweens:
 * the bulk of the motion is done by `visualDuration`, the settle happens after.
 * (The old `duration`-based springs looked done at about half their number)
 */
export const spring = {
  /** Controls: pills, toggles, indicators, press release. ~0.3% overshoot, 99% by ~205 ms. */
  snappy: { type: "spring", visualDuration: 0.22, bounce: 0.12 },
  /** Overlays, layout reflow, page content. Critically damped: never overshoots. 99% by ~380 ms. */
  smooth: { type: "spring", visualDuration: 0.3, bounce: 0 },
  /** Big surfaces and reveals: hero glass, cards, sections. ~1.1% overshoot, settles by ~630 ms. */
  gentle: { type: "spring", visualDuration: 0.55, bounce: 0.18 },
  /** Delight only: success, CTA pop, digit pop, badge count. ~8% overshoot, settles by ~485 ms. */
  bouncy: { type: "spring", visualDuration: 0.4, bounce: 0.38 },
} as const satisfies Record<string, Transition>;

/** Physics springs for MotionValues that chase a moving target (useSpring / useFollowValue). */
export const follow = {
  /** Pointer light, tilt: no overshoot, ~375 ms to catch up. */
  pointer: { stiffness: 320, damping: 32, mass: 0.6 },
  /** Magnetic pull: light and quick, ~0.5% overshoot. */
  magnetic: { stiffness: 220, damping: 18, mass: 0.5 },
  /** whileTap release: fast with a 1.5% rebound. */
  press: { stiffness: 700, damping: 30, mass: 0.5 },
  /** Scroll progress bars only (never parallax). */
  scroll: { stiffness: 140, damping: 30, mass: 0.5, restDelta: 0.001 },
  /** A heavy float for parallax compositions: thick glass moves slower than the pointer. */
  float: { stiffness: 90, damping: 20, mass: 1 },
} as const satisfies Record<string, SpringOptions>;

/**
 * A spring token for View Transition layers (AnimateView, animateView). Those are animated with
 * WAAPI directly and only accept the spring generator FUNCTION. `type: "spring"` (a string) is
 * silently replaced by a 300 ms ease-out in the browser, and throws where `process` exists.
 *   <AnimateView enter={{ opacity: [0, 1], transition: viewSpring(spring.smooth) }}>
 */
export const viewSpring = ({ visualDuration, bounce }: { visualDuration: number; bounce: number }) =>
  ({ type: springGenerator, visualDuration, bounce }) satisfies Transition;

/** Leaving the screen: duration.exit with ease.exit. */
export const exitTransition = { duration: duration.exit, ease: ease.exit } satisfies Transition;

/** Stagger steps in seconds, by what is being staggered. */
export const staggerStep = { chars: 0.025, words: 0.045, items: 0.05, cards: 0.07, sections: 0.1 } as const;

/** No stagger may spread a group over more than this (seconds). */
export const STAGGER_BUDGET = 0.4;

/**
 * A stagger that never spreads a group over more than STAGGER_BUDGET, however many children:
 *   transition: { delayChildren: budgetStagger(staggerStep.cards) }   (variants)
 *   animate("li", { opacity: 1 }, { delay: budgetStagger(staggerStep.items) })
 */
export const budgetStagger =
  (step: number): DynamicOption<number> =>
  (i, total) =>
    i * Math.min(step, STAGGER_BUDGET / Math.max(total - 1, 1));

/** Movement distances in pixels: `nudge`, `rise`, `reveal`, `panel`, `hero`, and the `magneticMax` / `parallaxMax` caps. */
export const distance = {
  nudge: 2,
  rise: 8,
  reveal: 16,
  panel: 24,
  hero: 48,
  magneticMax: 8,
  parallaxMax: 96,
} as const;

/** Scale targets (1 = unchanged) for press, pop-in, overlay entrance and hover. */
export const scaleTo = { press: 0.97, pressSmall: 0.92, popFrom: 0.94, overlayFrom: 0.96, hover: 1.02 } as const;

/** Phone-sized or touch-only screens (read when an animation starts, never during render). */
const isPhone = () =>
  typeof window !== "undefined" &&
  typeof window.matchMedia === "function" &&
  window.matchMedia(`${PHONE_QUERY}, ${COARSE_POINTER_QUERY}`).matches;

/**
 * Degrees / pixels for the rest.
 *
 * `heroTilt` and `handoffTilt` are the 3D lean of a glass slab's entrance. Phones skip it (0): a
 * perspective transform on a blurred surface re-rasterises its whole backdrop on every frame, and
 * on a small GPU that is the dropped frame. They are getters, so they read the screen when the
 * entrance starts (call sites read them inside effects / animation callbacks, not at module load).
 */
export const misc = {
  tiltMax: 6,
  get heroTilt() {
    return isPhone() ? 0 : 10;
  },
  get handoffTilt() {
    return isPhone() ? 0 : 8;
  },
  textBlur: 8,
} as const;

@layer sheen {
  /*
 * <SheenBackdrop>, preview stages and display type, per style preset.
 *
 *   .sheen-sky                 the page backdrop (fixed, behind everything, aria-hidden)
 *     .sheen-sky__base         static first paint: page gradient + soft light (pure CSS)
 *     .sheen-sky__liquid       Liquid Glass: drifting orbs + silk ribbons + daylight caustics (lazy)
 *     .sheen-sky__aurora       Aurora Neon: an OPAQUE low-res canvas sky (lazy, paints its own base)
 *     .sheen-sky__grain        a pre-baked bitmap grain tile (never SVG noise: it is re-rasterised per tile)
 *   .sheen-stage-backdrop      vivid colour behind docs previews, so glass always reads as glass
 *   .sheen-display / .sheen-accent-text   the style's display face and its accent word
 *
 * Glass rule: nothing here wraps glass. The sky is a fixed sibling behind the page (z-index -1)
 * and never fades, filters or blends an ancestor of glass. Ambient motion is transform only,
 * driven by the shared ~30 Hz beat (motion/beat.ts) and paused off screen / in hidden tabs.
 */

  .sheen-sky {
    position: fixed;
    inset: 0;
    z-index: -1;
    overflow: hidden;
    pointer-events: none;
    contain: strict;
    background-color: var(--sheen-bg);
  }

  .sheen-sky > * {
    position: absolute;
    inset: 0;
  }

  /* The backdrop is live: the body's CSS blobs (backgrounds.css) would only be painted under it. */
  :root[data-sheen-backdrop] .sheen-backdrop::before,
  :root[data-sheen-backdrop] .sheen-backdrop::after {
    display: none;
  }

  /* Hero sky below the fold. The vivid hero sky (full ribbons, hot orbs) is made for the first viewport;
   once it has scrolled away (SheenBackdrop sets [data-away]) a veil of the page tint calms it, so the
   long-form text further down keeps AA over the brightest ribbon and orb (measured: accent links fell to
   1.2:1 and body copy to 1.6:1 over the pink ribbon at night). Opacity only, so it costs no extra pass. */
  .sheen-sky[data-mode="hero"]::after {
    content: "";
    position: absolute;
    inset: 0;
    background: var(--sheen-bg);
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--sheen-duration-slower) var(--sheen-ease-out);
