   gradient and five soft orbs. "page" is calm and lit in the middle too, so the gaps between
   panels never fall to a black (or flat cream) void. */
  .sheen-sky[data-style="liquid"] .sheen-sky__base {
    background:
      radial-gradient(circle 34vmax at 0% 30%, var(--sheen-sky-orb-1), transparent),
      radial-gradient(circle 30vmax at 100% 72%, var(--sheen-sky-orb-2), transparent),
      radial-gradient(circle 24vmax at 18% 104%, var(--sheen-sky-orb-5), transparent),
      radial-gradient(circle 28vmax at 82% 12%, var(--sheen-sky-orb-6), transparent),
      radial-gradient(circle 32vmax at 48% 54%, var(--sheen-sky-orb-mid), transparent),
      linear-gradient(170deg, var(--sheen-bg) 10%, var(--sheen-bg-2));
  }

  .sheen-sky[data-style="liquid"] {
    --sheen-sky-orb-1: color-mix(in oklab, var(--sheen-spectrum-1) 62%, transparent);
    --sheen-sky-orb-2: color-mix(in oklab, var(--sheen-spectrum-2) 52%, transparent);
    --sheen-sky-orb-5: color-mix(in oklab, var(--sheen-spectrum-5) 60%, transparent);
    --sheen-sky-orb-6: color-mix(in oklab, var(--sheen-spectrum-6) 46%, transparent);
    --sheen-sky-orb-mid: color-mix(in oklab, var(--sheen-spectrum-1) 26%, transparent);
    --sheen-grain-o: 1;
  }

  /* Night: overlapping light adds up (glows) instead of muddying. */
  @media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) .sheen-sky[data-style="liquid"] .sheen-sky__base {
      background-blend-mode: screen, screen, screen, screen, screen, normal;
    }
  }

  :root[data-theme="dark"] .sheen-sky[data-style="liquid"] .sheen-sky__base {
    background-blend-mode: screen, screen, screen, screen, screen, normal;
  }

  /* Hero <-> page: the outgoing Liquid look rides above the incoming one and fades out (opacity only, no box ever
   moves, so no layout shift); the route transition's own cross-fade runs over the same ~300 ms. */
  .sheen-sky--ghost {
