    translate: -50% -50%;
    background: radial-gradient(closest-side, var(--c), transparent);
  }

  @media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) .sheen-sky__orb {
      mix-blend-mode: screen;
    }
  }

  :root[data-theme="dark"] .sheen-sky__orb {
    mix-blend-mode: screen;
  }

  /* Hero mode: the brightest colour sits behind the hero composition (right); the copy side stays calm. */
  .sheen-sky__orb[data-o="a"] {
    --c: var(--sheen-spectrum-2);
    width: 68vmax;
    inset-inline-start: 74%;
    top: 46%;
  }
  .sheen-sky__orb[data-o="b"] {
    --c: var(--sheen-spectrum-6);
    width: 62vmax;
    inset-inline-start: 98%;
    top: 4%;
  }
  .sheen-sky__orb[data-o="c"] {
    --c: var(--sheen-spectrum-warm);
    width: 44vmax;
    inset-inline-start: 84%;
    top: 100%;
  }
  .sheen-sky__orb[data-o="d"] {
    --c: var(--sheen-spectrum-5);
    width: 46vmax;
    inset-inline-start: 4%;
    top: 96%;
  }
  .sheen-sky__orb[data-o="e"] {
    --c: var(--sheen-spectrum-1);
    width: 54vmax;
    inset-inline-start: 22%;
    top: 2%;
  }

