    opacity: 0.7;
  }
  .sheen-sky[data-mode="page"] .sheen-sky__orb[data-o="a"] {
    --c: var(--sheen-spectrum-1);
    width: 64vmax;
    inset-inline-start: -2%;
    top: 30%;
  }
  .sheen-sky[data-mode="page"] .sheen-sky__orb[data-o="b"] {
    --c: var(--sheen-spectrum-2);
    width: 58vmax;
    inset-inline-start: 102%;
    top: 74%;
  }
  .sheen-sky[data-mode="page"] .sheen-sky__orb[data-o="c"] {
    --c: var(--sheen-spectrum-5);
    width: 46vmax;
    inset-inline-start: 18%;
    top: 108%;
  }
  .sheen-sky[data-mode="page"] .sheen-sky__orb[data-o="d"] {
    --c: var(--sheen-spectrum-6);
    width: 56vmax;
    inset-inline-start: 86%;
    top: 10%;
    opacity: 0.5;
  }
  .sheen-sky[data-mode="page"] .sheen-sky__orb[data-o="e"] {
    --c: var(--sheen-spectrum-1);
    width: 60vmax;
    inset-inline-start: 50%;
    top: 58%;
    opacity: 0.32;
  }

  /* The rose orb sits behind the page footer and the lower-right text: a touch quieter (muted footer
   links over it measured 4.3:1 at night). */
  .sheen-sky[data-mode="page"] .sheen-sky__orb[data-o="b"] {
    opacity: 0.58;
  }

  /* Night: the silk ribbons are the brightest thing a line of bare text can sit on (accent links measured
   3.7:1 across them, body copy 3:1). In page mode they step back further than by day; the glass panels and
   the orbs keep their light. */
  :root[data-theme="dark"] .sheen-sky[data-mode="page"] .sheen-sky__ribbons {
    opacity: 0.2;
  }

  @media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) .sheen-sky[data-mode="page"] .sheen-sky__ribbons {
      opacity: 0.2;
    }
  }

  /* Phones: the docs text column spans the whole screen, so every line of bare text (ledes,
   captions, hints) sits over some orb. Dimmed, muted text keeps AA over the brightest pixel
   (measured: it fell to 4.0:1 at night over the violet orb and 4.3:1 by day over the pink one). */
  @media (max-width: 639px) {
    .sheen-sky[data-mode="page"] .sheen-sky__orb {
      opacity: 0.45;
    }
    .sheen-sky[data-mode="page"] .sheen-sky__orb[data-o="b"] {
      opacity: 0.45;
    }
    .sheen-sky[data-mode="page"] .sheen-sky__orb[data-o="d"] {
      opacity: 0.38;
    }
    .sheen-sky[data-mode="page"] .sheen-sky__orb[data-o="e"] {
      opacity: 0.2;
    }
    .sheen-sky[data-mode="page"] .sheen-sky__ribbons {
      opacity: 0.3;
    }
  }

  /* Light blooms: soft, out-of-focus pools of coloured light that belong to the sky (hero mode only, behind
   the composition on the right; page mode has none). No disc edge: a long radial falloff to transparent,
   so nothing reads as a stamped object and a glass piece in front of one just picks up its colour. */
  .sheen-sky__sphere {
    display: none;
    position: absolute;
    aspect-ratio: 1;
    border-radius: 50%;
    translate: -50% -50%;
    pointer-events: none;
    background: radial-gradient(
      closest-side,
      var(--s-glow),
      color-mix(in oklab, var(--s-glow) 42%, transparent) 38%,
      transparent 100%
    );
  }

  .sheen-sky[data-mode="hero"] .sheen-sky__sphere {
    display: block;
  }

  .sheen-sky__sphere[data-sphere="magenta"] {
    --s-glow: light-dark(oklch(74% 0.2 350 / 0.5), oklch(62% 0.26 345 / 0.42));
    width: clamp(16rem, 44vmin, 30rem);
    inset-inline-start: 74%;
    top: 40%;
  }

  .sheen-sky__sphere[data-sphere="blue"] {
    --s-glow: light-dark(oklch(74% 0.16 250 / 0.5), oklch(58% 0.22 262 / 0.4));
    width: clamp(10rem, 28vmin, 20rem);
    inset-inline-start: 62%;
    top: 92%;
  }

  /* Phones: the composition sits below the copy, so the spheres sink under it (never behind text). */
  @media (max-width: 63.9rem) {
    .sheen-sky__sphere[data-sphere="magenta"] {
      inset-inline-start: 70%;
      top: 80%;
    }
    .sheen-sky__sphere[data-sphere="blue"] {
      inset-inline-start: 12%;
      top: 92%;
    }
  }

