  .sheen-sky[data-style="aurora"] .sheen-sky__base {
    background:
      radial-gradient(
        70% 55% at 78% 8%,
        light-dark(oklch(78% 0.15 210 / 0.7), oklch(45% 0.14 215 / 0.35)),
        transparent 70%
      ),
      radial-gradient(
        60% 50% at 22% 0%,
        light-dark(oklch(74% 0.18 300 / 0.7), oklch(40% 0.2 295 / 0.5)),
        transparent 70%
      ),
      radial-gradient(
        55% 45% at 55% 38%,
        light-dark(oklch(80% 0.16 350 / 0.6), oklch(36% 0.18 340 / 0.35)),
        transparent 72%
