  .sheen-sky[data-style="aurora"] {
    --sheen-grain-o: 0.55;
  }

  @media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) .sheen-sky[data-style="aurora"] {
      --sheen-grain-o: 1;
    }
  }

  :root[data-theme="dark"] .sheen-sky[data-style="aurora"] {
    --sheen-grain-o: 1;
