    );
    opacity: 0.6;
    mask: linear-gradient(to bottom, transparent, #000 38%, #000 62%, transparent);
    -webkit-mask: linear-gradient(to bottom, transparent, #000 38%, #000 62%, transparent);
  }

  /* Aurora: lit light behind the glass, no outlines: two soft filled aurora lobes, a slanted lit
   band and a cool core. Colours stay inside the stage's luminance band (text on a bare stage keeps AA). */
  :root[data-sheen-style="aurora"] .sheen-stage-backdrop {
    background:
      radial-gradient(
        52% 84% at var(--v-bx) var(--v-by),
        light-dark(oklch(85% 0.12 300 / 0.9), oklch(48% 0.25 295 / 0.9)),
        transparent 76%
      ),
      radial-gradient(
        46% 74% at 72% 66%,
        light-dark(oklch(86% 0.12 345 / 0.85), oklch(46% 0.23 340 / 0.86)),
        transparent 74%
      ),
      radial-gradient(
        40% 62% at 56% 18%,
        light-dark(oklch(87% 0.1 205 / 0.9), oklch(49% 0.15 212 / 0.82)),
        transparent 74%
      ),
      radial-gradient(60% 40% at 50% 112%, var(--sheen-blob-5), transparent 70%), var(--sheen-stage-base);
    /* Light theme: a "dawn" base instead of the page white, so the glass has colour to blur everywhere on the stage:
     peach, rose, lilac and cyan at the top of the luminance band (L 87-89%, C <= 0.11: fg-subtle keeps 4.5:1 on any
     pixel), with a darker horizon line two thirds down. */
    --sheen-stage-base:
      linear-gradient(to bottom, transparent 62%, oklch(84% 0.08 300 / 0.55) 66%, transparent 71%),
      linear-gradient(100deg, oklch(89% 0.09 70), oklch(88% 0.1 340) 36%, oklch(87% 0.1 295) 62%, oklch(88% 0.1 210));
  }
  :root[data-sheen-style="aurora"][data-theme="dark"] .sheen-stage-backdrop {
    --sheen-stage-base: linear-gradient(100deg, oklch(25% 0.07 290), oklch(23% 0.08 330) 45%, oklch(24% 0.06 220));
  }
  @media (prefers-color-scheme: dark) {
    :root[data-sheen-style="aurora"]:not([data-theme="light"]) .sheen-stage-backdrop {
      --sheen-stage-base: linear-gradient(100deg, oklch(25% 0.07 290), oklch(23% 0.08 330) 45%, oklch(24% 0.06 220));
    }
  }

  /* A lit band: a soft slanted aurora curtain. */
  :root[data-sheen-style="aurora"] .sheen-stage-backdrop > [data-s="1"] {
    inset-inline-start: -10%;
    inset-inline-end: -10%;
    --ty: var(--v-r-top);
    height: 32%;
    border-radius: 50%;
    rotate: var(--v-r-rot);
    background: linear-gradient(
      90deg,
      transparent,
      light-dark(oklch(86% 0.11 205 / 0.8), oklch(49% 0.17 200 / 0.9)) 25%,
      light-dark(oklch(86% 0.12 320 / 0.8), oklch(47% 0.24 320 / 0.9)) 65%,
      transparent
    );
    mask: linear-gradient(to bottom, transparent, #000 40%, #000 60%, transparent);
    -webkit-mask: linear-gradient(to bottom, transparent, #000 40%, #000 60%, transparent);
  }

  /* A filled soft lobe (no ring): a warm-magenta light whose edge dissolves. */
  :root[data-sheen-style="aurora"] .sheen-stage-backdrop > [data-s="2"] {
    inset-inline-start: var(--v-b-start);
    --ty: var(--v-a-top);
    width: clamp(7rem, 30%, 16rem);
    aspect-ratio: 1;
    background: radial-gradient(
      closest-side,
      light-dark(oklch(86% 0.12 345 / 0.9), oklch(49% 0.25 335 / 0.95)),
      transparent 100%
    );
  }

  :root[data-sheen-style="aurora"] .sheen-stage-backdrop > [data-s="3"] {
    inset-inline-start: var(--v-a-end);
    --ty: calc(100cqh - var(--v-b-bottom) - 100%);
    width: 40%;
    aspect-ratio: 1;
    background: radial-gradient(
      closest-side,
      light-dark(oklch(88% 0.1 200 / 0.9), oklch(50% 0.15 205 / 0.85)),
      transparent 100%
    );
  }

  /* ----------------------------------------------------------------------
 * Stage art per component family (the docs template sets `data-stage-family` from the page's sidebar group).
 * The same three layers are re-drawn so a stage says what it holds: a bar silhouette and a grid behind charts,
 * field rows behind forms, stacked panes behind overlays, a pill row behind navigation and layout, two bubbles
 * behind chat, a brighter sphere and a thin streak (a lens flare) behind effects, an app window behind blocks and
 * dashboards. Every colour sits inside the luminance band above (light L >= 86% at C <= 0.12, dark L <= 46%), the
 * shapes keep their drift and parallax, and components and data display keep the default composition.
 * -------------------------------------------------------------------- */
  .sheen-stage-backdrop {
    --sheen-stage-ink-a: light-dark(oklch(86% 0.1 295 / 0.9), oklch(44% 0.2 292 / 0.85));
    --sheen-stage-ink-b: light-dark(oklch(87% 0.1 212 / 0.9), oklch(42% 0.14 215 / 0.85));
    --sheen-stage-ink-c: light-dark(oklch(86% 0.11 350 / 0.9), oklch(44% 0.2 348 / 0.85));
    --sheen-stage-line: light-dark(oklch(80% 0.08 290 / 0.35), oklch(60% 0.1 290 / 0.28));
    /* Keep-out: family art lives in a stage's side gutters (3 % in, a quarter wide at most), never in the middle where the
     previewed control sits. The side alternates per stage (data-v), so neighbours still differ; --h-* is the other side. */
    --g-s: 3%;
    --g-e: auto;
    --h-s: auto;
    --h-e: 3%;
    /* Liquid's lights per family: the hue of the two orbs and of the lit pool behind the middle (night). */
    --oh1: 350;
    --oh2: 225;
    --stage-glow-h: 285;
  }
  .sheen-stage-backdrop:is([data-v="1"], [data-v="3"]) {
    --g-s: auto;
    --g-e: 3%;
    --h-s: 3%;
    --h-e: auto;
  }

  /* Every family rule starts with `:root` so it weighs (0,4,0), the same as the per-style rules above, and wins by
   coming later; each one states its whole geometry (insets, size, rotation, mask), so the shape is the same in both
   styles. The per-stage composition variables (data-v) still place it. */

  /* Charts: a grid tile where the sphere was, a bar silhouette where the band was. */
  :root [data-stage-family="charts"] .sheen-stage-backdrop > [data-s="1"] {
    inset-inline: var(--g-s) var(--g-e);
    --ty: clamp(6cqh, var(--v-a-top), 22cqh);
    width: clamp(7rem, 22%, 14rem);
    height: auto;
    aspect-ratio: 1.45;
    border-radius: 1rem;
    filter: blur(0.25rem);
    rotate: 0deg;
    box-shadow: none;
    background:
      linear-gradient(var(--sheen-stage-line) 1px, transparent 1px) 0 0 / 1.6rem 1.6rem,
      linear-gradient(90deg, var(--sheen-stage-line) 1px, transparent 1px) 0 0 / 1.6rem 1.6rem,
      var(--sheen-stage-ink-b);
    mask: linear-gradient(135deg, #000 40%, transparent);
    -webkit-mask: linear-gradient(135deg, #000 40%, transparent);
  }
  :root [data-stage-family="charts"] .sheen-stage-backdrop > [data-s="3"] {
    inset-inline: var(--h-s) var(--h-e);
    --ty: calc(100cqh + 6cqh - 100%);
    width: 24%;
    height: 46%;
    filter: blur(0.25rem);
    aspect-ratio: auto;
    border-radius: 0.6rem 0.6rem 0 0;
    rotate: 0deg;
    opacity: 1;
    background:
      repeating-linear-gradient(90deg, var(--sheen-stage-ink-a) 0 9%, transparent 9% 14%),
      linear-gradient(to top, var(--sheen-stage-ink-c), transparent);
    mask: linear-gradient(to top, #000 30%, transparent 95%);
    -webkit-mask: linear-gradient(to top, #000 30%, transparent 95%);
  }

  /* Forms: three field rows with a label stub each. */
  :root [data-stage-family="forms"] .sheen-stage-backdrop > [data-s="1"] {
    inset-inline: var(--g-s) var(--g-e);
    --ty: clamp(8cqh, var(--v-a-top), 24cqh);
    width: clamp(7rem, 22%, 14rem);
    height: 48%;
    filter: blur(0.25rem);
    aspect-ratio: auto;
    border-radius: 0.9rem;
    rotate: 0deg;
    box-shadow: none;
    background:
      repeating-linear-gradient(to bottom, var(--sheen-stage-ink-a) 0 1.4rem, transparent 1.4rem 2.6rem),
      repeating-linear-gradient(
          to bottom,
          transparent 0 1.6rem,
          var(--sheen-stage-line) 1.6rem 2rem,
          transparent 2rem 2.6rem
        )
        0 0 / 40% 100% no-repeat;
    mask: linear-gradient(to right, #000 55%, transparent);
    -webkit-mask: linear-gradient(to right, #000 55%, transparent);
  }

  /* Overlays: a pane and two more stacked behind it (sized to the stage's height, so the stack never leaves it). */
  :root [data-stage-family="overlays"] .sheen-stage-backdrop > [data-s="2"] {
    inset-inline: var(--g-s) var(--g-e);
    --ty: clamp(6cqh, var(--v-a-top), 18cqh);
    width: clamp(5rem, 15%, 9rem);
    filter: blur(0.25rem);
    /* The two offset panes of the stack reach 2.4 rem past the box: keep them inside the stage on the end side. */
    margin-inline-end: 2.6rem;
    height: auto;
    aspect-ratio: 1.3;
    border-radius: 0.8rem;
    background: var(--sheen-stage-ink-a);
    box-shadow:
      1.2rem 1.2rem 0 -0.15rem var(--sheen-stage-ink-c),
      2.4rem 2.4rem 0 -0.3rem var(--sheen-stage-ink-b);
  }

  /* Navigation and layout: a row of pills, one lit. */
  :root [data-stage-family="navigation"] .sheen-stage-backdrop > [data-s="1"],
  :root [data-stage-family="layout"] .sheen-stage-backdrop > [data-s="1"] {
    inset-inline: var(--g-s) var(--g-e);
    --ty: clamp(10cqh, var(--v-a-top), 24cqh);
    width: clamp(8rem, 24%, 16rem);
    height: 2.4rem;
    filter: blur(0.2rem);
    aspect-ratio: auto;
    border-radius: 999px;
    rotate: 0deg;
    box-shadow: none;
    mask: none;
    -webkit-mask: none;
    background:
      linear-gradient(var(--sheen-stage-ink-c), var(--sheen-stage-ink-c)) 0 0 / 26% 100% no-repeat,
      repeating-linear-gradient(90deg, var(--sheen-stage-ink-a) 0 22%, transparent 22% 26%);
  }

  /* Chat: two bubbles, one from each side. */
  :root [data-stage-family="chat"] .sheen-stage-backdrop > [data-s="1"] {
    inset-inline: auto 3%;
    --ty: clamp(8cqh, var(--v-a-top), 20cqh);
    width: clamp(6rem, 20%, 12rem);
    height: 24%;
    filter: blur(0.25rem);
    aspect-ratio: auto;
    border-radius: 1.4rem 1.4rem 0.35rem 1.4rem;
    rotate: 0deg;
    box-shadow: none;
    mask: none;
    -webkit-mask: none;
    background: var(--sheen-stage-ink-a);
  }
  :root [data-stage-family="chat"] .sheen-stage-backdrop > [data-s="2"] {
    inset-inline: 3% auto;
    --ty: calc(100cqh - clamp(8cqh, var(--v-b-bottom), 20cqh) - 100%);
    width: clamp(5rem, 18%, 10rem);
    height: 18%;
    filter: blur(0.25rem);
    aspect-ratio: auto;
    border-radius: 1.4rem 1.4rem 1.4rem 0.35rem;
    background: var(--sheen-stage-ink-b);
  }

  /* Effects: a lens flare, a hotter sphere and a thin bright streak. */
  :root [data-stage-family="effects"] .sheen-stage-backdrop > [data-s="1"] {
    inset-inline: var(--g-s) var(--g-e);
    --ty: clamp(6cqh, var(--v-a-top), 24cqh);
    width: clamp(5rem, 14%, 8rem);
    filter: blur(0.2rem);
    height: auto;
    aspect-ratio: 1;
    border-radius: 50%;
    rotate: 0deg;
    mask: none;
    -webkit-mask: none;
    /* Night cores stay at L 42 % (Y about 0.075): a light chip on a glass card over the flare keeps 4.5:1. */
    background: radial-gradient(
      circle at 34% 28%,
      light-dark(oklch(99% 0.02 90), oklch(42% 0.14 60)) 0 6%,
      light-dark(oklch(90% 0.1 40), oklch(42% 0.19 340)) 30%,
      light-dark(oklch(86% 0.12 330), oklch(36% 0.2 300)) 62%,
      light-dark(oklch(86% 0.1 290), oklch(26% 0.14 290)) 100%
    );
  }
  :root [data-stage-family="effects"] .sheen-stage-backdrop > [data-s="3"] {
    inset-inline: -10% -10%;
    --ty: var(--v-r-top);
    width: auto;
    height: 0.9rem;
    aspect-ratio: auto;
    filter: blur(0.15rem);
    border-radius: 999px;
    rotate: -28deg;
    opacity: 0.9;
    background: linear-gradient(
      90deg,
      transparent,
      var(--sheen-stage-ink-c) 30%,
      light-dark(oklch(98% 0.02 90), oklch(42% 0.1 90)) 50%,
      var(--sheen-stage-ink-b) 70%,
      transparent
    );
  }

  /* Blocks and dashboards: an app window with a title bar and two cards. */
  :root [data-stage-family="blocks"] .sheen-stage-backdrop > [data-s="2"],
  :root [data-stage-family="dashboards"] .sheen-stage-backdrop > [data-s="2"] {
    inset-inline: var(--g-s) var(--g-e);
    --ty: clamp(6cqh, var(--v-a-top), 22cqh);
    width: clamp(8rem, 24%, 16rem);
    filter: blur(0.25rem);
    height: auto;
    aspect-ratio: 1.5;
    border-radius: 0.9rem;
    background:
      linear-gradient(var(--sheen-stage-ink-c), var(--sheen-stage-ink-c)) 0 0 / 100% 16% no-repeat,
      linear-gradient(var(--sheen-stage-ink-a), var(--sheen-stage-ink-a)) 8% 28% / 40% 60% no-repeat,
      linear-gradient(var(--sheen-stage-ink-b), var(--sheen-stage-ink-b)) 92% 28% / 40% 30% no-repeat,
      light-dark(oklch(92% 0.04 290 / 0.8), oklch(22% 0.06 290 / 0.8));
  }

  /* Liquid, per family: the same two orbs and silk band, but each family lights its stage in its own colours and with its
   own count and placement, so button, dialog and date picker are three different pictures (night adds the lit pool,
   see the base above). Components: violet and teal orbs, the band stays. Forms: a violet pool with an amber orb behind
   the field rows, a column of toggles opposite instead of the band. Overlays: one large teal orb opposite the pane stack,
   no band. All inside the gutters and the luminance band. */
  :root [data-stage-family="components"] .sheen-stage-backdrop {
    --oh1: 300;
    --oh2: 182;
    --stage-glow-h: 262;
  }
  :root [data-stage-family="forms"] .sheen-stage-backdrop {
    --oh2: 70;
    --stage-glow-h: 312;
  }
  :root [data-stage-family="overlays"] .sheen-stage-backdrop {
    --oh1: 196;
    --stage-glow-h: 205;
  }
  :root:not([data-sheen-style="aurora"]) [data-stage-family="forms"] .sheen-stage-backdrop > [data-s="3"] {
    inset-inline: var(--h-s) var(--h-e);
    --ty: calc(100cqh - 12cqh - 100%);
    width: clamp(5rem, 16%, 10rem);
    height: 36%;
    aspect-ratio: auto;
    border-radius: 0.9rem;
    rotate: 0deg;
    opacity: 1;
    filter: blur(0.25rem);
    background:
      repeating-linear-gradient(to bottom, var(--sheen-stage-ink-b) 0 1.1rem, transparent 1.1rem 2.1rem) 100% 0 / 46%
        100% no-repeat,
      repeating-linear-gradient(to bottom, var(--sheen-stage-ink-c) 0 0.9rem, transparent 0.9rem 2.1rem) 0 0 / 40% 100%
        no-repeat;
    mask: linear-gradient(to left, #000 50%, transparent);
    -webkit-mask: linear-gradient(to left, #000 50%, transparent);
  }
  :root:not([data-sheen-style="aurora"]) [data-stage-family="overlays"] .sheen-stage-backdrop > [data-s="1"] {
    inset-inline: var(--h-s) var(--h-e);
    --ty: clamp(6cqh, var(--v-a-top), 14cqh);
    width: clamp(5rem, min(24%, 76cqh), 15rem);
  }
  :root:not([data-sheen-style="aurora"]) [data-stage-family="overlays"] .sheen-stage-backdrop > [data-s="3"] {
    display: none;
  }

  /* Overlays, Aurora: the same picture as Liquid's (one large soft teal orb opposite the pane stack, no third light), so
   dialog, alert dialog, popover, menus and drawers read as "a sheet over a lit scene" in both styles. */
  :root[data-sheen-style="aurora"] [data-stage-family="overlays"] .sheen-stage-backdrop > [data-s="1"] {
    inset-inline: var(--h-s) var(--h-e);
    --ty: clamp(6cqh, var(--v-a-top), 14cqh);
    width: clamp(5rem, min(24%, 76cqh), 15rem);
    height: auto;
    aspect-ratio: 1;
    border-radius: 50%;
    rotate: 0deg;
    mask: none;
    -webkit-mask: none;
    background: radial-gradient(
      closest-side,
      light-dark(oklch(88% 0.1 195 / 0.95), oklch(50% 0.13 195 / 0.92)),
      transparent 100%
    );
  }
  :root[data-sheen-style="aurora"] [data-stage-family="overlays"] .sheen-stage-backdrop > [data-s="3"] {
    display: none;
  }

  /* Controls (button, button group, switch, slider): a different picture from the overlays. A lit diagonal bar low in the
   stage, crossing under the row of controls, and two small orbs in opposite gutters, in both styles. */
  :root [data-stage-family="controls"] .sheen-stage-backdrop {
    --oh1: 330;
    --oh2: 215;
    --stage-glow-h: 252;
  }
  :root [data-stage-family="controls"] .sheen-stage-backdrop > [data-s="1"] {
    inset-inline: var(--g-s) var(--g-e);
    --ty: clamp(8cqh, var(--v-a-top), 22cqh);
    width: clamp(3.5rem, 9%, 6rem);
    height: auto;
    aspect-ratio: 1;
    border-radius: 50%;
    rotate: 0deg;
    box-shadow: none;
    mask: none;
    -webkit-mask: none;
    background: radial-gradient(
      circle at 38% 32%,
      light-dark(oklch(97% 0.04 var(--oh1) / 0.95), oklch(52% 0.2 var(--oh1) / 0.95)) 0 6%,
      light-dark(oklch(88% 0.1 var(--oh1) / 0.9), oklch(44% 0.2 var(--oh1) / 0.85)) 40%,
      transparent 72%
    );
  }
  :root [data-stage-family="controls"] .sheen-stage-backdrop > [data-s="2"] {
    inset-inline: var(--h-s) var(--h-e);
    --ty: calc(100cqh - clamp(8cqh, var(--v-b-bottom), 22cqh) - 100%);
    width: clamp(2.75rem, 7%, 4.5rem);
    height: auto;
    aspect-ratio: 1;
    border-radius: 50%;
    box-shadow: none;
    background: radial-gradient(
      circle at 38% 32%,
      light-dark(oklch(97% 0.03 var(--oh2) / 0.95), oklch(52% 0.15 var(--oh2) / 0.95)) 0 6%,
      light-dark(oklch(89% 0.09 var(--oh2) / 0.9), oklch(42% 0.15 var(--oh2) / 0.85)) 42%,
      transparent 72%
    );
  }
  :root [data-stage-family="controls"] .sheen-stage-backdrop > [data-s="3"] {
    inset-inline: 14% 14%;
    --ty: calc(100cqh - 34cqh - 100%);
    width: auto;
    height: 2.6rem;
    aspect-ratio: auto;
    border-radius: 999px;
    rotate: -13deg;
    opacity: 0.8;
    background: linear-gradient(
      90deg,
      transparent,
      light-dark(oklch(90% 0.09 85), oklch(45% 0.12 300)) 22%,
      light-dark(oklch(89% 0.1 340), oklch(46% 0.2 340)) 60%,
      transparent
    );
    mask: linear-gradient(to bottom, transparent, #000 40%, #000 60%, transparent);
    -webkit-mask: linear-gradient(to bottom, transparent, #000 40%, #000 60%, transparent);
  }
}

/* Ambient depth: the stage's orbs, band and lobes drift slowly at different depths (the `translate`
   property, which also carries each layer's placement (--ty): transform-only, compositor, and independent of the `rotate` the band already uses). Each
   is an infinite CSS loop, so the global off-screen hook pauses it while the stage is out of view;
   reduced motion turns it into a single 1 ms pass (static composition). */
@keyframes sheen-stage-drift-a {
  from {
    translate: -0.75rem calc(var(--ty, 0px) + 0.5rem);
  }
  to {
    translate: 0.75rem calc(var(--ty, 0px) - 0.75rem);
  }
}
@keyframes sheen-stage-drift-b {
  from {
    translate: 1rem calc(var(--ty, 0px) - 0.5rem);
  }
  to {
    translate: -1.25rem calc(var(--ty, 0px) + 0.9rem);
  }
}
@keyframes sheen-stage-drift-c {
  from {
    translate: -1.5rem var(--ty, 0px);
  }
  to {
    translate: 1.5rem calc(var(--ty, 0px) + 0.25rem);
  }
}
@layer sheen {
  @media (prefers-reduced-motion: no-preference) {
    :root:not([data-motion="reduced"]) .sheen-stage-backdrop > [data-s="1"] {
      animation: sheen-stage-drift-a var(--sheen-duration-drift-a) var(--sheen-ease-in-out) infinite alternate;
    }
    :root:not([data-motion="reduced"]) .sheen-stage-backdrop > [data-s="2"] {
      animation: sheen-stage-drift-b var(--sheen-duration-drift-b) var(--sheen-ease-in-out) infinite alternate;
    }
    :root:not([data-motion="reduced"]) .sheen-stage-backdrop > [data-s="3"] {
      animation: sheen-stage-drift-c var(--sheen-duration-drift-c) var(--sheen-ease-in-out) infinite alternate;
    }
  }
}

/* Parallax depth: as a stage scrolls through the viewport its three layers travel at different rates (the far layer
   least), on `transform` so it composes with the drift's `translate` and the band's `rotate`. Scroll-linked (a view
   timeline, not a loop): nothing runs while the stage is off-screen, and reduced motion leaves it still. */
@keyframes sheen-stage-par-far {
  from {
    transform: translateY(5%);
  }
  to {
    transform: translateY(-5%);
  }
}
@keyframes sheen-stage-par-mid {
  from {
    transform: translateY(12%);
  }
  to {
    transform: translateY(-12%);
  }
}
@keyframes sheen-stage-par-near {
  from {
    transform: translateY(22%);
  }
  to {
    transform: translateY(-22%);
  }
}
@layer sheen {
  @supports (animation-timeline: view()) {
    @media (prefers-reduced-motion: no-preference) {
      :root:not([data-motion="reduced"]) .sheen-stage-backdrop > [data-s="1"] {
        animation:
          sheen-stage-drift-a var(--sheen-duration-drift-a) var(--sheen-ease-in-out) infinite alternate,
          sheen-stage-par-mid linear both;
        animation-timeline: auto, view();
        animation-range:
          normal,
          cover 0% cover 100%;
      }
      :root:not([data-motion="reduced"]) .sheen-stage-backdrop > [data-s="2"] {
        animation:
          sheen-stage-drift-b var(--sheen-duration-drift-b) var(--sheen-ease-in-out) infinite alternate,
          sheen-stage-par-near linear both;
        animation-timeline: auto, view();
        animation-range:
          normal,
          cover 0% cover 100%;
      }
      :root:not([data-motion="reduced"]) .sheen-stage-backdrop > [data-s="3"] {
        animation:
          sheen-stage-drift-c var(--sheen-duration-drift-c) var(--sheen-ease-in-out) infinite alternate,
          sheen-stage-par-far linear both;
        animation-timeline: auto, view();
        animation-range:
          normal,
          cover 0% cover 100%;
      }
    }
  }

  :root[data-transparency="reduced"] .sheen-stage-backdrop {
    opacity: 0.45;
  }

  @media (prefers-reduced-transparency: reduce) {
    .sheen-stage-backdrop {
      opacity: 0.45;
    }
  }

  /* ======================================================================
 * Display type and the accent word
 * ====================================================================== */
  .sheen-display {
    font-family: var(--sheen-font-display);
    font-weight: var(--sheen-display-weight);
    letter-spacing: var(--sheen-display-tracking);
  }

  /* The style's accent word: Liquid = italic spectrum, Aurora = serif italic aurora. Painted with
   the AA-checked text gradient. Use on ONE word or short phrase per heading. */
  .sheen-accent-text {
    font-family: var(--sheen-font-accent);
    font-style: var(--sheen-accent-style);
    font-weight: var(--sheen-accent-weight);
    font-size: var(--sheen-accent-size);
    letter-spacing: normal;
    color: transparent;
    background-image: var(--sheen-text-gradient);
    background-size: 220% 100%;
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-box-decoration-break: clone;
    box-decoration-break: clone;
    /* Room for the italic overhang, so the gradient never clips the last letter. */
    padding-inline-end: 0.08em;
  }

  :root:not([data-sheen-style="aurora"]) .sheen-accent-text {
    letter-spacing: -0.03em;
  }

  @media (forced-colors: active) {
    .sheen-accent-text {
      color: CanvasText;
      background: none;
    }
  }

  /* Aurora, every page: the content area sits under a soft veil of the page tint, so body text and links that
   fall on the bare sky keep 4.5:1 at the worst pixel in both themes (the vivid light stays in the hero, behind
   its glass). Opacity of one static layer, so it costs no extra pass. */
  .sheen-sky[data-mode="page"][data-style="aurora"]::after {
    content: "";
    position: absolute;
    inset: 0;
    background: var(--sheen-bg);
    opacity: 0.34;
    pointer-events: none;
  }

  /*
 * <SheenScene>: a real picture behind glass (so the blur has something to refract).
 *   .sheen-scene             fills its positioned parent (or the page when [data-fixed]); aria-hidden
 *     .sheen-scene__layer    the image holder; oversized while [data-parallax] so the drift never shows an edge
 *     .sheen-scene__dim      the page background mixed in by --sheen-scene-dim, so text over glass keeps 4.5:1
 * Nothing here wraps glass; no opacity or filter sits on an ancestor of glass.
 */
  .sheen-scene {
    position: absolute;
    inset: 0;
    z-index: 0;
    overflow: hidden;
    pointer-events: none;
    background-color: var(--sheen-bg);
  }

  .sheen-scene[data-fixed] {
    position: fixed;
    z-index: -1;
  }

  .sheen-scene__layer {
    position: absolute;
    inset: 0;
  }

  .sheen-scene[data-parallax] .sheen-scene__layer {
    inset: -5% 0;
  }

  .sheen-scene__layer picture,
  .sheen-scene__img {
    display: block;
    width: 100%;
    height: 100%;
  }

  .sheen-scene__img {
    object-fit: cover;
    user-select: none;
  }

  .sheen-scene__dim {
    position: absolute;
    inset: 0;
    background: color-mix(in oklab, var(--sheen-bg) calc(var(--sheen-scene-dim, 0.5) * 100%), transparent);
  }

  /* Reduced transparency / forced colours: the solid page background, no image. */
  @media (prefers-reduced-transparency: reduce), (forced-colors: active) {
    .sheen-scene__layer {
      display: none;
    }
  }
}

@layer sheen {
  /*
 * Backdrops that make glass look good: soft colour blobs, a faint grid and fine grain.
 * Glass needs something colourful behind it (a flat background makes it look grey) and
 * something crisp (the grid lines) so you can SEE the blur where glass covers it.
 *
 * Usage: <body class="sheen-backdrop"> or <div class="sheen-backdrop"> ...app... </div>
 *
 * Both layers are fixed pseudo-elements behind the content. Nothing here uses
 * mix-blend-mode, filter or opacity on an ancestor of the content: those turn the
 * container into a "backdrop root" and every glass surface inside stops blurring.
 */

  :root,
  [data-theme] {
    /* Blob colours: saturated but light in light mode, so text on the bare page keeps
     4.5:1; deep and cool in dark mode. Peaks sit in the corners, away from body text. */
    --sheen-blob-1: light-dark(oklch(80% 0.13 285 / 0.62), oklch(50% 0.19 285 / 0.55));
    --sheen-blob-2: light-dark(oklch(87% 0.12 185 / 0.8), oklch(56% 0.11 185 / 0.45));
    --sheen-blob-3: light-dark(oklch(84% 0.11 340 / 0.6), oklch(48% 0.16 330 / 0.38));
    --sheen-blob-4: light-dark(oklch(86% 0.09 235 / 0.6), oklch(50% 0.14 250 / 0.42));
    /* Wide, pale centre wash so the middle of the page is not flat. */
    --sheen-blob-5: light-dark(oklch(93% 0.05 20 / 0.55), oklch(40% 0.09 290 / 0.22));
    /* Grid lines: barely there on the open page, fully blurred away under glass. */
    --sheen-backdrop-grid: light-dark(oklch(40% 0.08 285 / 0.07), oklch(100% 0 0 / 0.045));
    --sheen-backdrop-grid-size: 44px;
  }

  .sheen-backdrop {
    position: relative;
    min-height: 100%;
    background-color: var(--sheen-bg);
  }

  /*
 * On a <div>, the blobs (z-index: -1) need a stacking context to stay inside it and in
 * front of its background. <body> does not: its background paints the canvas, below them.
 * Isolation on <body> is left off on purpose; together with any blend mode inside, it made
 * Chromium stop blurring behind glass.
 */
  .sheen-backdrop:not(body) {
    isolation: isolate;
  }

  .sheen-backdrop::before,
  .sheen-backdrop::after {
    content: "";
    position: fixed;
    z-index: -1;
    pointer-events: none;
  }

  /*
 * Colour blobs. Plain radial gradients, no filter: blur(): they are soft on their own, and
 * an unfiltered layer is a single texture the compositor can move for free.
 * Only transform is animated.
 */
  .sheen-backdrop::before {
    inset: -10%;
    background:
      radial-gradient(38% 44% at 10% 14%, var(--sheen-blob-1), transparent 72%),
      radial-gradient(34% 40% at 88% 12%, var(--sheen-blob-2), transparent 72%),
      radial-gradient(40% 44% at 76% 88%, var(--sheen-blob-3), transparent 72%),
      radial-gradient(32% 38% at 16% 90%, var(--sheen-blob-4), transparent 72%),
      radial-gradient(55% 50% at 50% 50%, var(--sheen-blob-5), transparent 75%);
    animation: sheen-float var(--sheen-duration-ambient) var(--sheen-ease-in-out) infinite;
  }

  /* Grid + grain: crisp detail for the glass to blur. Grain is baked at low alpha (no blending). */
  .sheen-backdrop::after {
    inset: 0;
    background-image:
      url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/><feColorMatrix values='0 0 0 0 0.5 0 0 0 0 0.5 0 0 0 0 0.5 0 0 0 0.07 0'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>"),
      linear-gradient(to bottom, var(--sheen-backdrop-grid) 1px, transparent 1px),
      linear-gradient(to right, var(--sheen-backdrop-grid) 1px, transparent 1px);
    background-size:
      160px 160px,
      var(--sheen-backdrop-grid-size) var(--sheen-backdrop-grid-size),
      var(--sheen-backdrop-grid-size) var(--sheen-backdrop-grid-size);
    background-position:
      0 0,
      -1px -1px,
      -1px -1px;
  }

  /* ---------- Hold the drift still: lite glass, reduced transparency, reduced motion ---------- */
  [data-glass="lite"] .sheen-backdrop::before,
  [data-motion="reduced"] .sheen-backdrop::before,
  [data-transparency="reduced"] .sheen-backdrop::before {
    animation: none;
  }

  @media (prefers-reduced-motion: reduce), (prefers-reduced-transparency: reduce) {
    .sheen-backdrop::before {
      animation: none;
    }
  }

  /* Calmer backdrop when transparency is reduced: glass turns solid, so blobs only tint the page. */
  [data-transparency="reduced"] .sheen-backdrop::before {
    opacity: 0.4;
  }

  @media (prefers-reduced-transparency: reduce) {
    .sheen-backdrop::before {
      opacity: 0.4;
    }
  }

  /* Windows high contrast: decoration only, so it goes. */
  @media (forced-colors: active) {
    .sheen-backdrop::before,
    .sheen-backdrop::after {
      display: none;
    }
  }
}

/*
 * More contrast: the OS asks for it (prefers-contrast: more). Imported LAST so it wins over the presets,
 * which set the same tokens.
 *
 *   - text: muted and subtle text become full-strength text
 *   - edges: borders and control borders turn solid and strong
 *   - surfaces: glass is opaque, with no blur, no rim light and no wallpaper behind it
 *   - links and focus keep their own colours (they already meet 7:1 in both themes)
 */
/* Windows forced colors has its own rules (glass.css); this layer is for everyone else. */
@media (prefers-contrast: more) and (forced-colors: none) {
  :root:root:root,
  [data-theme][data-theme][data-theme] {
    --sheen-fg-muted: var(--sheen-fg);
    --sheen-fg-subtle: var(--sheen-fg);
    --sheen-border: light-dark(oklch(30% 0.03 285), oklch(92% 0.01 285));
    --sheen-control-border: light-dark(oklch(30% 0.03 285), oklch(92% 0.01 285));
    --sheen-glass-border: light-dark(oklch(30% 0.03 285), oklch(92% 0.01 285));
    --sheen-hover: light-dark(oklch(25% 0.03 285 / 0.12), oklch(100% 0 0 / 0.18));
  }

  .glass-1,
  .glass-2,
  .glass-3,
  [data-slot="liquid-glass"],
  [data-slot="glass-card"] {
    background-color: var(--sheen-surface-solid);
    background-image: none;
    border: 1px solid var(--sheen-fg);
    box-shadow: none;
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }

  :is(.glass-1, .glass-2, .glass-3)::after,
  [data-slot="liquid-glass-tint"],
  [data-slot="liquid-glass-rim"] {
    display: none;
  }

  /* The live wallpaper only tints the page: shapes, orbs and grain go, the flat base stays. */
  .sheen-sky > :not(.sheen-sky__base),
  .sheen-backdrop::before,
  .sheen-backdrop::after,
  .sheen-stage-backdrop {
    display: none;
  }

  /* Accent-filled buttons and badges: a flat, dark accent instead of the gradient, so white text is 7:1+ in both themes. */
  .sheen-fill,
  [class~="[background-image:var(--sheen-accent-fill)]"],
  [class~="bg-(image:--sheen-accent-fill)"],
  [style*="sheen-accent-fill"] {
    background-image: none !important;
    background-color: oklch(36% 0.22 290);
    color: var(--sheen-accent-fg);
  }

  /* Gradient text is decoration over a changing colour: use the plain text colour. */
  [class~="bg-clip-text"] {
    -webkit-text-fill-color: currentColor;
    background: none;
    color: var(--sheen-fg);
  }

  /* Underline links in running text; the accent alone is not enough. */
  main a:not([data-slot]):not([role]) {
    text-decoration-line: underline;
    text-underline-offset: 0.2em;
  }
}

/*
 * SheenUI glass engine.
 *
 * Levels:  .glass-1  chips, inputs        (tint + rim, no blur of its own: see the glass budget)
 *          .glass-2  cards, popovers      (medium blur)
 *          .glass-3  dialogs, nav bars    (strong blur, most opaque, deepest shadow)
 *
 * What makes it read as glass (not a translucent grey box):
 *   - backdrop blur + saturation (+ a brightness tweak per style preset)
 *   - a lit rim that CATCHES LIGHT: every glass surface owns an ::after rim layer that the
 *     pointer light lights up (see motion/pointer-light.ts and the style presets)
 *   - a soft inner glow and a specular gradient from the top-left, plus fine noise
 *   - an elevation shadow that grows with the level
 *
 * The values here are the CONTRACT defaults. Each style preset (styles/presets/*.css) re-points
 * them; components only ever read these names.
 *
 * Every level degrades gracefully:
 *   - no backdrop-filter support        → solid surface
 *   - reduced transparency (OS or [data-transparency="reduced"]) → solid surface, no rim light
 *   - prefers-contrast: more            → solid surface, solid border
 *   - forced-colors (Windows HC)        → system colors, no blur, no rim
 *   - [data-glass="lite"]               → cheaper blur for slow devices
 *
 * Glass budget (at most 8 blurred surfaces in view): glass nested inside glass
 * has NO backdrop-filter of its own. The outer surface is already a backdrop root, so a nested
 * blur could only ever blur the outer surface's own tint: same look, one render pass less per
 * frame. For the same reason glass-1 never blurs: it is the level of checkboxes, switches,
 * avatars, chips and inputs, a dozen of which sit in one view (a docs stage measured 11-17
 * blurred surfaces), and each one costs a full offscreen pass for a frost nobody can see on a
 * 20 px square. Its denser tint, specular, noise and lit rim still read as glass.
 *
 * Rule of thumb: never fade or filter a WRAPPER of a glass element.
 * An ancestor with opacity < 1, filter, mask, clip-path or mix-blend-mode becomes a
 * "backdrop root" and the blur stops seeing the page behind it. Animate the glass element itself.
 * Glass surfaces own their ::after (the rim). Use ::before (e.g. .glass-sheen) for anything else.
 */

/* Pointer light (written inline by motion/pointer-light.ts). Not inherited: a write restyles the
   surface and its rim layer only, never the surface's subtree. The rim layer inherits them
   explicitly. Rest values = ambient light from the top-left. */
@property --sheen-mx {
  syntax: "<length-percentage>";
  inherits: false;
  initial-value: 18%;
}

@property --sheen-my {
  syntax: "<length-percentage>";
  inherits: false;
  initial-value: -8%;
}

@property --sheen-ra {
  syntax: "<angle>";
  inherits: false;
  initial-value: -40deg;
}

@property --sheen-lit {
  syntax: "<number>";
  inherits: false;
  initial-value: 0.42;
}

@property --sheen-flare {
  syntax: "<number>";
  inherits: false;
  initial-value: 1;
}

/* The card sheen (GlassCard, HoverCard: written inline on every pointer move over the card). Registered and
   not inherited for the same reason as the pointer light: an unregistered custom property is inherited, so
   each write restyled the card's WHOLE subtree (50-150 elements per move on a dashboard panel). The sheen
   layer (.glass-sheen::before) inherits the two values explicitly. */
@property --sheen-x {
  syntax: "<length-percentage>";
  inherits: false;
  initial-value: 50%;
}

@property --sheen-y {
  syntax: "<length-percentage>";
  inherits: false;
  initial-value: -20%;
}
@layer sheen {
  :root,
  [data-theme] {
    /* Dark glass is a smoked tint, not a white frost: over the bright violet blob peak a white
     frost lifted the backdrop so far that status, accent and caption text on glass-1 fell to
     ~3.3:1. The tint darkens bright spots and still lifts the flat near-black page a little. */
    --sheen-glass-1-bg: light-dark(oklch(100% 0 0 / 0.5), oklch(22% 0.02 275 / 0.42));
    --sheen-glass-2-bg: light-dark(oklch(100% 0 0 / 0.55), oklch(24% 0.02 275 / 0.5));
    --sheen-glass-3-bg: light-dark(oklch(100% 0 0 / 0.72), oklch(20% 0.02 275 / 0.7));

    /* Blur radius per level (lengths). Saturation and brightness are per theme / style.
     glass-1-blur is kept for surfaces that opt into their own frost (LiquidGlass "clear"). */
    --sheen-glass-1-blur: 12px;
    --sheen-glass-2-blur: 20px;
    --sheen-glass-3-blur: 32px;
    --sheen-glass-saturate: 180%;
    --sheen-glass-brightness: 1;
    /* Fine noise on the glass (a bitmap tile set at runtime by <SheenBackdrop>; none until then). */
    --sheen-glass-noise: none;
    --sheen-glass-noise-size: 140px;

    /* Rim lighting: light falls from the top-left. */
    --sheen-glass-border: light-dark(oklch(100% 0 0 / 0.6), oklch(100% 0 0 / 0.1));
    --sheen-glass-highlight: light-dark(oklch(100% 0 0 / 0.95), oklch(100% 0 0 / 0.16));
    --sheen-glass-highlight-side: light-dark(oklch(100% 0 0 / 0.55), oklch(100% 0 0 / 0.07));
    --sheen-glass-lowlight: light-dark(oklch(100% 0 0 / 0.3), oklch(100% 0 0 / 0.03));
    /* Hairline just outside the border, so light glass has an edge on a light page. */
    --sheen-glass-edge: light-dark(oklch(35% 0.05 280 / 0.1), oklch(0% 0 0 / 0.35));
    --sheen-glass-glow: light-dark(oklch(100% 0 0 / 0.45), oklch(100% 0 0 / 0.035));
    --sheen-glass-specular: linear-gradient(
      160deg,
      light-dark(oklch(100% 0 0 / 0.5), oklch(100% 0 0 / 0.06)),
      transparent 46%
    );
    /* Pointer-following sheen (.glass-sheen). */
    --sheen-glass-sheen: light-dark(oklch(100% 0 0 / 0.75), oklch(100% 0 0 / 0.09));

    /* light-dark() only accepts colours, so shadows are built from colour tokens. */
    --sheen-shadow-near: light-dark(oklch(20% 0.03 275 / 0.07), oklch(0% 0 0 / 0.3));
    --sheen-shadow-far: light-dark(oklch(25% 0.06 280 / 0.2), oklch(0% 0 0 / 0.55));
    /* Coloured cast: light through tinted glass (presets give it the style's hue). */
    --sheen-shadow-cast: transparent;
    --sheen-glass-1-shadow: 0 1px 2px var(--sheen-shadow-near), 0 6px 16px -8px var(--sheen-shadow-far);
    --sheen-glass-2-shadow: 0 1px 2px var(--sheen-shadow-near), 0 14px 38px -12px var(--sheen-shadow-far);
    --sheen-glass-3-shadow: 0 2px 6px var(--sheen-shadow-near), 0 28px 64px -18px var(--sheen-shadow-far);
    /* Kept for components that compose their own shadow. */
    --sheen-glass-shadow: var(--sheen-glass-2-shadow);
    --sheen-glass-rim:
      inset 0 1px 0 0 var(--sheen-glass-highlight), inset 1px 0 0 0 var(--sheen-glass-highlight-side),
      inset -1px -1px 0 0 var(--sheen-glass-lowlight), 0 0 0 1px var(--sheen-glass-edge);
    /* The full box-shadow of each level (presets swap in their own stack). */
    --sheen-glass-1-box: var(--sheen-glass-rim), inset 0 0 8px 0 var(--sheen-glass-glow), var(--sheen-glass-1-shadow);
    --sheen-glass-2-box: var(--sheen-glass-rim), inset 0 0 16px 0 var(--sheen-glass-glow), var(--sheen-glass-2-shadow);
    --sheen-glass-3-box: var(--sheen-glass-rim), inset 0 0 24px 0 var(--sheen-glass-glow), var(--sheen-glass-3-shadow);

    /* ---- Rim light ("glass catches light"): drawn by each preset in .glass-*::after ---- */
    --sheen-rim-width: 1.5px;
    /* The hot spot nearest the light, the bright side, the base ring, the far (counter) side. */
    --sheen-rim-core: oklch(100% 0 0);
    --sheen-rim-hot: light-dark(oklch(100% 0 0 / 0.9), oklch(100% 0 0 / 0.6));
    --sheen-rim-fall: light-dark(oklch(100% 0 0 / 0.6), oklch(100% 0 0 / 0.3));
    --sheen-rim-base: light-dark(oklch(100% 0 0 / 0.3), oklch(100% 0 0 / 0.08));
    --sheen-rim-counter: light-dark(oklch(25% 0.05 290 / 0.18), oklch(100% 0 0 / 0.05));
    /* Prism tints either side of the bright arc. */
    --sheen-rim-iri-a: light-dark(oklch(84% 0.12 215), oklch(84% 0.12 212 / 0.8));
    --sheen-rim-iri-b: light-dark(oklch(80% 0.15 345), oklch(78% 0.17 348 / 0.8));
    /* A soft light inside the glass under the pointer (behind the text). */
    --sheen-glass-spot: light-dark(oklch(100% 0 0 / 0.5), oklch(100% 0 0 / 0.1));

    --sheen-surface-solid: light-dark(var(--sheen-ink-0), var(--sheen-ink-800));
  }

  /* Dark glass saturates less: the dark blobs are already deep, and over-saturating them
   pulls text contrast down. Set per theme (not light-dark) because it is not a colour. */
  @media (prefers-color-scheme: dark) {
    :root {
      --sheen-glass-saturate: 140%;
    }
  }

  [data-theme="light"] {
    --sheen-glass-saturate: 180%;
  }

  [data-theme="dark"] {
    --sheen-glass-saturate: 140%;
  }
}

@layer components {
  .glass-1,
  .glass-2,
  .glass-3 {
    position: relative;
    isolation: isolate;
    border: 1px solid var(--sheen-glass-border);
    background-image: var(--sheen-glass-specular), var(--sheen-glass-noise);
    background-size:
      100% 100%,
      var(--sheen-glass-noise-size);
    color: var(--sheen-fg);
  }

  /* No backdrop-filter (glass budget, see the header): the tint carries the frost. */
  .glass-1 {
    background-color: var(--sheen-glass-1-bg);
    box-shadow: var(--sheen-glass-1-box);
  }

  /* The -webkit- lines use literal values: older Safari ignores var() inside the prefixed property. */
  .glass-2 {
    background-color: var(--sheen-glass-2-bg);
    box-shadow: var(--sheen-glass-2-box);
    -webkit-backdrop-filter: blur(20px) saturate(170%);
    backdrop-filter: blur(var(--sheen-glass-2-blur)) saturate(var(--sheen-glass-saturate))
      brightness(var(--sheen-glass-brightness));
  }

  .glass-3 {
    background-color: var(--sheen-glass-3-bg);
    box-shadow: var(--sheen-glass-3-box);
    -webkit-backdrop-filter: blur(32px) saturate(170%);
    backdrop-filter: blur(var(--sheen-glass-3-blur)) saturate(var(--sheen-glass-saturate))
      brightness(var(--sheen-glass-brightness));
  }

  /*
   * The rim layer: a ring inside the surface's edge, painted ONLY in its own border stroke
   * (background-clip: border-area, no mask, so no offscreen pass), plus a soft inner light
   * (padding-box) behind the content. Each style preset paints it (presets/*.css), reading the
   * pointer light: --sheen-mx / --sheen-my / --sheen-ra / --sheen-lit / --sheen-flare.
   * inset: 0 (the padding box) so overflow: hidden surfaces keep their rim.
   */
  .glass-1::after,
  .glass-2::after,
  .glass-3::after {
    --sheen-mx: inherit;
    --sheen-my: inherit;
    --sheen-ra: inherit;
    --sheen-lit: inherit;
    --sheen-flare: inherit;
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    border: var(--sheen-rim-width) solid transparent;
    border-radius: inherit;
    pointer-events: none;
    background-origin: border-box;
  }

  /* Specular sheen that follows the pointer (set --sheen-x / --sheen-y from JS). */
  .glass-sheen::before {
    --sheen-x: inherit;
    --sheen-y: inherit;
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    pointer-events: none;
    background: radial-gradient(
      420px circle at var(--sheen-x, 50%) var(--sheen-y, -20%),
      var(--sheen-glass-sheen),
      transparent 60%
    );
    opacity: var(--sheen-glow, 0.7);
    transition: opacity var(--sheen-duration-base) var(--sheen-ease-out);
  }

  /* A card that carries its own moving light layer (GlassCard) doesn't paint the pointer-written gradient. */
  .glass-sheen:has(> [data-slot="glass-card-sheen"])::before {
    content: none;
  }

  /* Accent-tinted variant for primary surfaces. */
  .glass-tint {
    background-image:
      var(--sheen-glass-specular),
      linear-gradient(
        135deg,
        color-mix(in oklab, var(--sheen-spectrum-1, var(--sheen-violet-500)) 18%, transparent),
        color-mix(in oklab, var(--sheen-spectrum-5, var(--sheen-teal-500)) 12%, transparent)
      );
    background-size: 100% 100%;
  }
}
@layer sheen {
  /* A surface the pointer is lighting: its rim layer gets its own compositor layer, so moving the
   light repaints only the rim, never the surface's text, noise and shadows. */
  [data-sheen-lit]::after {
    will-change: transform;
  }

  /* Browsers without background-clip: border-area (Firefox) cannot paint the moving rim. They get a static one instead:
   a hairline of the lit top and left edges and a faint lowlight, from the same tokens (no pointer light, no animation).
   The presets paint the rim unlayered, so this repeats :root to out-rank them without !important. */
  @supports not (background-clip: border-area) {
    :root:root:root:root :is(.glass-1, .glass-2, .glass-3)::after {
      background: none;
      opacity: 1;
      box-shadow:
        inset 0 1px 0 var(--sheen-glass-highlight),
        inset 1px 0 0 var(--sheen-glass-highlight-side),
        inset 0 -1px 0 var(--sheen-glass-lowlight);
    }
  }

  /* ---------- Lite mode: cheaper blur for low-end devices ---------- */
  [data-glass="lite"] .glass-2,
  [data-glass="lite"] .glass-3 {
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px) saturate(var(--sheen-glass-saturate));
  }

  /* ---------- Glass budget: nested glass draws no blur of its own (see the header) ---------- */
  :is(.glass-1, .glass-2, .glass-3) :is(.glass-1, .glass-2, .glass-3) {
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }

  /* Glass budget with a modal open: a dialog (the command palette included) sits over a dimmed page, so the page's
   own surfaces stop blurring while it is open (the dialog is the one new blur). Blurring them again behind the
   scrim took /blocks/pricing to 10 surfaces with the search open.
   `data-modal-open` is set on <html> by DialogContent for as long as its popup is in the DOM (lib/modal-flag.ts).
   Written as `:root:has([data-slot="dialog-content"])` this rule made the browser re-check the whole document on
   every insertion while a dialog opened or closed (six to nine times per open at 4x CPU). */
  :root[data-modal-open]
    :is(.glass-2, .glass-3):not(
      [data-slot="dialog-content"],
      [data-slot="dialog-content"] *,
      [data-slot="command-palette"],
      [data-slot="command-palette"] *
    ) {
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }

  /* Visually hidden glass (a skip link before it is focused) has nothing to blur. */
  :is(.glass-1, .glass-2, .glass-3).sr-only {
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }

  /* ---------- No backdrop-filter support at all ---------- */
  @supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
    .glass-1,
    .glass-2,
    .glass-3 {
      background-color: var(--sheen-surface-solid);
    }
  }

  /* ---------- Reduced transparency: OS setting (Chromium) or in-app toggle (all browsers) ---------- */
  @media (prefers-reduced-transparency: reduce) {
    .glass-1,
    .glass-2,
    .glass-3 {
      background-color: var(--sheen-surface-solid);
      background-image: none;
      -webkit-backdrop-filter: none;
      backdrop-filter: none;
    }

    .glass-1::after,
    .glass-2::after,
    .glass-3::after {
      display: none;
    }
  }

  [data-transparency="reduced"] .glass-1,
  [data-transparency="reduced"] .glass-2,
  [data-transparency="reduced"] .glass-3 {
    background-color: var(--sheen-surface-solid);
    background-image: none;
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }

  [data-transparency="reduced"] :is(.glass-1, .glass-2, .glass-3)::after {
    display: none;
  }

  /* ---------- More contrast ---------- */
  @media (prefers-contrast: more) {
    .glass-1,
    .glass-2,
    .glass-3 {
      background-color: var(--sheen-surface-solid);
      background-image: none;
      border-color: var(--sheen-fg);
    }

    .glass-1::after,
    .glass-2::after,
    .glass-3::after {
      display: none;
    }
  }
}

/*
 * ---------- Windows high contrast / forced colors ----------
 * The browser drops box-shadows and gradient backgrounds here, so anything that relied
 * on them needs a system-colour equivalent:
 *   - glass       → Canvas surface with a CanvasText border
 *   - focus rings → a real 2px Highlight outline (box-shadow rings vanish)
 *   - filled controls (accent-fill gradient) → Highlight / HighlightText.
 *     Opt in with the .sheen-fill class on any element whose fill is always on
 *     (solid button, solid badge, slider range, progress bar, active indicator).
 *     An unconditional `[background-image:var(--sheen-accent-fill)]` utility class or an
 *     inline style that mentions sheen-accent-fill is picked up automatically.
 *     For fills that depend on state (checked switch, checked checkbox), use Tailwind's
 *     forced-colors: variant on that state instead.
 */
@media (forced-colors: active) {
  .glass-1,
  .glass-2,
  .glass-3 {
    background: Canvas;
    color: CanvasText;
    border-color: CanvasText;
    box-shadow: none;
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }

  .glass-1::after,
  .glass-2::after,
  .glass-3::after,
  .glass-sheen::before {
    display: none;
  }

  :focus-visible {
    outline: 2px solid Highlight !important;
    outline-offset: 2px !important;
  }

  .sheen-fill,
  [class~="[background-image:var(--sheen-accent-fill)]"],
  [class~="bg-(image:--sheen-accent-fill)"],
  [style*="sheen-accent-fill"] {
    forced-color-adjust: none;
    background: Highlight;
    color: HighlightText;
    border-color: Highlight;
    /* forced-color-adjust: none would otherwise keep the decorative glow. */
    box-shadow: none;
    text-shadow: none;
  }

  /* Children follow the fill's system colours (icons use currentColor; decorative shine goes). */
  .sheen-fill :where(*),
  [class~="[background-image:var(--sheen-accent-fill)]"] :where(*),
  [class~="bg-(image:--sheen-accent-fill)"] :where(*),
  [style*="sheen-accent-fill"] :where(*) {
    color: inherit;
    background: none;
  }

  .sheen-fill:is(:disabled, [aria-disabled="true"], [data-disabled]),
  [class~="[background-image:var(--sheen-accent-fill)]"]:is(:disabled, [aria-disabled="true"], [data-disabled]) {
    background: Canvas;
    color: GrayText;
    border-color: GrayText;
  }
}

@layer sheen {
  /* =====================================================================
 * Micro-interaction layer: the sweep layer's structure (behaviour and keyframes: motion.css).
 * One child span inside a glass surface (GlassCard, DialogContent): a clipped box with a band of
 * light in it. No backdrop-filter, so it adds no glass surface to the budget. It sits at z -10,
 * like the card's pointer light: over the glass fill, under the content.
 * ===================================================================== */
  .sheen-sweep {
    position: absolute;
    inset: 0;
    z-index: -10;
    overflow: clip;
    border-radius: inherit;
    pointer-events: none;
  }
  .sheen-sweep > i {
    position: absolute;
    inset-block: -10%;
    left: 0;
    width: 42%;
    opacity: 0;
    background: linear-gradient(
      100deg,
      transparent,
      color-mix(in oklab, var(--sheen-glass-sheen) 100%, transparent) 50%,
      transparent
    );
  }
  /* Right-to-left: the band travels from the inline start. */
  .sheen-sweep:dir(rtl) {
    scale: -1 1;
  }
  @media (forced-colors: active) {
    .sheen-sweep {
      display: none;
    }
  }
}

/* =====================================================================
 * State light: light is a material tied to state.
 * A glass surface (or a control) that carries data-state="idle|working|success|warning|error" holds ONE child layer,
 * <span data-slot="state-light" aria-hidden /> (see lib/state-light.tsx), that draws three lights from the glow tokens:
 *   - an aura: a soft glow just outside the edge (outer box-shadow),
 *   - a light pool: a wash rising from the bottom of the surface (radial gradient),
 *   - a lit edge: an inner rim tint plus a faint inner glow (inset box-shadow).
 * The layer is a child, never a wrapper around glass, and it has no backdrop-filter and no animated blur: the shadows are
 * painted once and only opacity changes (transform/opacity gate). Colours: --sheen-accent-glow (working),
 * --sheen-success-glow, --sheen-warning-glow, --sheen-danger-glow (error). Tune per surface with
 * --sl-aura / --sl-pool / --sl-edge (0 to 1, each light's weight) and --sl-strength (0 to 1, the whole layer).
 * The host needs a stacking context (`isolate`, or any glass class) so the layer sits above its fill and below its content.
 * ===================================================================== */
@layer components {
  [data-slot="state-light"] {
    --sl-c: transparent;
    /* The outer light, a little quieter than the rim so a caption written beside the surface keeps 4.5:1 (more so on light). */
    --sl-ac: light-dark(
      color-mix(in oklab, var(--sl-c) 24%, transparent),
      color-mix(in oklab, var(--sl-c) 72%, transparent)
    );
    position: absolute;
    inset: 0;
    z-index: -20;
    border-radius: inherit;
    pointer-events: none;
    opacity: 0;
    /* The light pool floods up from the bottom (strong low, thinning towards the top) over a faint all-over wash. */
    background-image:
      radial-gradient(
        130% 100% at 50% 118%,
        color-mix(in oklab, var(--sl-c) calc(var(--sl-pool, 1) * 100%), transparent),
        color-mix(in oklab, var(--sl-c) calc(var(--sl-pool, 1) * 45%), transparent) 45%,
        transparent 82%
      ),
      radial-gradient(
        90% 70% at 50% 100%,
        color-mix(in oklab, var(--sl-c) calc(var(--sl-pool, 1) * 70%), transparent),
        transparent
      ),
      linear-gradient(color-mix(in oklab, var(--sl-c) calc(var(--sl-pool, 1) * 28%), transparent), transparent);
    box-shadow:
      inset 0 0 0 1.5px color-mix(in oklab, var(--sl-c) calc(var(--sl-edge, 1) * 100%), transparent),
      inset 0 0 0 1px color-mix(in oklab, white calc(var(--sl-edge, 1) * 18%), transparent),
      inset 0 0 30px -4px color-mix(in oklab, var(--sl-c) calc(var(--sl-edge, 1) * 100%), transparent),
      inset 0 0 12px -2px color-mix(in oklab, var(--sl-c) calc(var(--sl-edge, 1) * 100%), transparent),
      inset 0 -14px 24px -12px color-mix(in oklab, var(--sl-c) calc(var(--sl-edge, 1) * 100%), transparent),
      0 0 12px 1px color-mix(in oklab, var(--sl-ac) calc(var(--sl-aura, 1) * 100%), transparent),
      0 0 22px 2px color-mix(in oklab, var(--sl-ac) calc(var(--sl-aura, 1) * 100%), transparent),
      0 0 38px 2px color-mix(in oklab, var(--sl-ac) calc(var(--sl-aura, 1) * 55%), transparent),
      0 14px 30px -10px color-mix(in oklab, var(--sl-ac) calc(var(--sl-aura, 1) * 70%), transparent);
    transition: opacity var(--sheen-duration-slow) var(--sheen-ease-out);
  }
  [data-state="working"] > [data-slot="state-light"] {
    --sl-c: var(--sheen-accent-glow);
    opacity: var(--sl-strength, 1);
  }
  [data-state="success"] > [data-slot="state-light"] {
    --sl-c: var(--sheen-success-glow);
    opacity: var(--sl-strength, 1);
  }
  [data-state="warning"] > [data-slot="state-light"] {
    --sl-c: var(--sheen-warning-glow);
    opacity: var(--sl-strength, 1);
  }
  [data-state="error"] > [data-slot="state-light"] {
    --sl-c: var(--sheen-danger-glow);
    opacity: var(--sl-strength, 1);
  }
  /* A calm accent light that is not a status (a checked switch, an open dialog): data-state="on". */
  [data-state="on"] > [data-slot="state-light"] {
    --sl-c: var(--sheen-accent-glow);
    opacity: var(--sl-strength, 1);
  }
  @keyframes sheen-state-breathe {
    from {
      opacity: calc(var(--sl-strength, 1) * 0.55);
    }
    to {
      opacity: var(--sl-strength, 1);
    }
  }
  @keyframes sheen-state-flash {
    from {
      opacity: 0;
    }
    35% {
      opacity: 1;
    }
    to {
      opacity: var(--sl-strength, 1);
    }
  }
  @media (prefers-reduced-motion: no-preference) {
    :root:not([data-motion="reduced"]) [data-state="working"] > [data-slot="state-light"] {
      animation: sheen-state-breathe calc(var(--sheen-duration-slower) * 2) var(--sheen-ease-out) infinite alternate;
    }
    :root:not([data-motion="reduced"]) :is([data-state="success"], [data-state="error"]) > [data-slot="state-light"] {
      animation: sheen-state-flash var(--sheen-duration-slower) var(--sheen-ease-out) 1;
    }
  }
  /* Reduced motion: the light changes at once, nothing breathes or flashes. */
  @media (prefers-reduced-motion: reduce) {
    [data-slot="state-light"] {
      transition: none;
      animation: none !important;
    }
  }
  [data-motion="reduced"] [data-slot="state-light"] {
    transition: none;
    animation: none !important;
  }
  /* Reduced transparency and forced colours: the light is off (the state is always written as text or an icon too). */
  @media (prefers-reduced-transparency: reduce), (forced-colors: active) {
    [data-slot="state-light"] {
      display: none;
    }
  }
  [data-transparency="reduced"] [data-slot="state-light"] {
    display: none;
  }
}

/*
 * .sheen-hit: an invisible hit area of at least 44 x 44 px on touch screens (WCAG 2.5.5 / 2.5.8).
 * The element keeps its look; an absolutely centred pseudo-element grows only the area that takes taps.
 * Use `.sheen-hit` (::after) by default, `.sheen-hit-before` where ::after is taken (glass rims), and a real
 * `<span aria-hidden class="sheen-hit-area">` child where both pseudo-elements are taken. Fine pointers: no effect.
 * Size comes from --sheen-hit-size (set on coarse pointers in tokens.css); override it per element if needed.
 */
@layer components {
  .sheen-hit,
  .sheen-hit-before {
    position: relative;
  }
  .sheen-hit-area {
    display: none;
  }
}

@media (any-pointer: coarse) {
  @layer components {
    .sheen-hit::after,
    .sheen-hit-before::before,
    .sheen-hit-area {
      content: "";
      position: absolute;
      /*
       * Centre by hand, logical sides, RTL included. `inset: 0; margin: auto` does not centre a box wider than its host in
       * the inline axis (negative free space makes the start margin 0, so a 44 px area sat 24 px off a 20 px control).
       */
      inset-inline-start: calc(50% - max(100%, var(--sheen-hit-size, 2.75rem)) / 2);
      inset-block-start: calc(50% - max(100%, var(--sheen-hit-size, 2.75rem)) / 2);
      inline-size: max(100%, var(--sheen-hit-size, 2.75rem));
      block-size: max(100%, var(--sheen-hit-size, 2.75rem));
    }
    .sheen-hit-area {
      display: block;
    }
  }
}

/*
 * SheenUI styles entry. Import this AFTER Tailwind in your app's CSS:
 *
 *   @import "tailwindcss";
 *   @import "@sheenui/theme/styles.css";
 *   @source "<path-to>/theme/src";
 */

@import "./tokens.css";
@import "./motion.css";
@import "./glass.css";
@import "./backgrounds.css";
/* Style presets: each one re-points the tokens above for its look (data-sheen-style on <html>).
   Liquid Glass is the default (no attribute, or data-sheen-style="liquid"). */
@import "./presets/liquid.css";
@import "./presets/aurora.css";
/* <SheenBackdrop>, preview stages and the type accents of the presets. */
@import "./backdrop.css";
/* prefers-contrast: more. Last, so it overrides the preset tokens. */
@import "./contrast.css";

/* Dark-mode variant that follows [data-theme], not just the OS. */
@custom-variant dark (&:where([data-theme="dark"], [data-theme="dark"] *));

/*
 * motion-ok: apply only when movement is welcome — the OS allows it AND the in-app
 * toggle ([data-motion="reduced"]) is off. Use for transforms: motion-ok:hover:-translate-y-0.5
 */
@custom-variant motion-ok {
  @media (prefers-reduced-motion: no-preference) {
    &:where(:root:not([data-motion="reduced"]) *) {
      @slot;
    }
  }
}

/*
 * motion-reduced: the exact inverse of motion-ok. Applies when the OS asks for reduced motion
 * OR the in-app toggle is on. Use it for the calmer stand-in, e.g. a short fade where
 * motion-ok gets a slide: motion-ok:translate-x-2 motion-reduced:transition-opacity
 */
@custom-variant motion-reduced {
  @media (prefers-reduced-motion: reduce) {
    @slot;
  }
  &:where(:root[data-motion="reduced"] *) {
    @slot;
  }
}

/*
 * Expose SheenUI tokens to Tailwind utilities:
 *   bg-sheen-bg, text-sheen-fg-muted, bg-sheen-accent-soft, text-sheen-danger-text,
 *   bg-sheen-hover, outline-sheen-focus, rounded-sheen-lg, ease-sheen-exit,
 *   border-sheen-control-border, border-sheen-danger-border (invalid control edge),
 *   bg-sheen-thumb, bg-sheen-indicator, bg-sheen-scrim, ...
 * Shadow tokens are used directly: shadow-(--sheen-accent-fill-shadow).
 */
@theme inline {
  --color-sheen-bg: var(--sheen-bg);
  --color-sheen-fg: var(--sheen-fg);
  --color-sheen-fg-muted: var(--sheen-fg-muted);
  --color-sheen-fg-subtle: var(--sheen-fg-subtle);
  --color-sheen-border: var(--sheen-border);
  --color-sheen-surface: var(--sheen-surface-solid);

  --color-sheen-accent: var(--sheen-accent);
  --color-sheen-accent-2: var(--sheen-accent-2);
  --color-sheen-accent-fg: var(--sheen-accent-fg);
  --color-sheen-accent-soft: var(--sheen-accent-soft);
  --color-sheen-accent-border: var(--sheen-accent-border);

  --color-sheen-hover: var(--sheen-hover);
  --color-sheen-focus: var(--sheen-focus);
  --color-sheen-ring: var(--sheen-ring);

  --color-sheen-control-border: var(--sheen-control-border);
  --color-sheen-thumb: var(--sheen-thumb);
  --color-sheen-ink-on-dark: var(--sheen-ink-on-dark);
  --color-sheen-ink-on-light: var(--sheen-ink-on-light);
  --color-sheen-indicator: var(--sheen-indicator);
  --color-sheen-scrim: var(--sheen-scrim);

  --color-sheen-success: var(--sheen-success);
  --color-sheen-danger: var(--sheen-danger);
  --color-sheen-warning: var(--sheen-warning);
  --color-sheen-success-text: var(--sheen-success-text);
  --color-sheen-danger-text: var(--sheen-danger-text);
  --color-sheen-warning-text: var(--sheen-warning-text);
  --color-sheen-success-soft: var(--sheen-success-soft);
  --color-sheen-danger-soft: var(--sheen-danger-soft);
  --color-sheen-warning-soft: var(--sheen-warning-soft);
  --color-sheen-danger-border: var(--sheen-danger-border);
  --color-sheen-success-border: var(--sheen-success-border);

  --radius-sheen-sm: var(--sheen-radius-sm);
  --radius-sheen-md: var(--sheen-radius-md);
  --radius-sheen-lg: var(--sheen-radius-lg);
  --radius-sheen-xl: var(--sheen-radius-xl);
  --radius-sheen-full: var(--sheen-radius-full);

  --font-sheen: var(--sheen-font-sans);
  --font-sheen-mono: var(--sheen-font-mono);
  --font-sheen-display: var(--sheen-font-display);

  --color-sheen-bg-2: var(--sheen-bg-2);

  --ease-sheen-out: var(--sheen-ease-out);
  --ease-sheen-in-out: var(--sheen-ease-in-out);
  --ease-sheen-exit: var(--sheen-ease-exit);
  --ease-sheen-spring: var(--sheen-ease-spring);
  --ease-sheen-snappy: var(--sheen-ease-snappy);
  --ease-sheen-smooth: var(--sheen-ease-smooth);
  --ease-sheen-gentle: var(--sheen-ease-gentle);
  --ease-sheen-bouncy: var(--sheen-ease-bouncy);
  --ease-sheen-press: var(--sheen-ease-press);
}

/* Tiny labels (kbd hints, chart ticks, overlines): text-2xs = 11px. */
@theme {
  --text-2xs: 0.6875rem;
  --text-2xs--line-height: 1rem;
}
@layer sheen {
  /* Phones: nothing reads below 12 px (the 11 px labels and badges step up; desktop keeps the denser size). */
  @media (max-width: 639.98px) {
    .text-2xs {
      font-size: 0.75rem;
    }
  }
}

@layer base {
  body {
    background-color: var(--sheen-bg);
    color: var(--sheen-fg);
    font-family: var(--sheen-font-sans);
    -webkit-font-smoothing: antialiased;
  }

  :focus-visible {
    outline: 2px solid var(--sheen-focus);
    outline-offset: 2px;
  }

  ::selection {
    background-color: var(--sheen-selection);
  }

  /*
   * Windows High Contrast / forced colors: backgrounds and shadows are dropped, so a pressable control
   * with no border of its own (icon buttons, ghost buttons, toolbar and navigation items) loses its
   * extent. Give every button a 1px edge in the system colour. Base layer on purpose: any component's
   * own border utility (Button, Tabs, Checkbox...) still wins, and tab triggers sit inside a bordered
   * track so they stay edge-less.
   */
  @media (forced-colors: active) {
    :where(button:not([role="tab"]), [role="button"]) {
      border-width: 1px;
      border-style: solid;
      border-color: ButtonText;
    }
  }
}
@layer sheen {
  /*
 * Chart scale labels (axis ticks, gauge numbers) sit over gridlines, series and bars. A halo in the chart surface colour
 * (painted behind the glyphs, so it hides whatever runs through the digits) keeps every label at its own text-on-surface
 * contrast (WCAG 1.4.3). The pixel-contrast gate in demo/e2e/contrast keeps the halo when it hides the text.
 */
  svg[role="figure"] text.fill-sheen-fg-muted,
  svg[role="figure"] text.fill-sheen-fg-subtle {
    paint-order: stroke fill;
    stroke: var(--sheen-chart-surface);
    stroke-width: 3px;
    stroke-linejoin: round;
  }
  @media (forced-colors: active) {
    svg[role="figure"] text.fill-sheen-fg-muted,
    svg[role="figure"] text.fill-sheen-fg-subtle {
      stroke: Canvas;
    }
    /* Every chart label in system colours, whatever token class it carries: pale token fills vanish on Canvas. */
    svg text {
      fill: CanvasText !important; /* some charts set the fill inline */
