  /* Both halves of the root cross-fade use the SAME duration and curve and blend with plus-lighter inside an
   isolated pair, so old + new opacity is exactly 1 at every frame: the chrome (identical in both snapshots) never
   brightens. Mismatched halves (100 ms ease-in against 220 ms ease-out) pulsed the whole viewport ~40% brighter. */
  ::view-transition-image-pair(root) {
    isolation: isolate;
  }

