  #main[data-route-transition] h1 {
    view-transition-name: sheen-page-title;
  }

  ::view-transition-old(sheen-page-title) {
    animation: sheen-vt-title-out var(--sheen-duration-exit-fast) var(--sheen-ease-exit) both;
  }

  ::view-transition-new(sheen-page-title) {
    animation: sheen-vt-title-in var(--sheen-duration-base) var(--sheen-ease-out) both;
  }

