      );
      /* --sheen-lit rests at 0.42 (ambient light): the pool only shows once the pointer lifts it above that. */
      opacity: clamp(0, calc((var(--sheen-lit, 0.42) - 0.42) * 1.72), 1);
    }
  }
  @media (forced-colors: active) {
    .sheen-spot::before {
      display: none;
    }
  }
}

/*
 * ============================================================================
 *  Style preset: AURORA NEON
 * ============================================================================
 * A premium developer-tool launch: slow curtains of violet, magenta and cyan light behind real
 * frosted glass. Every panel has a glowing gradient rim (white-hot top-left, aurora picked up
 * bottom-right) with a rim light and a 40 px hotspot that follow the pointer. Light mode is a
 * bright daytime aurora on pearl. Display type: Geist, very tight, with ONE Instrument Serif
 * italic accent word per heading.
 *
 * Applies when <html data-sheen-style="aurora">.
 * Source: the approved aurora prototype (recipe: wow/aurora/final.json).
 * Contrast: the prototype's rendered-pixel audit (min 4.93:1 body text, AA everywhere, 22 theme /
 * width / scroll combinations); re-audited on the docs site, see the report.
 */

@font-face {
  font-family: "Geist Fallback";
  src: local("Arial"), local("ArialMT"), local("Helvetica");
  font-weight: 100 549;
  size-adjust: 102.6%;
  ascent-override: 98.4%;
  descent-override: 28.3%;
  line-gap-override: 0%;
}

@font-face {
  font-family: "Geist Fallback";
  src: local("Arial Bold"), local("Arial-BoldMT"), local("Helvetica Bold");
  font-weight: 550 900;
  size-adjust: 101%;
  ascent-override: 100%;
  descent-override: 28.7%;
  line-gap-override: 0%;
}

@font-face {
  font-family: "Instrument Serif Fallback";
  font-style: italic;
  src: local("Times New Roman Italic"), local("TimesNewRomanPS-ItalicMT"), local("Times Italic");
  size-adjust: 85.5%;
  ascent-override: 115.8%;
  descent-override: 36.3%;
  line-gap-override: 0%;
}

@font-face {
  font-family: "Geist Mono Fallback";
  src: local("Menlo"), local("Menlo-Regular"), local("Courier New");
  size-adjust: 99.7%;
  ascent-override: 101.4%;
  descent-override: 29.1%;
  line-gap-override: 0%;
}
@layer sheen {
  :root[data-sheen-style="aurora"],
  :root[data-sheen-style="aurora"] [data-theme] {
    /* ---- Page ---- */
    --sheen-bg: light-dark(oklch(98.2% 0.009 300), oklch(12% 0.03 282));
    --sheen-bg-2: light-dark(oklch(96% 0.02 290), oklch(9.5% 0.03 285));
    --sheen-fg: light-dark(oklch(17% 0.035 285), oklch(98.5% 0.006 285));
    /* Night: muted 90 / subtle 86 (were 84 / 83): measured from pixels, muted text over a bright
     curtain on the bare page and on glass fell to 3.4-4.4:1. */
    --sheen-fg-muted: light-dark(oklch(31% 0.035 285), oklch(90% 0.02 285));
    --sheen-fg-subtle: light-dark(oklch(35% 0.03 285), oklch(86% 0.025 285));
    --sheen-border: light-dark(oklch(30% 0.06 290 / 0.12), oklch(100% 0 0 / 0.1));

    /* ---- Spectrum: aurora light (decorative) ---- */
    --sheen-spectrum-1: light-dark(oklch(60% 0.22 295), oklch(66% 0.25 295)); /* violet */
    --sheen-spectrum-2: light-dark(oklch(64% 0.24 350), oklch(68% 0.27 345)); /* magenta */
    --sheen-spectrum-3: light-dark(oklch(80% 0.13 55), oklch(84% 0.13 55)); /* peach (dark only in gradients) */
    --sheen-spectrum-4: light-dark(oklch(72% 0.2 330), oklch(78% 0.19 330)); /* orchid */
    --sheen-spectrum-5: light-dark(oklch(74% 0.14 210), oklch(86% 0.14 200)); /* cyan */
    --sheen-spectrum-6: light-dark(oklch(62% 0.18 260), oklch(62% 0.2 262)); /* blue */
    --sheen-spectrum-warm: var(--sheen-spectrum-2);

    /* ---- Accent ---- */
    /* Night: 86 % (was 82 %), so accent links on the bare aurora sky keep AA (measured 3.8-4.4:1 at 82 %). */
    --sheen-accent: light-dark(oklch(38% 0.24 292), oklch(86% 0.11 295));
    --sheen-accent-2: light-dark(oklch(48% 0.11 215), oklch(86% 0.14 200));
    --sheen-accent-soft: light-dark(oklch(55% 0.24 292 / 0.12), oklch(72% 0.2 295 / 0.18));
    --sheen-accent-border: light-dark(oklch(55% 0.24 292 / 0.32), oklch(78% 0.16 295 / 0.4));
    /* Words in the aurora gradient, interpolated in oklch (no grey or brown midpoints).
     Light: a cool ramp, every stop L 50-54% with chroma >= .17 (>= 5.1:1 on pearl).
     Dark: cyan, violet, magenta, a peach flare between two magentas, all L >= 77% (>= 8.3:1). */
    --sheen-text-gradient: linear-gradient(
      100deg in oklch,
      light-dark(oklch(50% 0.17 245), oklch(88% 0.13 200)) 0%,
      light-dark(oklch(50% 0.25 295), oklch(77% 0.19 295)) 25%,
      light-dark(oklch(54% 0.26 340), oklch(77% 0.21 345)) 45%,
      light-dark(oklch(50% 0.24 305), oklch(86% 0.12 55)) 60%,
      light-dark(oklch(54% 0.25 345), oklch(78% 0.2 350)) 75%,
      light-dark(oklch(50% 0.17 245), oklch(88% 0.13 200)) 100%
    );
    --sheen-accent-gradient: var(--sheen-text-gradient);
    /* Aurora fill for primary controls: white text >= 5.7:1 on every stop. */
    --sheen-accent-fill: linear-gradient(
      115deg in oklch,
      oklch(48% 0.22 275) 0%,
      oklch(50% 0.25 295) 35%,
      oklch(52% 0.24 335) 75%,
      oklch(54% 0.21 355) 100%
    );
    --sheen-accent-fg: oklch(100% 0 0);
    --sheen-accent-glow: light-dark(oklch(55% 0.25 310 / 0.55), oklch(62% 0.27 320 / 0.75));
    --sheen-accent-fill-shadow:
      inset 0 1px 0 oklch(100% 0 0 / 0.38), inset 0 0 0 1px oklch(100% 0 0 / 0.1),
      0 10px 28px -10px var(--sheen-accent-glow), 0 0 22px -8px oklch(70% 0.2 300 / 0.55);

    /* ---- Interaction ---- */
    --sheen-focus: light-dark(oklch(48% 0.24 292), oklch(88% 0.12 200));
    --sheen-ring: light-dark(oklch(55% 0.24 292 / 0.32), oklch(86% 0.14 200 / 0.35));
    --sheen-selection: light-dark(oklch(66% 0.2 330 / 0.3), oklch(70% 0.22 330 / 0.45));
    --sheen-hover: light-dark(oklch(40% 0.1 290 / 0.07), oklch(100% 0 0 / 0.09));
    --sheen-indicator: light-dark(oklch(100% 0 0 / 0.96), oklch(100% 0 0 / 0.17));

    /* ---- Shape ---- */
    --sheen-radius-sm: 0.75rem;
    --sheen-radius-md: 1rem;
    --sheen-radius-lg: 1.5rem;
    --sheen-radius-xl: 1.75rem;

    /* ---- Type ---- */
    --sheen-font-sans:
      "Geist Variable", "Geist", "Geist Fallback", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
    --sheen-font-mono:
      "Geist Mono Variable", "Geist Mono", "Geist Mono Fallback", ui-monospace, "SF Mono", Menlo, monospace;
    --sheen-font-display: "Geist Variable", "Geist", "Geist Fallback", ui-sans-serif, system-ui, sans-serif;
    /* ONE accent word per heading in a serif italic, 1.18em, painted with the aurora. */
    --sheen-font-accent: "Instrument Serif", "Instrument Serif Fallback", ui-serif, Georgia, serif;
    --sheen-display-weight: 600;
    --sheen-display-tracking: -0.04em;
    --sheen-accent-style: italic;
    --sheen-accent-weight: 400;
    --sheen-accent-size: 1.18em;

    /* ---- Glass (Aurora Neon recipe) ---- */
    /* Dark glass-1 is a smoked tint, not a white frost: chips and inputs carry captions, and a 7%
     white lift over a bright curtain put muted text at ~3.3:1 (measured on /foundations). */
    --sheen-glass-1-bg: light-dark(oklch(97.5% 0.022 300 / 0.58), oklch(16% 0.04 285 / 0.64));
    --sheen-glass-2-bg: light-dark(oklch(97% 0.03 300 / 0.58), oklch(17% 0.04 285 / 0.76));
    --sheen-glass-3-bg: light-dark(oklch(97.5% 0.025 300 / 0.66), oklch(15% 0.04 285 / 0.72));
    --sheen-glass-1-blur: 14px;
    --sheen-glass-2-blur: 22px;
    --sheen-glass-3-blur: 30px;
    --sheen-glass-saturate: 190%;
    --sheen-glass-brightness: 1;
    --sheen-glass-border: light-dark(oklch(100% 0 0 / 0.75), oklch(100% 0 0 / 0.13));
    --sheen-glass-highlight: light-dark(oklch(100% 0 0 / 1), oklch(100% 0 0 / 0.32));
    --sheen-glass-highlight-side: light-dark(oklch(100% 0 0 / 0.6), oklch(100% 0 0 / 0.1));
    --sheen-glass-lowlight: light-dark(oklch(100% 0 0 / 0.3), oklch(100% 0 0 / 0.04));
    --sheen-glass-edge: light-dark(oklch(100% 0 0 / 0.85), oklch(0% 0 0 / 0.55));
    --sheen-glass-glow: light-dark(oklch(80% 0.13 300 / 0.5), oklch(62% 0.24 305 / 0.2));
    --sheen-glass-specular: linear-gradient(
      180deg,
      light-dark(oklch(100% 0 0 / 0.7), oklch(100% 0 0 / 0.075)),
      transparent 42%
    );
    --sheen-glass-sheen: light-dark(oklch(60% 0.2 295 / 0.16), oklch(85% 0.12 295 / 0.16));
    --sheen-shadow-near: light-dark(oklch(45% 0.18 295 / 0.18), oklch(0% 0 0 / 0.5));
    --sheen-shadow-far: light-dark(oklch(45% 0.18 295 / 0.3), oklch(0% 0 0 / 0.7));
    --sheen-shadow-cast: light-dark(oklch(70% 0.18 320 / 0.2), oklch(55% 0.25 300 / 0.3));
    --sheen-glass-1-shadow: 0 0 0 1px var(--sheen-glass-edge), 0 10px 30px -14px var(--sheen-shadow-far);
    --sheen-glass-2-shadow: 0 2px 6px -2px var(--sheen-shadow-far), 0 32px 70px -28px var(--sheen-shadow-far);
    --sheen-glass-3-shadow:
      0 2px 6px -2px var(--sheen-shadow-far), 0 32px 70px -28px var(--sheen-shadow-far),
      0 24px 90px -40px var(--sheen-shadow-cast);
    --sheen-glass-1-box: inset 0 1px 0 0 var(--sheen-glass-highlight), var(--sheen-glass-1-shadow);
    --sheen-glass-2-box:
      inset 0 1px 0 0 var(--sheen-glass-highlight), inset 0 -28px 48px -28px var(--sheen-glass-glow),
      0 0 0 1px var(--sheen-glass-edge), var(--sheen-glass-2-shadow), 0 24px 90px -40px var(--sheen-shadow-cast);
    --sheen-glass-3-box:
      inset 0 1px 0 0 var(--sheen-glass-highlight), inset 0 -28px 48px -28px var(--sheen-glass-glow),
      0 0 0 1px var(--sheen-glass-edge), var(--sheen-glass-3-shadow);
    --sheen-surface-solid: light-dark(oklch(100% 0 0), oklch(19% 0.035 285));

    /* ---- Rim: a gradient ring (white-hot top-left → violet → magenta → cyan), a 220 px rim
     light and a sharp 40 px hotspot that follow the pointer. ---- */
    --sheen-rim-width: 1.5px;
    --sheen-rim-gradient: linear-gradient(
      155deg,
      light-dark(oklch(100% 0 0 / 1), oklch(100% 0 0 / 0.5)) 0%,
      light-dark(oklch(60% 0.22 295 / 0.55), oklch(100% 0 0 / 0.12)) 30%,
      light-dark(oklch(62% 0.22 330 / 0.4), oklch(100% 0 0 / 0.04)) 58%,
      light-dark(oklch(64% 0.22 340 / 0.45), oklch(70% 0.22 330 / 0.4)) 82%,
      light-dark(oklch(70% 0.14 210 / 0.6), oklch(86% 0.13 200 / 0.6)) 100%
    );
    --sheen-rim-hot: light-dark(oklch(58% 0.25 300 / 0.9), oklch(90% 0.1 200 / 0.95));
    --sheen-rim-core: light-dark(oklch(66% 0.22 300), oklch(100% 0 0));
    --sheen-glass-spot: light-dark(oklch(60% 0.2 295 / 0.12), oklch(85% 0.12 295 / 0.14));

    /* ---- Backdrop colours (backgrounds.css blobs, preview stages) ---- */
    --sheen-blob-1: light-dark(oklch(74% 0.17 300 / 0.7), oklch(50% 0.24 295 / 0.7));
    --sheen-blob-2: light-dark(oklch(78% 0.14 210 / 0.7), oklch(56% 0.16 215 / 0.55));
    --sheen-blob-3: light-dark(oklch(78% 0.16 350 / 0.62), oklch(50% 0.23 340 / 0.55));
    --sheen-blob-4: light-dark(oklch(76% 0.14 260 / 0.6), oklch(44% 0.19 270 / 0.55));
    --sheen-blob-5: light-dark(oklch(86% 0.09 262 / 0.7), oklch(24% 0.1 280 / 0.5));
    --sheen-backdrop-grid: light-dark(oklch(40% 0.12 290 / 0.06), oklch(100% 0 0 / 0.04));
    --sheen-backdrop-grid-size: 56px;

    /* ---- Motion intensity: slow light, crisp UI ---- */
    --sheen-motion-intensity: 1;
    --sheen-duration-ambient: 28s;
  }

  /* Dark: glass saturates a little less (keeps light text readable over the brightest ribbons). */
  :root[data-sheen-style="aurora"][data-theme="dark"] {
    --sheen-glass-saturate: 160%;
    --sheen-rim-width: 1px;
  }

  @media (prefers-color-scheme: dark) {
    :root[data-sheen-style="aurora"]:not([data-theme="light"]) {
      --sheen-glass-saturate: 160%;
      --sheen-rim-width: 1px;
    }
  }

  :root[data-sheen-style="aurora"][data-theme="light"] {
    --sheen-glass-saturate: 190%;
    --sheen-rim-width: 1.5px;
  }

  /* Phones: lower blur radii (smaller GPU kernels; the narrow sky needs less frosting anyway). */
  @media (max-width: 639px) {
    :root[data-sheen-style="aurora"] {
      --sheen-glass-1-blur: 12px;
      --sheen-glass-2-blur: 16px;
      --sheen-glass-3-blur: 20px;
    }
  }

  /*
 * The Aurora rim, in each surface's ::after, drawn ONLY in its border stroke (no mask):
 *   1. a sharp 40 px hotspot at the pointer (brightens with --sheen-lit)
 *   2. a 220 px rim light at the pointer
 *   3. the gradient rim
 *   4. a soft spotlight inside the glass under the pointer, behind the content
 * A fast flick flares the rim (filter on the rim layer only, never on the glass).
 */
  :root[data-sheen-style="aurora"] :is(.glass-1, .glass-2, .glass-3)::after {
    background-image:
      radial-gradient(
        calc(40px * var(--sheen-flare)) circle at var(--sheen-mx) var(--sheen-my),
        color-mix(in oklab, var(--sheen-rim-core) calc(var(--sheen-lit) * 100%), transparent),
        transparent 100%
      ),
      radial-gradient(
        calc(220px * var(--sheen-flare)) circle at var(--sheen-mx) var(--sheen-my),
        var(--sheen-rim-hot),
        transparent 70%
      ),
      var(--sheen-rim-gradient),
      radial-gradient(360px circle at var(--sheen-mx) var(--sheen-my), var(--sheen-glass-spot), transparent 65%);
    background-clip: border-area, border-area, border-area, padding-box;
    opacity: calc(0.62 + var(--sheen-lit) * 0.38);
  }

  :root[data-sheen-style="aurora"][data-sheen-flare] [data-sheen-lit]::after {
    --sheen-flare: 1.25;
  }

  :root[data-sheen-style="aurora"] .glass-1::after {
    --sheen-rim-width: 1px;
  }

  /* Preview stages sit on a tinted sky (not pearl white), so light glass reads as glass over light. */
  :root[data-sheen-style="aurora"] .sheen-stage-backdrop {
    --sheen-stage-base: light-dark(oklch(93% 0.04 290), oklch(15% 0.05 285));
  }

  /*
 * Neon on focus and hover. Plain controls get a double ring and an aurora halo; glass controls keep
 * their own shadows (no filter on a backdrop-filter surface) and add the halo as an extra shadow
 * layer, with the rim at full strength. The halo is a shadow colour change only: no layout, no motion.
 */
  :root[data-sheen-style="aurora"]
    :is(
      button,
      a,
      input,
      select,
      textarea,
      summary,
      [role="button"],
      [role="tab"],
      [role="switch"],
      [role="checkbox"],
      [role="slider"],
      [tabindex]
    ):focus-visible:not(.glass-1, .glass-2, .glass-3) {
    box-shadow:
      0 0 0 3px light-dark(oklch(100% 0 0 / 0.9), oklch(12% 0.03 282 / 0.9)),
      0 0 0 5px var(--sheen-focus),
      0 0 24px 2px var(--sheen-accent-glow);
  }
  :root[data-sheen-style="aurora"]
    :is(.glass-1, .glass-2, .glass-3):is(button, a, [role="button"], [role="tab"], [tabindex]):focus-visible {
    box-shadow:
      var(--sheen-glass-2-box),
      0 0 0 4px var(--sheen-ring),
      0 0 28px 2px var(--sheen-accent-glow);
  }
  :root[data-sheen-style="aurora"]
    :is(.glass-1, .glass-2, .glass-3):is(button, a, [role="button"], [role="tab"]):focus-visible::after,
  :root[data-sheen-style="aurora"]
    :is(.glass-1, .glass-2, .glass-3):is(button, a, [role="button"], [role="tab"]):hover::after {
    opacity: 1;
  }
  @media (hover: hover) {
    :root[data-sheen-style="aurora"]
      :is(.glass-1, .glass-2, .glass-3):is(button, a, [role="button"], [role="tab"]):hover:not(:focus-visible) {
      box-shadow:
        var(--sheen-glass-2-box),
        0 0 26px -4px var(--sheen-accent-glow);
    }
  }
}

/*
 * ============================================================================
 *  Style preset: LIQUID GLASS (the default)
 * ============================================================================
 * Thick, clear glass held up to a glowing wallpaper: silk ribbons, glossy spheres and (by day)
 * sunlight caustics behind light, liquid panes. Every pane has a white-hot rim that slides along
 * its edge toward the pointer, a prism tint either side of the lit arc and a counter-rim on the
 * far side. Display type: Inter Tight, tight and heavy, with one italic spectrum accent.
 *
 * Applies when <html data-sheen-style="liquid"> OR when the attribute is missing.
 * Every value is a token from tokens.css / glass.css / backgrounds.css re-pointed for the look;
 * components never need per-style code.
 *
 * Source: the approved liquid prototype (recipe: wow/liquid/final.json).
 * Contrast: text tokens are the prototype's pixel-audited values (0 runs below AA over ~1,000
 * text runs at 1440 and 390, both themes); re-audited on the docs site, see the report.
 */

/* Metric-matched fallbacks: until the web fonts arrive the layout already has their size, so
   nothing reflows when they swap in. */
@font-face {
  font-family: "Inter Fallback";
  src: local("Arial"), local("Helvetica"), local("Liberation Sans");
  size-adjust: 107%;
  ascent-override: 90.5%;
  descent-override: 22.5%;
  line-gap-override: 0%;
}

/* JetBrains Mono advances 0.6em like Courier New / Liberation Mono; its ascent and descent are 102% and 30% of the em. Inline
   code (a chip inside a paragraph) wraps the same way before and after the web font arrives. */
@font-face {
  font-family: "JetBrains Mono Fallback";
  src: local("Courier New"), local("Liberation Mono"), local("Menlo"), local("DejaVu Sans Mono");
  size-adjust: 100%;
  ascent-override: 102%;
  descent-override: 30%;
  line-gap-override: 0%;
}

@font-face {
  font-family: "Inter Tight Fallback";
  src: local("Arial"), local("Helvetica"), local("Liberation Sans");
  size-adjust: 99%;
  ascent-override: 97.8%;
  descent-override: 24.4%;
  line-gap-override: 0%;
}
@layer sheen {
  :root:not([data-sheen-style="aurora"]),
  :root:not([data-sheen-style="aurora"]) [data-theme] {
    /* ---- Page ---- */
    --sheen-bg: light-dark(oklch(97.6% 0.012 75), oklch(13.5% 0.035 283));
    --sheen-bg-2: light-dark(oklch(95.5% 0.025 300), oklch(10% 0.03 285));
    --sheen-fg: light-dark(oklch(18% 0.03 280), oklch(98.5% 0.004 280));
    /* Night: muted 92 / subtle 86 (were 89 / 83). Measured from pixels, muted text on the bare page
     fell to 4.4:1 over the rose and violet orbs and on glass-1/2 over a bright orb. Day: muted 37 (was 40): the
     "Files to copy" summary measured 4.43:1 at its worst pixel on glass; 37 gives 4.7+. */
    --sheen-fg-muted: light-dark(oklch(31% 0.03 280), oklch(92% 0.015 280));
    --sheen-fg-subtle: light-dark(oklch(35% 0.03 280), oklch(86% 0.018 280));
    --sheen-border: light-dark(oklch(25% 0.04 285 / 0.12), oklch(100% 0 0 / 0.12));

    /* ---- Spectrum (wallpaper, rims, casts; never behind text without glass) ---- */
    --sheen-spectrum-1: light-dark(oklch(70% 0.18 295), oklch(55% 0.25 292)); /* violet */
    --sheen-spectrum-2: light-dark(oklch(74% 0.19 352), oklch(63% 0.26 350)); /* magenta */
    --sheen-spectrum-3: light-dark(oklch(80% 0.14 35), oklch(70% 0.19 32)); /* coral */
    --sheen-spectrum-4: light-dark(oklch(89% 0.13 82), oklch(81% 0.16 72)); /* amber */
    --sheen-spectrum-5: light-dark(oklch(86% 0.11 212), oklch(76% 0.13 215)); /* cyan */
    --sheen-spectrum-6: light-dark(oklch(75% 0.15 255), oklch(55% 0.23 264)); /* blue */
    /* Warm orbs: amber by day, a hot rose at night (low-alpha amber over near-black reads brown). */
    --sheen-spectrum-warm: light-dark(oklch(89% 0.13 82), oklch(62% 0.23 12));

    /* ---- Accent ---- */
    --sheen-accent: light-dark(oklch(39% 0.24 290), oklch(84% 0.12 300));
    --sheen-accent-2: light-dark(oklch(46% 0.13 235), oklch(84% 0.11 212));
    --sheen-accent-soft: light-dark(oklch(55% 0.24 300 / 0.12), oklch(78% 0.14 300 / 0.18));
    --sheen-accent-border: light-dark(oklch(50% 0.24 300 / 0.3), oklch(80% 0.13 300 / 0.4));
    /* Headline gradient (indigo → violet → coral by day; cyan → orchid → gold at night).
     Every stop >= 4.5:1 on the page. */
    --sheen-text-gradient: linear-gradient(
      100deg,
      light-dark(oklch(50% 0.22 262), oklch(84% 0.12 215)) 0%,
      light-dark(oklch(50% 0.26 305), oklch(78% 0.17 320)) 30%,
      light-dark(oklch(53% 0.23 25), oklch(86% 0.14 65)) 60%,
      light-dark(oklch(50% 0.26 305), oklch(78% 0.17 320)) 85%,
      light-dark(oklch(50% 0.22 262), oklch(84% 0.12 215)) 100%
    );
    --sheen-accent-gradient: var(--sheen-text-gradient);
    /* Liquid fill: indigo → violet → magenta. White text >= 4.5:1 across the whole sweep. */
    --sheen-accent-fill: linear-gradient(
      115deg,
      oklch(47% 0.23 268) 0%,
      oklch(47% 0.26 298) 48%,
      oklch(50% 0.25 338) 100%
    );
    --sheen-accent-fg: oklch(100% 0 0);
    --sheen-accent-glow: oklch(56% 0.26 318 / 0.7);
    --sheen-accent-fill-shadow:
      inset 0 1px 0.5px oklch(100% 0 0 / 0.55), inset 0 -3px 8px -3px oklch(22% 0.18 300 / 0.5),
      inset 0 0 0 1px oklch(100% 0 0 / 0.14), 0 3px 8px -3px oklch(35% 0.2 290 / 0.45),
      0 14px 34px -12px var(--sheen-accent-glow);

    /* ---- Interaction ---- */
    --sheen-focus: light-dark(oklch(45% 0.25 290), oklch(88% 0.11 300));
    --sheen-ring: light-dark(oklch(55% 0.24 300 / 0.35), oklch(80% 0.14 300 / 0.45));
    --sheen-selection: light-dark(oklch(62% 0.2 300 / 0.28), oklch(72% 0.16 300 / 0.38));
    --sheen-indicator: light-dark(
      oklch(100% 0 0 / 0.92),
      oklch(100% 0 0 / 0.15)
    ); /* night: 0.15 (was 0.2): the selected segment's white label measured 4.4:1 on it */

    /* ---- Shape: controls become capsules, panes are generous ---- */
    --sheen-radius-sm: 0.875rem;
    --sheen-radius-md: 1.5rem;
    --sheen-radius-lg: 1.75rem;
    --sheen-radius-xl: 2.25rem;

    /* ---- Type ---- */
    --sheen-font-sans:
      "Inter Variable", "Inter", "Inter Fallback", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
    --sheen-font-display:
      "Inter Tight Variable", "Inter Tight", "Inter Tight Fallback", ui-sans-serif, system-ui, -apple-system,
      "Segoe UI", sans-serif;
    --sheen-font-accent: var(--sheen-font-display);
    --sheen-display-weight: 680;
    --sheen-display-tracking: -0.028em;
    /* The accent word: a true italic, painted with the spectrum. */
    --sheen-accent-style: italic;
    --sheen-accent-weight: 700;
    --sheen-accent-size: 1em;

    /* ---- Glass material ---- */
    /* glass-1 has no blur of its own (glass budget), so its tint is a touch denser. Night: 0.64 (was
     0.56), as segmented-control labels over a bright orb measured 4.1:1. */
    --sheen-glass-1-bg: light-dark(oklch(100% 0 0 / 0.58), oklch(15% 0.035 285 / 0.64));
    /* Text-heavy cards: a touch denser than the hero slab, so captions hold AA on any wallpaper
     (dark: the sidebar's muted links over a bright orb measured 4.4:1 at 0.56; 0.64 gives 5+). */
    --sheen-glass-2-bg: light-dark(oklch(100% 0 0 / 0.6), oklch(15% 0.035 285 / 0.7));
    --sheen-glass-3-bg: light-dark(oklch(99.5% 0.006 300 / 0.64), oklch(15% 0.03 285 / 0.72));
    --sheen-glass-1-blur: 14px;
    --sheen-glass-2-blur: 20px;
    --sheen-glass-3-blur: 28px;
    --sheen-glass-saturate: 190%;
    --sheen-glass-brightness: 1.05;
    --sheen-glass-border: light-dark(oklch(100% 0 0 / 0.7), oklch(100% 0 0 / 0.14));
    --sheen-glass-highlight: light-dark(oklch(100% 0 0 / 0.95), oklch(100% 0 0 / 0.34));
    --sheen-glass-highlight-side: light-dark(oklch(100% 0 0 / 0.55), oklch(100% 0 0 / 0.1));
    --sheen-glass-lowlight: light-dark(oklch(100% 0 0 / 0.5), oklch(100% 0 0 / 0.09));
    --sheen-glass-edge: light-dark(oklch(100% 0 0 / 0.5), oklch(100% 0 0 / 0.09));
    --sheen-glass-glow: light-dark(oklch(100% 0 0 / 0.6), oklch(100% 0 0 / 0.08));
    --sheen-glass-specular: linear-gradient(
      180deg,
      light-dark(oklch(100% 0 0 / 0.5), oklch(100% 0 0 / 0.08)),
      transparent 55%
    );
    --sheen-glass-sheen: light-dark(oklch(100% 0 0 / 0.75), oklch(100% 0 0 / 0.12));
    /* Inner light: the lit top lip, the light lower lip, and a tint of the wallpaper inside. */
    --sheen-glass-inner-tint: light-dark(oklch(88% 0.09 330 / 0.4), oklch(62% 0.24 330 / 0.24));
    /* Shadows: a tight contact shadow, a soft drop, and a coloured cast (light through tinted glass). */
    --sheen-shadow-near: light-dark(oklch(35% 0.08 290 / 0.1), oklch(0% 0 0 / 0.35));
    --sheen-shadow-far: light-dark(oklch(40% 0.12 300 / 0.2), oklch(4% 0.02 285 / 0.6));
    --sheen-shadow-cast: light-dark(oklch(68% 0.19 330 / 0.32), oklch(55% 0.25 320 / 0.32));
    --sheen-glass-1-shadow: 0 1px 2px var(--sheen-shadow-near), 0 8px 20px -10px var(--sheen-shadow-far);
    --sheen-glass-2-shadow: 0 1px 2px var(--sheen-shadow-near), 0 26px 52px -22px var(--sheen-shadow-far);
    --sheen-glass-3-shadow:
      0 2px 4px var(--sheen-shadow-near), 0 30px 60px -22px var(--sheen-shadow-far),
      0 56px 100px -44px var(--sheen-shadow-cast);
    /* Order matters: lit top lip, lower lip, hairline edge, inner glow, wallpaper tint, then depth. */
    --sheen-glass-1-box:
      inset 0 1px 0.5px var(--sheen-glass-highlight), inset 0 -1px 0.5px var(--sheen-glass-lowlight),
      inset 0 8px 14px -10px var(--sheen-glass-glow), var(--sheen-glass-1-shadow);
    --sheen-glass-2-box:
      inset 0 1px 0.5px var(--sheen-glass-highlight), inset 0 -1px 0.5px var(--sheen-glass-lowlight),
      inset 0 0 0 1px var(--sheen-glass-edge), inset 0 26px 36px -28px var(--sheen-glass-glow),
      inset 0 -30px 44px -32px var(--sheen-glass-inner-tint), var(--sheen-glass-2-shadow),
      0 56px 100px -44px var(--sheen-shadow-cast);
    --sheen-glass-3-box:
      inset 0 1px 0.5px var(--sheen-glass-highlight), inset 0 -1px 0.5px var(--sheen-glass-lowlight),
      inset 0 0 0 1px var(--sheen-glass-edge), inset 0 26px 36px -28px var(--sheen-glass-glow),
      inset 0 -30px 44px -32px var(--sheen-glass-inner-tint), var(--sheen-glass-3-shadow);
    --sheen-surface-solid: light-dark(oklch(100% 0 0), oklch(20% 0.035 285));

    /* ---- Rim light: a hot core where the light is, a broad lit side, a prism either side, a
     counter-rim opposite (a dark edge by day, a faint internal reflection at night). ---- */
    --sheen-rim-width: 1.5px;
    --sheen-rim-core: oklch(100% 0 0);
    --sheen-rim-glow: light-dark(oklch(100% 0 0 / 0.8), oklch(100% 0 0 / 0.7));
    --sheen-rim-hot: oklch(100% 0 0);
    --sheen-rim-fall: light-dark(oklch(100% 0 0 / 0.62), oklch(100% 0 0 / 0.42));
    --sheen-rim-base: light-dark(oklch(100% 0 0 / 0.34), oklch(100% 0 0 / 0.1));
    --sheen-rim-counter: light-dark(oklch(25% 0.05 290 / 0.22), oklch(100% 0 0 / 0.06));
    --sheen-rim-iri-a: light-dark(oklch(84% 0.12 215), oklch(84% 0.12 212 / 0.8));
    --sheen-rim-iri-b: light-dark(oklch(80% 0.15 345), oklch(78% 0.17 348 / 0.8));
    --sheen-glass-spot: light-dark(oklch(100% 0 0 / 0.55), oklch(100% 0 0 / 0.1));

    /* ---- Backdrop colours (backgrounds.css blobs, preview stages) ---- */
    --sheen-blob-1: light-dark(oklch(78% 0.15 295 / 0.6), oklch(48% 0.24 292 / 0.55));
    --sheen-blob-2: light-dark(oklch(86% 0.11 212 / 0.75), oklch(50% 0.14 215 / 0.45));
    --sheen-blob-3: light-dark(oklch(81% 0.15 352 / 0.6), oklch(50% 0.24 350 / 0.45));
    --sheen-blob-4: light-dark(oklch(80% 0.12 255 / 0.55), oklch(46% 0.22 264 / 0.45));
    --sheen-blob-5: light-dark(oklch(94% 0.06 70 / 0.55), oklch(34% 0.12 300 / 0.3));
    --sheen-backdrop-grid: light-dark(oklch(40% 0.08 300 / 0.05), oklch(100% 0 0 / 0.035));

    /* ---- Motion intensity: thick glass, slow light ---- */
    --sheen-motion-intensity: 1;
    --sheen-duration-ambient: 34s;
  }

  /* Non-colour values per theme (light-dark() only takes colours). */
  :root:not([data-sheen-style="aurora"])[data-theme="dark"] {
    --sheen-glass-saturate: 190%;
    --sheen-glass-brightness: 0.96;
  }

  @media (prefers-color-scheme: dark) {
    :root:not([data-sheen-style="aurora"]):not([data-theme="light"]) {
      --sheen-glass-saturate: 190%;
      --sheen-glass-brightness: 0.96;
    }
  }

  :root:not([data-sheen-style="aurora"])[data-theme="light"] {
    --sheen-glass-saturate: 190%;
    --sheen-glass-brightness: 1.05;
  }

  /* Phones: smaller blur kernels (cheaper, and small panes read better with less frost). */
  @media (max-width: 639px) {
    :root:not([data-sheen-style="aurora"]) {
      --sheen-glass-1-blur: 10px;
      --sheen-glass-2-blur: 14px;
      --sheen-glass-3-blur: 20px;
    }
  }

  /*
 * The Liquid rim (the "glass catches light" signature), in each surface's ::after:
 *   1. hot core: a white-hot spot on the edge nearest the pointer (grows on a fast flick)
 *   2. broad rim: the side facing the light (--sheen-ra) is lit, prism tints either side, a
 *      counter-rim on the far side
 *   3. inner light: a soft spot inside the glass under the pointer, behind the content
 * At rest (touch, reduced motion, pointer far away) the light sits at the top-left.
 */
  :root:not([data-sheen-style="aurora"]) :is(.glass-1, .glass-2, .glass-3)::after {
    background-image:
      radial-gradient(
        circle calc(150px * var(--sheen-flare)) at var(--sheen-mx) var(--sheen-my),
        color-mix(in oklab, var(--sheen-rim-core) calc(clamp(0, (var(--sheen-lit) - 0.3) * 1.6, 1) * 100%), transparent)
          0%,
        color-mix(in oklab, var(--sheen-rim-core) calc(clamp(0, (var(--sheen-lit) - 0.3) * 1.6, 1) * 100%), transparent)
          18%,
        color-mix(in oklab, var(--sheen-rim-glow) calc(clamp(0, (var(--sheen-lit) - 0.3) * 1.6, 1) * 100%), transparent)
          40%,
        transparent 74%
      ),
      conic-gradient(
        from var(--sheen-ra),
        var(--sheen-rim-hot) 0deg,
        var(--sheen-rim-fall) 22deg,
        var(--sheen-rim-iri-a) 36deg,
        var(--sheen-rim-base) 66deg,
        var(--sheen-rim-base) 140deg,
        var(--sheen-rim-counter) 180deg,
        var(--sheen-rim-base) 220deg,
        var(--sheen-rim-base) 294deg,
        var(--sheen-rim-iri-b) 324deg,
        var(--sheen-rim-fall) 338deg,
        var(--sheen-rim-hot) 360deg
      ),
      radial-gradient(circle 240px at var(--sheen-mx) var(--sheen-my), var(--sheen-glass-spot), transparent 70%);
    background-clip: border-area, border-area, padding-box;
    opacity: calc(0.3 + var(--sheen-lit) * 0.7);
  }

  :root:not([data-sheen-style="aurora"])[data-sheen-flare] [data-sheen-lit]::after {
    --sheen-flare: 1.25;
  }

  /* Small controls (glass-1) carry a thinner rim. */
  :root:not([data-sheen-style="aurora"]) .glass-1::after {
    --sheen-rim-width: 1px;
  }
}

@layer sheen {
  /*
 * SheenUI design tokens.
 *
 * Three tiers:
 *   1. Primitives  (--sheen-ink-*, --sheen-violet-*, --sheen-teal-*): raw OKLCH values
 *   2. Semantics   (--sheen-bg, --sheen-fg, --sheen-accent, ...): what a value is FOR
 *   3. Component   (--sheen-glass-*, in glass.css; --sheen-blob-*, in backgrounds.css)
 *
 * Components use tier 2 (or 3), never raw colours. Every semantic colour is exposed to
 * Tailwind in index.css: --sheen-accent-soft → bg-sheen-accent-soft, and so on.
 *
 * Light/dark is resolved by `color-scheme` + `light-dark()`:
 *   - no attribute            → follows the OS
 *   - [data-theme="light"]    → forced light
 *   - [data-theme="dark"]     → forced dark
 *
 * Contrast (WCAG 2), measured in the browser. "flat" is against plain --sheen-bg. Every other
 * column is the WORST case: the brightest backdrop blob peak, with the demo Stage's extra blobs
 * on top, at 1440 and 390 wide, as the mean of a chip-sized (92x26) patch.
 *   blob = straight on the backdrop   g1 / g2 = on glass-1 / glass-2
 *   tint = on its own *-soft tint straight on the backdrop   tint/g1 = that tint over glass-1
 * Text needs 4.5:1 (light status text aims for 5:1). Light text tokens were darkened a step (fg-muted L31%, fg-subtle L35%, accent L38-39%, danger-text L36%) after a pixel-by-pixel audit found single worst pixels at 3.5-4.4:1 over Aurora light's brightest backdrop; the table below predates that and understates the light columns; focus and edges need 3:1. Rounded down.
 *
 *                 light: flat  blob   g1   g2 tint tint/g1   dark: flat  blob   g1   g2 tint tint/g1
 *   fg-subtle            6.8   4.5  5.5  5.9                       8.9   4.6  5.4  5.7
 *   fg-muted             7.8   5.2  6.3  6.7                      10.5   5.5  6.4  6.7
 *   accent               7.4   5.0  6.0  6.5  4.6   5.5            9.9   5.2  6.0  6.3  4.6   5.2
 *   success-text         8.3   5.6  6.7  7.2  5.1   6.0           12.4   6.5  7.6  7.9  5.2   6.0
 *   danger-text          8.8   5.9  7.1  7.6  5.2   6.2           10.3   5.4  6.3  6.6  4.8   5.5
 *   warning-text         8.3   5.6  6.7  7.2  5.2   6.1           12.7   6.7  7.8  8.2  5.5   6.3
 *   focus                6.6   4.4  5.3  5.7                       7.9   4.1  4.8  5.1
 *
 * Edges (non-text, 3:1): a 1px edge of a glass-1 control vs the backdrop just outside it, worst
 * single point over the blob peaks (same conditions as above).
 *                 light: flat  blob   dark: flat  blob
 *   control-border       5.2   3.1          7.0   3.6
 *   danger-border        5.8   3.4          7.6   3.9
 *   success-border       5.3   3.2         10.8   5.6
 * The base light --sheen-danger / --sheen-success reach only ~2.1 / ~1.5 there: never use them as
 * a control edge. Rendered pages were audited pixel-by-pixel too (text and edges over real blobs
 * and glass): all pass.
 */

  :root,
  [data-theme] {
    color-scheme: light dark;

    /* ---------- 1. Primitives ---------- */
    --sheen-ink-0: oklch(100% 0 0);
    --sheen-ink-50: oklch(98.5% 0.004 270);
    --sheen-ink-100: oklch(96.5% 0.006 270);
    --sheen-ink-200: oklch(92% 0.01 270);
    --sheen-ink-300: oklch(86% 0.014 270);
    --sheen-ink-350: oklch(79% 0.016 270);
    --sheen-ink-400: oklch(72% 0.02 270);
    --sheen-ink-500: oklch(55% 0.025 270);
    --sheen-ink-550: oklch(46% 0.025 270);
    --sheen-ink-600: oklch(43% 0.025 270);
    --sheen-ink-700: oklch(32% 0.025 270);
    --sheen-ink-800: oklch(22% 0.022 270);
    --sheen-ink-900: oklch(16% 0.02 270);
    --sheen-ink-950: oklch(11% 0.018 270);

    --sheen-violet-300: oklch(80% 0.11 285);
    --sheen-violet-400: oklch(72% 0.15 285);
    --sheen-violet-500: oklch(62% 0.19 285);
    --sheen-violet-600: oklch(53% 0.2 285);
    --sheen-violet-700: oklch(49% 0.21 285);

    --sheen-teal-300: oklch(87% 0.1 185);
    --sheen-teal-400: oklch(80% 0.13 185);
    --sheen-teal-500: oklch(70% 0.13 185);
    --sheen-teal-600: oklch(58% 0.11 185);

    --sheen-rose-400: oklch(72% 0.16 15);
    --sheen-rose-500: oklch(64% 0.2 20);
    --sheen-rose-700: oklch(50% 0.18 25);
    --sheen-amber-400: oklch(83% 0.14 80);
    --sheen-amber-500: oklch(65% 0.15 70);
    --sheen-amber-700: oklch(48% 0.11 60);
    --sheen-green-400: oklch(78% 0.15 155);
    --sheen-green-500: oklch(68% 0.16 155);
    --sheen-green-700: oklch(46% 0.12 155);

    /* ---------- 2. Semantics ---------- */
    --sheen-bg: light-dark(var(--sheen-ink-50), var(--sheen-ink-950));
    --sheen-fg: light-dark(var(--sheen-ink-900), var(--sheen-ink-50));
    --sheen-fg-muted: light-dark(var(--sheen-ink-600), var(--sheen-ink-350));
    /* Captions, placeholders, group labels. Still body-text contrast (>= 4.5:1), on glass too.
     Dark sits 2 L above ink-400: at 72% it fell to ~4.3:1 on a demo Stage over the violet blob. */
    --sheen-fg-subtle: light-dark(var(--sheen-ink-550), oklch(74% 0.02 270));
    --sheen-border: light-dark(oklch(20% 0.02 270 / 0.1), oklch(100% 0 0 / 0.1));

    /* Accent text sits a step past the brand violet (deeper in light, paler in dark), so it clears
     4.5:1 on its own soft tint even straight over the violet backdrop blob, the worst case. */
    --sheen-accent: light-dark(oklch(46% 0.2 285), oklch(78% 0.125 285));
    --sheen-accent-2: light-dark(var(--sheen-teal-600), var(--sheen-teal-400));
    --sheen-accent-fg: var(--sheen-ink-0);
    /* Accent tint for chips, badges, selected rows. --sheen-accent text stays >= 4.5:1 on it.
     Kept faint: a stronger tint pulls the background toward the text colour. */
    --sheen-accent-soft: light-dark(oklch(53% 0.2 285 / 0.08), oklch(72% 0.15 285 / 0.09));
    --sheen-accent-border: light-dark(oklch(53% 0.2 285 / 0.3), oklch(72% 0.15 285 / 0.35));
    /* Decorative gradient (brand text, blobs): not for backgrounds behind text. */
    --sheen-accent-gradient: linear-gradient(135deg, var(--sheen-violet-500), var(--sheen-teal-500));
    /* Gradient for filled controls: dark enough for white text to pass WCAG AA (4.5:1).
     Elements filled with it should also carry the .sheen-fill class (Windows High Contrast). */
    --sheen-accent-fill: linear-gradient(135deg, oklch(52% 0.21 285), oklch(50% 0.16 250));
    /* Coloured glow under accent-filled controls (primary button, slider value bubble). */
    --sheen-accent-glow: oklch(52% 0.21 285 / 0.8);
    /* Lit top edge + glow for a solid accent-filled button. */
    --sheen-accent-fill-shadow: inset 0 1px 0 oklch(100% 0 0 / 0.25), 0 8px 24px -10px var(--sheen-accent-glow);
    /* Destructive fill (danger button). White text >= 5.6:1 across the whole gradient.
     --sheen-danger-solid is the same red as one colour: the background-color under the gradient. */
    --sheen-danger-fill: linear-gradient(135deg, oklch(54% 0.2 22), oklch(48% 0.19 12));
    --sheen-danger-solid: oklch(51% 0.2 17);
    --sheen-danger-fill-shadow: inset 0 1px 0 oklch(100% 0 0 / 0.2), 0 8px 24px -10px oklch(55% 0.2 20 / 0.8);
    /* Coloured glow under the danger button (its --sheen-glow-color). */
    --sheen-danger-glow: oklch(58% 0.22 25 / 0.6);
    /* Coloured glows of the success and warning states (a status light behind a toast, a stage, a verified seal).
     With --sheen-accent-glow and --sheen-danger-glow they are the four state lights. */
    --sheen-success-glow: oklch(66% 0.17 155 / 0.6);
    --sheen-warning-glow: oklch(76% 0.16 75 / 0.55);

    /* Interaction */
    /* Row / item hover and keyboard-highlighted background (menus, lists, tables). */
    --sheen-hover: light-dark(oklch(30% 0.03 275 / 0.07), oklch(100% 0 0 / 0.08));
    /* Solid focus colour (>= 3:1 on bg and glass): outline-2 outline-offset-2 outline-sheen-focus. */
    --sheen-focus: light-dark(var(--sheen-violet-700), var(--sheen-violet-400));
    /* Soft halo that can sit around the solid focus outline. Decorative only. */
    --sheen-ring: light-dark(oklch(53% 0.2 285 / 0.45), oklch(72% 0.15 285 / 0.55));
    --sheen-selection: light-dark(oklch(62% 0.19 285 / 0.28), oklch(72% 0.15 285 / 0.38));

    /* Status: the base colour is for dots, fills and icons that sit next to a word saying the same
     thing. In light mode it is not a 3:1 graphic on its own (flat --sheen-bg: danger 3.5, warning
     3.2, success 2.5; less over the blobs). *-text is for words (and icons that stand alone);
     *-soft is the tinted background they sit on; *-border is the edge of an invalid / valid
     control (below). */
    --sheen-success: light-dark(var(--sheen-green-500), var(--sheen-green-400));
    --sheen-danger: light-dark(var(--sheen-rose-500), var(--sheen-rose-400));
    --sheen-warning: light-dark(var(--sheen-amber-500), var(--sheen-amber-400));

    /* Words. Light text sits below the -700 primitives and dark text above the -400 ones, so it
     keeps >= 5:1 (light) / >= 4.5:1 (dark) on its -soft tint even straight over the brightest
     backdrop blob, and on glass-1/2/3 with or without the tint. */
    --sheen-success-text: light-dark(oklch(40% 0.105 155), oklch(82% 0.145 155));
    --sheen-danger-text: light-dark(oklch(36% 0.15 25), oklch(84% 0.11 18));
    --sheen-warning-text: light-dark(oklch(42% 0.095 60), oklch(85% 0.135 80));

    /* Dark tints are fainter than light ones: a light tint over dark glass lifts the background
     toward the (light) text colour. */
    --sheen-success-soft: light-dark(oklch(68% 0.16 155 / 0.14), oklch(78% 0.15 155 / 0.11));
    --sheen-danger-soft: light-dark(oklch(64% 0.2 20 / 0.12), oklch(72% 0.16 15 / 0.11));
    --sheen-warning-soft: light-dark(oklch(80% 0.15 75 / 0.22), oklch(83% 0.14 80 / 0.11));

    /* Edge of an invalid (danger) or confirmed (success) control: the status twin of
     --sheen-control-border, >= 3:1 against glass-1 over the brightest blob, light and dark
     (WCAG 1.4.11). The base light colours are too pale for a 1px edge on a light backdrop
     (~2.1:1 danger, ~1.5:1 success). Unlike the decorative --sheen-accent-border, these are solid. */
    --sheen-danger-border: light-dark(oklch(52% 0.19 22), var(--sheen-rose-400));
    --sheen-success-border: light-dark(oklch(50% 0.13 155), var(--sheen-green-400));

    /* Expanding success ring (keyframes sheen-ripple). */
    --sheen-success-ring: light-dark(oklch(68% 0.16 155 / 0.55), oklch(78% 0.15 155 / 0.5));

    /* ---------- Controls ---------- */
    /* Boundary of small form controls (checkbox, switch and slider tracks, text fields, select
     triggers): >= 3:1 against the page, glass and the demo stages, light and dark (WCAG 1.4.11).
     Only controls use it: cards and panels keep the soft --sheen-glass-border. */
    --sheen-control-border: light-dark(oklch(52% 0.03 275), oklch(68% 0.03 275));
    /* Thumbs of switches and sliders, and their shadows (resting in a track / floating above one).
     In light mode a white thumb is ~1.1:1 against a light track and page, so the shadows carry a
     1px control-border ring: the thumb is the only position cue on a slider at its minimum. */
    --sheen-thumb: oklch(100% 0 0);
    /* Fixed ink for text and marks drawn on a data fill whose colour is only known at run time (a heatmap cell, a
     treemap tile): the chart picks one by contrast, so neither follows the theme. "on-dark" is the light ink for dark
     fills, "on-light" the dark ink for light fills. */
    --sheen-ink-on-dark: oklch(100% 0 0);
    --sheen-ink-on-light: oklch(0% 0 0);
    --sheen-thumb-ring: light-dark(var(--sheen-control-border), transparent);
    --sheen-thumb-shadow:
      0 0 0 1px var(--sheen-thumb-ring), 0 1px 3px oklch(0% 0 0 / 0.3), inset 0 -1px 0 oklch(0% 0 0 / 0.08);
    --sheen-thumb-shadow-raised:
      0 0 0 1px var(--sheen-thumb-ring), 0 2px 6px oklch(0% 0 0 / 0.35), inset 0 -1px 0 oklch(0% 0 0 / 0.08);
    /* The sliding "selected" pill under the active tab. */
    --sheen-indicator: light-dark(oklch(100% 0 0 / 0.95), oklch(100% 0 0 / 0.14));
    --sheen-indicator-shadow: inset 0 1px 0 oklch(100% 0 0 / 0.4), 0 2px 10px -2px oklch(20% 0.03 275 / 0.25);
    /* Dims the page behind modal surfaces (dialog, alert dialog, drawer). Deeper in dark mode,
     where a light veil would barely show. */
    --sheen-scrim: light-dark(oklch(15% 0.02 275 / 0.35), oklch(6% 0.015 275 / 0.6));
    /* Text laid over an arbitrary image (carousel captions): a fixed dark scrim and light text, the same in every
     look because a photo does not follow the theme. Light text over the scrim over pure white stays >= 9:1. */
    --sheen-image-scrim: oklch(14% 0.02 275 / 0.82);
    --sheen-on-image: oklch(100% 0 0);

    /* ---------- Code (CodeBlock syntax colours) ----------
   * Every colour keeps >= 4.5:1 on the code block's glass (levels 1-3), plain and on its
   * highlighted, added and removed line tints, in light and dark, over the brightest backdrop
   * blob with the demo Stage blobs on top (worst pixel: 4.6, light, danger tint on glass-1).
   * Light L 43-47%, dark L 81-86%: hue carries the meaning, lightness the contrast.
   * Line numbers: fg-subtle on plain lines, fg-muted on tinted ones, accent on marked ones (>= 4.8).
   */
    --sheen-code-keyword: light-dark(oklch(46% 0.2 300), oklch(83% 0.11 300));
    --sheen-code-string: light-dark(oklch(45% 0.11 155), oklch(84% 0.12 155));
    --sheen-code-number: light-dark(oklch(47% 0.12 55), oklch(85% 0.11 70));
    --sheen-code-literal: light-dark(oklch(47% 0.16 30), oklch(83% 0.1 35));
    --sheen-code-function: light-dark(oklch(46% 0.15 255), oklch(83% 0.09 250));
    --sheen-code-type: light-dark(oklch(45% 0.08 195), oklch(85% 0.09 190));
    --sheen-code-tag: light-dark(oklch(47% 0.17 10), oklch(83% 0.1 10));
    --sheen-code-attr: light-dark(oklch(46% 0.11 75), oklch(86% 0.1 85));
    --sheen-code-property: light-dark(oklch(45% 0.12 230), oklch(84% 0.08 230));
    --sheen-code-variable: light-dark(oklch(46% 0.17 340), oklch(83% 0.1 340));
    --sheen-code-comment: light-dark(oklch(46% 0.02 270), oklch(81% 0.02 270));
    --sheen-code-punctuation: light-dark(oklch(43% 0.02 270), oklch(84% 0.015 270));

    /* ---------- Charts ----------
   * Categorical slots, assigned in this fixed order (never cycled past 8).
   * Validated with the data-viz palette checks (lightness band, chroma floor,
   * colour-blind separation of adjacent slots, normal-vision floor) against
   * SheenUI's light (#f6f6fa) and dark (#1d1e29) surfaces: all checks pass.
   * Slots 2–5 sit below 3:1 on the light surface, so every chart ships a table view.
   */
    --sheen-chart-1: light-dark(#4a3aa7, #9085e9); /* violet */
    --sheen-chart-2: light-dark(#eb6834, #d95926); /* orange */
    --sheen-chart-3: light-dark(#1baf7a, #199e70); /* aqua */
    --sheen-chart-4: light-dark(#eda100, #c98500); /* yellow */
    --sheen-chart-5: light-dark(#e87ba4, #d55181); /* magenta */
    --sheen-chart-6: light-dark(#008300, #008300); /* green */
    --sheen-chart-7: light-dark(#2a78d6, #3987e5); /* blue */
    --sheen-chart-8: light-dark(#e34948, #e66767); /* red */
    /* Surface colour used for the 2px gaps between marks and rings around dots. */
    --sheen-chart-surface: light-dark(#f6f6fa, #1d1e29);
    --sheen-chart-grid: light-dark(oklch(20% 0.02 270 / 0.09), oklch(100% 0 0 / 0.08));

    /* ---------- Shape & type ---------- */
    --sheen-radius-sm: 0.625rem;
    --sheen-radius-md: 0.875rem;
    --sheen-radius-lg: 1.25rem;
    --sheen-radius-xl: 1.75rem;
    --sheen-radius-full: 999px;

    /* ---------- Control heights ----------
     ONE scale for buttons and form fields, so a Button beside an Input lines up at every size.
     Touch screens (any coarse pointer) grow sm and md to 44px so the 44px target gate holds without hit-area tricks. */
    --sheen-control-h-sm: 2rem;
    --sheen-control-h-md: 2.5rem;
    --sheen-control-h-lg: 3rem;

    --sheen-font-sans: "Inter Variable", "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
    --sheen-font-mono: "JetBrains Mono Variable", "JetBrains Mono", "JetBrains Mono Fallback", ui-monospace, "SF Mono", Menlo, Consolas, monospace;

    /* ---------- Style layer contract ----------
   * Tokens every style preset (styles/presets/*.css) defines for its look. These are the
   * neutral defaults; the presets re-point them, light and dark.
   */
    /* Second page colour: the backdrop's gradient runs from --sheen-bg to this. */
    --sheen-bg-2: var(--sheen-bg);
    /* Six decorative colours of the style (backdrop light, rims, casts). Never behind text
     without glass. 1 violet · 2 magenta · 3 warm · 4 gold · 5 cyan · 6 blue (by role). */
    --sheen-spectrum-1: var(--sheen-violet-500);
    --sheen-spectrum-2: var(--sheen-rose-500);
    --sheen-spectrum-3: var(--sheen-amber-400);
    --sheen-spectrum-4: var(--sheen-amber-400);
    --sheen-spectrum-5: var(--sheen-teal-500);
    --sheen-spectrum-6: oklch(62% 0.17 255);
    /* Gradient for display TEXT (the hero accent phrase, brand words): every stop keeps large-text
     AA (>= 3:1, in practice >= 4.5:1) on the page, light and dark. */
    --sheen-text-gradient: linear-gradient(100deg, var(--sheen-accent), var(--sheen-accent-2));
    /* Display type: headings and the hero. The accent face is used for ONE word or phrase. */
    --sheen-font-display: var(--sheen-font-sans);
    --sheen-font-accent: var(--sheen-font-display);
    --sheen-display-weight: 650;
    --sheen-display-tracking: -0.03em;
    --sheen-accent-style: normal;
    --sheen-accent-weight: var(--sheen-display-weight);
    --sheen-accent-size: 1em;
  }

  [data-theme="light"] {
    color-scheme: light;
  }

  [data-theme="dark"] {
    color-scheme: dark;
  }

  @media (any-pointer: coarse) {
    :root {
      --sheen-hit-size: 2.75rem;
      --sheen-control-h-sm: 2.75rem;
      --sheen-control-h-md: 2.75rem;
    }
  }
}
